INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4b53498f-aac3-5735-aa0d-1949be2750d2', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 45, 45, 'A foreigner and a hired servant shall not eat of it.'),
  ('ba3de5d0-4bc3-5be9-a7c6-df1d4253c336', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 46, 46, 'In one house shall it be eaten; you shall not carry forth anything of the flesh abroad out of the house; neither shall you break a bone of it.'),
  ('552ebd41-05c2-5ba7-a56c-3b1f0cd248a9', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 47, 47, 'All the congregation of Israel shall keep it.'),
  ('c822a060-234e-5fc0-aa11-58c90f3b87e5', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 48, 48, 'When a stranger shall live as a foreigner with you, and will keep the Passover to Yahweh, let all his males be circumcised, and then let him come near and keep it; and he shall be as one who is born in the land: but no uncircumcised person shall eat of it.'),
  ('f7807e30-6e1d-5fac-ad8e-e1804a6ea72c', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 49, 49, 'One law shall be to him who is born at home, and to the stranger who lives as a foreigner among you."'),
  ('5771c2bf-1dd5-59be-aa55-977b8f475714', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 50, 50, 'All the children of Israel did so. As Yahweh commanded Moses and Aaron, so they did.'),
  ('e0146b05-ad3d-5e76-a47d-0ceb85f55357', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 51, 51, 'It happened the same day, that Yahweh brought the children of Israel out of the land of Egypt by their armies.'),
  ('022531b0-130a-5f7e-a1d6-34509174c82b', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('69525b99-986c-530f-a5b8-2bef749ffe92', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 2, 2, '"Sanctify to me all of the firstborn, whatever opens the womb among the children of Israel, both of man and of animal. It is mine."'),
  ('852c711e-f424-516c-a7a0-f5eb4fb7ceac', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 3, 3, 'Moses said to the people, "Remember this day, in which you came out from Egypt, out of the house of bondage; for by strength of hand Yahweh brought you out from this place. No leavened bread shall be eaten.'),
  ('2e2f700a-55ac-5592-a878-e5fe264c4b7b', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 4, 4, 'This day you go forth in the month Abib.'),
  ('d9fbac8f-1576-5d93-ad6d-fae7991d5713', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 5, 5, 'It shall be, when Yahweh shall bring you into the land of the Canaanite, and the Hittite, and the Amorite, and the Hivite, and the Jebusite, which he swore to your fathers to give you, a land flowing with milk and honey, that you shall keep this service in this month.'),
  ('a6ebaee7-5807-5c09-a241-0c72dc0320d7', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 6, 6, 'Seven days you shall eat unleavened bread, and in the seventh day shall be a feast to Yahweh.'),
  ('3158f03a-3913-5ba2-ab7a-5e2715040cd6', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 7, 7, 'Unleavened bread shall be eaten throughout the seven days; and no leavened bread shall be seen with you, neither shall there be yeast seen with you, in all your borders.'),
  ('001b05b6-558a-594e-a5ee-b74186a3c8c9', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 8, 8, 'You shall tell your son in that day, saying, ''It is because of that which Yahweh did for me when I came forth out of Egypt.'''),
  ('c234700b-43d5-5660-aa3d-b8046e55c7a9', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 9, 9, 'It shall be for a sign to you on your hand, and for a memorial between your eyes, that the law of Yahweh may be in your mouth; for with a strong hand Yahweh has brought you out of Egypt.'),
  ('92681dbc-3ffb-5daa-aed4-84cebe4c9bf3', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 10, 10, 'You shall therefore keep this ordinance in its season from year to year.'),
  ('619dbc22-75f3-5989-ac9e-ab98478fa7b4', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 11, 11, '"It shall be, when Yahweh shall bring you into the land of the Canaanite, as he swore to you and to your fathers, and shall give it you,'),
  ('39694238-ee48-5b06-a3b9-9037e112a473', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 12, 12, 'that you shall set apart to Yahweh all that opens the womb, and every firstborn which you have that comes from an animal. The males shall be Yahweh''s.'),
  ('af44da26-dc3d-5fcd-a40d-5cff5a4db65c', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 13, 13, 'Every firstborn of a donkey you shall redeem with a lamb; and if you will not redeem it, then you shall break its neck; and you shall redeem all the firstborn of man among your sons.'),
  ('911978c2-0b90-5839-ae2c-50bf12718e3e', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 14, 14, 'It shall be, when your son asks you in time to come, saying, ''What is this?'' that you shall tell him, ''By strength of hand Yahweh brought us out from Egypt, from the house of bondage;'),
  ('9bddde12-422c-5a72-a084-cd9867fd3cd0', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 15, 15, 'and it happened, when Pharaoh would hardly let us go, that Yahweh killed all the firstborn in the land of Egypt, both the firstborn of man, and the firstborn of animal. Therefore I sacrifice to Yahweh all that opens the womb, being males; but all the firstborn of my sons I redeem.'''),
  ('356b1feb-0415-5825-ab0f-2592b42b5cb4', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 16, 16, 'It shall be for a sign on your hand, and for symbols between your eyes: for by strength of hand Yahweh brought us forth out of Egypt."'),
  ('e24b277f-90f7-55c4-a96f-e241b7f1f1b9', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 17, 17, 'It happened, when Pharaoh had let the people go, that God didn''t lead them by the way of the land of the Philistines, although that was near; for God said, "Lest perhaps the people change their minds when they see war, and they return to Egypt;"'),
  ('4bbbcf6e-e3a3-55b7-a444-47e75d7a73f6', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 18, 18, 'but God led the people around by the way of the wilderness by the Red Sea; and the children of Israel went up armed out of the land of Egypt.'),
  ('c7cdc3dc-e6e8-5b90-a6ba-f3da60b08e32', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 19, 19, 'Moses took the bones of Joseph with him, for he had made the children of Israel swear, saying, "God will surely visit you, and you shall carry up my bones away from here with you."'),
  ('d40a2ba6-b059-5d57-a40d-8cd2089be666', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 20, 20, 'They took their journey from Succoth, and encamped in Etham, in the edge of the wilderness.'),
  ('f9591e60-250e-5dc6-a438-65f06c5bf814', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 21, 21, 'Yahweh went before them by day in a pillar of cloud, to lead them on their way, and by night in a pillar of fire, to give them light, that they might go by day and by night:'),
  ('802798a0-886c-53c4-a357-de1225806928', '7a3d870c-cd8e-5e1e-a756-2c4914efbb06', NULL, 22, 22, 'the pillar of cloud by day, and the pillar of fire by night, didn''t depart from before the people.'),
  ('91678d30-e228-5f65-a80b-1e8b389821ea', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('f2869f6f-c769-5eae-a3ba-2aa517e6f905', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 2, 2, '"Speak to the children of Israel, that they turn back and encamp before Pihahiroth, between Migdol and the sea, before Baal Zephon. You shall encamp opposite it by the sea.'),
  ('e8acb4d7-84bf-5be8-acbf-51eb3471c86c', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 3, 3, 'Pharaoh will say of the children of Israel, ''They are entangled in the land. The wilderness has shut them in.'''),
  ('c6556ad0-2cf9-5520-a156-2e6f78eef2a2', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 4, 4, 'I will harden Pharaoh''s heart, and he will follow after them; and I will get honor over Pharaoh, and over all his armies; and the Egyptians shall know that I am Yahweh." They did so.'),
  ('ba8de133-dfd0-53ab-a1f0-bc7380ae9e6f', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 5, 5, 'It was told the king of Egypt that the people had fled; and the heart of Pharaoh and of his servants was changed towards the people, and they said, "What is this we have done, that we have let Israel go from serving us?"'),
  ('396dc243-5bbb-59fe-a6bf-687c902602c2', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 6, 6, 'He prepared his chariot, and took his army with him;'),
  ('6dc96d02-23d0-5b83-a02a-b87881fb2217', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 7, 7, 'and he took six hundred chosen chariots, and all the chariots of Egypt, and captains over all of them.'),
  ('ecc5e964-5589-538a-acf8-464b2f30449e', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 8, 8, 'Yahweh hardened the heart of Pharaoh king of Egypt, and he pursued after the children of Israel; for the children of Israel went out with a high hand.'),
  ('1494a1db-68ec-5ed1-a3a6-1c2e4680f59f', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 9, 9, 'The Egyptians pursued after them: all the horses and chariots of Pharaoh, his horsemen, and his army; and overtook them encamping by the sea, beside Pihahiroth, before Baal Zephon.'),
  ('ef1b6c48-5f8b-507e-a1a8-c3a7e11e5dc4', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 10, 10, 'When Pharaoh drew near, the children of Israel lifted up their eyes, and behold, the Egyptians were marching after them; and they were very afraid. The children of Israel cried out to Yahweh.'),
  ('adda753e-adc5-5d26-a689-d0007923880f', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 11, 11, 'They said to Moses, "Because there were no graves in Egypt, have you taken us away to die in the wilderness? Why have you treated us this way, to bring us forth out of Egypt?'),
  ('bab9f171-c755-5c60-ab3b-35fe272d7776', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 12, 12, 'Isn''t this the word that we spoke to you in Egypt, saying, ''Leave us alone, that we may serve the Egyptians?'' For it were better for us to serve the Egyptians, than that we should die in the wilderness."'),
  ('3e232e79-b0bb-5a19-a345-baf19842e80c', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 13, 13, 'Moses said to the people, "Don''t be afraid. Stand still, and see the salvation of Yahweh, which he will work for you today: for the Egyptians whom you have seen today, you shall never see them again.'),
  ('dfaafbfc-4357-5425-a798-c5609a612ac0', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 14, 14, 'Yahweh will fight for you, and you shall be still."'),
  ('26930818-b510-552f-ac2c-1f6c11254e07', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 15, 15, 'Yahweh said to Moses, "Why do you cry to me? Speak to the children of Israel, that they go forward.'),
  ('2b9dbde2-983a-5f63-aecb-842387ff5ecf', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 16, 16, 'Lift up your rod, and stretch out your hand over the sea, and divide it: and the children of Israel shall go into the midst of the sea on dry ground.'),
  ('421bf7bc-58f5-52f9-a5a2-90179bd6c069', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 17, 17, 'I, behold, I will harden the hearts of the Egyptians, and they shall go in after them: and I will get myself honor over Pharaoh, and over all his armies, over his chariots, and over his horsemen.'),
  ('3d244453-3656-5b97-a8f4-52933ba6b74f', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 18, 18, 'The Egyptians shall know that I am Yahweh, when I have gotten myself honor over Pharaoh, over his chariots, and over his horsemen."'),
  ('96d6577e-72bc-5fa5-a366-c0c89c4dfa18', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 19, 19, 'The angel of God, who went before the camp of Israel, moved and went behind them; and the pillar of cloud moved from before them, and stood behind them.'),
  ('d6b9e8ec-bae4-59cb-af01-778ad4bb3f92', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 20, 20, 'It came between the camp of Egypt and the camp of Israel; and there was the cloud and the darkness, yet gave it light by night: and the one didn''t come near the other all the night.'),
  ('3395b15e-04b2-5d0d-a6e5-9ca2a8928565', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 21, 21, 'Moses stretched out his hand over the sea, and Yahweh caused the sea to go back by a strong east wind all the night, and made the sea dry land, and the waters were divided.'),
  ('0e8fe84c-b35a-5786-a104-b87d679bcfac', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 22, 22, 'The children of Israel went into the midst of the sea on the dry ground, and the waters were a wall to them on their right hand, and on their left.'),
  ('221bd9e1-0781-5975-a2cf-5e9f73e98cf6', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 23, 23, 'The Egyptians pursued, and went in after them into the midst of the sea: all of Pharaoh''s horses, his chariots, and his horsemen.'),
  ('eb377bab-7024-5e89-a971-79db27d01b50', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 24, 24, 'It happened in the morning watch, that Yahweh looked out on the Egyptian army through the pillar of fire and of cloud, and confused the Egyptian army.'),
  ('b7980a60-67bc-5bf4-a776-0cf901bda901', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 25, 25, 'He took off their chariot wheels, and they drove them heavily; so that the Egyptians said, "Let''s flee from the face of Israel, for Yahweh fights for them against the Egyptians!"'),
  ('750a6149-ddbc-5c4a-ad76-50b87152a661', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 26, 26, 'Yahweh said to Moses, "Stretch out your hand over the sea, that the waters may come again on the Egyptians, on their chariots, and on their horsemen."'),
  ('03425d1c-667b-5fec-a744-90a9fc32ccf9', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 27, 27, 'Moses stretched out his hand over the sea, and the sea returned to its strength when the morning appeared; and the Egyptians fled against it. Yahweh overthrew the Egyptians in the midst of the sea.'),
  ('767733ac-1416-5872-af01-a253ff2d7b80', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 28, 28, 'The waters returned, and covered the chariots and the horsemen, even all Pharaoh''s army that went in after them into the sea. There remained not so much as one of them.'),
  ('e4fb4674-3d2a-515c-aaa5-395e8c4e3494', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 29, 29, 'But the children of Israel walked on dry land in the midst of the sea, and the waters were a wall to them on their right hand, and on their left.'),
  ('3a413611-dd88-5983-a5c3-0c3d8cc16436', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 30, 30, 'Thus Yahweh saved Israel that day out of the hand of the Egyptians; and Israel saw the Egyptians dead on the seashore.'),
  ('f95b363c-704d-5580-a947-db0e82d23f83', '285a6c98-3dd9-5839-aded-e1f7cf99c48e', NULL, 31, 31, 'Israel saw the great work which Yahweh did to the Egyptians, and the people feared Yahweh; and they believed in Yahweh, and in his servant Moses.'),
  ('066a0366-0dea-586d-afca-920ffd2cc41c', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 1, 1, 'Then Moses and the children of Israel sang this song to Yahweh, and said, "I will sing to Yahweh, for he has triumphed gloriously. The horse and his rider he has thrown into the sea.'),
  ('8a2f1ff3-89d8-54b9-a933-95bcffe9fb06', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 2, 2, 'Yah is my strength and song. He has become my salvation. This is my God, and I will praise him; my father''s God, and I will exalt him.'),
  ('e6eb4ab5-7eaa-5a33-a683-639fd71bd6ec', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 3, 3, 'Yahweh is a man of war. Yahweh is his name.'),
  ('01557764-0fb4-5b08-a619-306f28049cea', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 4, 4, 'He has cast Pharaoh''s chariots and his army into the sea. His chosen captains are sunk in the Red Sea.'),
  ('ef093f62-7382-51a9-aaef-136a9a22a714', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 5, 5, 'The deeps cover them. They went down into the depths like a stone.'),
  ('7a86d074-1104-51c3-a89c-d165095ecb51', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 6, 6, 'Your right hand, Yahweh, is glorious in power. Your right hand, Yahweh, dashes the enemy in pieces.'),
  ('9c8a4c39-2438-5641-a5d5-b28c08f7204d', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 7, 7, 'In the greatness of your excellency, you overthrow those who rise up against you. You send forth your wrath. It consumes them as stubble.'),
  ('2aa82515-ceda-5e48-aeb8-63a98bd5664a', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 8, 8, 'With the blast of your nostrils, the waters were piled up. The floods stood upright as a heap. The deeps were congealed in the heart of the sea.'),
  ('ba959d27-311c-5568-a94e-b8a410700ff8', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 9, 9, 'The enemy said, ''I will pursue. I will overtake. I will divide the spoil. My desire shall be satisfied on them. I will draw my sword, my hand shall destroy them.'''),
  ('adb850ef-b242-5d1a-a123-1531fb26fc20', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 10, 10, 'You blew with your wind. The sea covered them. They sank like lead in the mighty waters.'),
  ('2faa02e4-161a-54e5-a08e-0c09b35b642a', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 11, 11, 'Who is like you, Yahweh, among the gods? Who is like you, glorious in holiness, fearful in praises, doing wonders?'),
  ('94b03fd4-30fe-53b4-a451-4e3cbbb3ecba', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 12, 12, 'You stretched out your right hand. The earth swallowed them.'),
  ('39029d2a-524b-5960-a658-668524531bec', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 13, 13, '"You, in your loving kindness, have led the people that you have redeemed. You have guided them in your strength to your holy habitation.'),
  ('29a62021-b2fd-5e68-a97a-4092e246fd97', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 14, 14, 'The peoples have heard. They tremble. Pangs have taken hold on the inhabitants of Philistia.'),
  ('88c62e36-821b-59fa-aafc-89b4cd85171b', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 15, 15, 'Then the chiefs of Edom were dismayed. Trembling takes hold of the mighty men of Moab. All the inhabitants of Canaan are melted away.'),
  ('28231cba-99aa-5ac4-a834-56615ad13b46', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 16, 16, 'Terror and dread falls on them. By the greatness of your arm they are as still as a stone-- until your people pass over, Yahweh, until the people pass over who you have purchased.'),
  ('fb8064fb-b20b-5522-a380-73c46f33f273', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 17, 17, 'You shall bring them in, and plant them in the mountain of your inheritance, the place, Yahweh, which you have made for yourself to dwell in; the sanctuary, Lord, which your hands have established.'),
  ('436bc60c-74ff-5fb8-ab71-008ab3f68427', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 18, 18, 'Yahweh shall reign forever and ever."'),
  ('4749f423-3981-5a2b-a3e2-1118a9e08955', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 19, 19, 'For the horses of Pharaoh went in with his chariots and with his horsemen into the sea, and Yahweh brought back the waters of the sea on them; but the children of Israel walked on dry land in the midst of the sea.'),
  ('b150273a-7a1d-5732-a621-ea205c31ac3a', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 20, 20, 'Miriam the prophetess, the sister of Aaron, took a tambourine in her hand; and all the women went out after her with tambourines and with dances.'),
  ('e5148374-22ca-527d-a67c-080fd5451825', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 21, 21, 'Miriam answered them, "Sing to Yahweh, for he has triumphed gloriously. The horse and his rider he has thrown into the sea."'),
  ('fd091bb3-d295-52f7-acfa-afb30362a0fd', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 22, 22, 'Moses led Israel onward from the Red Sea, and they went out into the wilderness of Shur; and they went three days in the wilderness, and found no water.'),
  ('87feeb36-3d26-5c12-a793-ce7fd8a1b944', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 23, 23, 'When they came to Marah, they couldn''t drink from the waters of Marah, for they were bitter. Therefore its name was called Marah.'),
  ('61d0db37-392c-5a6c-a8b8-3f2a701db0c9', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 24, 24, 'The people murmured against Moses, saying, "What shall we drink?"'),
  ('d50d6a0c-8538-5ecc-af13-4ad4b1d0fc49', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 25, 25, 'Then he cried to Yahweh. Yahweh showed him a tree, and he threw it into the waters, and the waters were made sweet. There he made a statute and an ordinance for them, and there he tested them;'),
  ('e04d3bf9-c972-58db-a04c-6ad6650b81ad', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 26, 26, 'and he said, "If you will diligently listen to the voice of Yahweh your God, and will do that which is right in his eyes, and will pay attention to his commandments, and keep all his statutes, I will put none of the diseases on you, which I have put on the Egyptians; for I am Yahweh who heals you."'),
  ('99e4da6f-32c5-5f08-aa1c-bce8427443d0', '0e6ac1a7-e9a1-5cf7-ae9f-7d407fac6864', NULL, 27, 27, 'They came to Elim, where there were twelve springs of water, and seventy palm trees: and they encamped there by the waters.'),
  ('cf3254fa-f15d-54d3-a364-e895870b1246', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 1, 1, 'They took their journey from Elim, and all the congregation of the children of Israel came to the wilderness of Sin, which is between Elim and Sinai, on the fifteenth day of the second month after their departing out of the land of Egypt.'),
  ('4c63891d-6616-56a1-a4ae-4ee139d07663', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 2, 2, 'The whole congregation of the children of Israel murmured against Moses and against Aaron in the wilderness;'),
  ('f2c279e2-4171-514d-a4ee-e478e999e984', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 3, 3, 'and the children of Israel said to them, "We wish that we had died by the hand of Yahweh in the land of Egypt, when we sat by the meat pots, when we ate our fill of bread, for you have brought us out into this wilderness, to kill this whole assembly with hunger."'),
  ('66b57485-90cf-5d3e-af0f-7269cb22b568', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 4, 4, 'Then Yahweh said to Moses, "Behold, I will rain bread from the sky for you, and the people shall go out and gather a day''s portion every day, that I may test them, whether they will walk in my law, or not.'),
  ('64658d20-93de-5286-a451-dadd47494761', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 5, 5, 'It shall come to pass on the sixth day, that they shall prepare that which they bring in, and it shall be twice as much as they gather daily."'),
  ('da383884-9376-5b45-a77f-16d38dd8861f', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 6, 6, 'Moses and Aaron said to all the children of Israel, "At evening, then you shall know that Yahweh has brought you out from the land of Egypt;'),
  ('701e3e29-65a8-546e-a594-b543590f89bd', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 7, 7, 'and in the morning, then you shall see the glory of Yahweh; because he hears your murmurings against Yahweh. Who are we, that you murmur against us?"'),
  ('f9e4ae69-ec60-5b31-a2b5-40a3378e9d43', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 8, 8, 'Moses said, "Now Yahweh shall give you meat to eat in the evening, and in the morning bread to satisfy you; because Yahweh hears your murmurings which you murmur against him. And who are we? Your murmurings are not against us, but against Yahweh."'),
  ('e0ec46f3-cfeb-5863-ad68-6f13d0ed4efe', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 9, 9, 'Moses said to Aaron, "Tell all the congregation of the children of Israel, ''Come near before Yahweh, for he has heard your murmurings.''"'),
  ('84eaa4a1-dbd9-55e5-acfd-272de4c2feb5', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 10, 10, 'It happened, as Aaron spoke to the whole congregation of the children of Israel, that they looked toward the wilderness, and behold, the glory of Yahweh appeared in the cloud.'),
  ('a4ca533f-1d50-51b2-acf2-217f65eab90f', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 11, 11, 'Yahweh spoke to Moses, saying,'),
  ('ef301cf1-9014-5ac5-a614-db22a006e57f', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 12, 12, '"I have heard the murmurings of the children of Israel. Speak to them, saying, ''At evening you shall eat meat, and in the morning you shall be filled with bread: and you shall know that I am Yahweh your God.''"'),
  ('5d1e7a46-0082-5eff-a5f0-9b58118fac39', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 13, 13, 'It happened at evening that quail came up and covered the camp; and in the morning the dew lay around the camp.'),
  ('819d6419-6ced-5588-a5d6-afc76fc3e3d7', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 14, 14, 'When the dew that lay had gone, behold, on the surface of the wilderness was a small round thing, small as the frost on the ground.'),
  ('965505d4-e697-5388-a7d6-b84d7110ee2b', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 15, 15, 'When the children of Israel saw it, they said one to another, "What is it?" For they didn''t know what it was. Moses said to them, "It is the bread which Yahweh has given you to eat."'),
  ('ad8d73b9-6392-539c-ab0b-93c63c95d4fa', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 16, 16, 'This is the thing which Yahweh has commanded: "Gather of it everyone according to his eating; an omer a head, according to the number of your persons, you shall take it, every man for those who are in his tent."'),
  ('4a5b20d7-090a-520d-a7f9-cb812e3e606c', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 17, 17, 'The children of Israel did so, and gathered some more, some less.'),
  ('e77340de-b975-50cb-a53e-031da988ff9b', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 18, 18, 'When they measured it with an omer, he who gathered much had nothing over, and he who gathered little had no lack. They gathered every man according to his eating.'),
  ('344ce159-c0c9-581a-a260-486b9ce36ce9', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 19, 19, 'Moses said to them, "Let no one leave of it until the morning."'),
  ('ea3b020d-f343-59d5-ae61-08f5065d12be', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 20, 20, 'Notwithstanding they didn''t listen to Moses, but some of them left of it until the morning, and it bred worms, and became foul: and Moses was angry with them.'),
  ('6eecbf36-30de-57e7-a3f3-ec7863bedbfc', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 21, 21, 'They gathered it morning by morning, everyone according to his eating. When the sun grew hot, it melted.'),
  ('e5eec786-9412-5cd7-a421-684befbdb61f', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 22, 22, 'It happened that on the sixth day they gathered twice as much bread, two omers for each one, and all the rulers of the congregation came and told Moses.'),
  ('56d97376-355e-5776-a9bb-445fbbf7b3b8', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 23, 23, 'He said to them, "This is that which Yahweh has spoken, ''Tomorrow is a solemn rest, a holy Sabbath to Yahweh. Bake that which you want to bake, and boil that which you want to boil; and all that remains over lay up for yourselves to be kept until the morning.''"'),
  ('65593fae-995e-570b-aad0-f31451c61591', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 24, 24, 'They laid it up until the morning, as Moses asked, and it didn''t become foul, neither was there any worm in it.'),
  ('547446a3-ddc2-52aa-ac4c-bac60222c63a', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 25, 25, 'Moses said, "Eat that today, for today is a Sabbath to Yahweh. Today you shall not find it in the field.'),
  ('daf39222-50a1-57d8-a492-cd69a554291c', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 26, 26, 'Six days you shall gather it, but on the seventh day is the Sabbath. In it there shall be none."'),
  ('65a7576b-4701-5e70-aea2-17dbd6abb3fb', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 27, 27, 'It happened on the seventh day, that some of the people went out to gather, and they found none.'),
  ('75f68e85-b43b-56f7-abe0-7635a142ccec', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 28, 28, 'Yahweh said to Moses, "How long do you refuse to keep my commandments and my laws?'),
  ('587a1ac3-48ae-5238-a487-bcbfb0c9994e', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 29, 29, 'Behold, because Yahweh has given you the Sabbath, therefore he gives you on the sixth day the bread of two days. Everyone stay in his place. Let no one go out of his place on the seventh day."'),
  ('244d583d-e05b-55f3-a004-5c13c2c66a6f', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 30, 30, 'So the people rested on the seventh day.'),
  ('1f285b8f-a2b2-568e-a342-6a6450fbdfa4', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 31, 31, 'The house of Israel called its name Manna, and it was like coriander seed, white; and its taste was like wafers with honey.'),
  ('eea931fe-a63e-546c-ad24-4f2d41bbe1b0', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 32, 32, 'Moses said, "This is the thing which Yahweh has commanded, ''Let an omer-full of it be kept throughout your generations, that they may see the bread with which I fed you in the wilderness, when I brought you forth from the land of Egypt.''"'),
  ('391c69a6-65ce-56e8-a5b4-60c8b960f57a', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 33, 33, 'Moses said to Aaron, "Take a pot, and put an omer-full of manna in it, and lay it up before Yahweh, to be kept throughout your generations."'),
  ('d483cb95-ecbf-5f7f-aec6-c95a44beebe2', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 34, 34, 'As Yahweh commanded Moses, so Aaron laid it up before the Testimony, to be kept.'),
  ('1780dd42-c85d-55ff-a368-ecbea4b987c1', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 35, 35, 'The children of Israel ate the manna forty years, until they came to an inhabited land. They ate the manna until they came to the borders of the land of Canaan.'),
  ('4390820e-877f-5c8e-a52e-288b1a5b37bc', '13b7620a-e2df-5312-a70c-4e70bc9d1b29', NULL, 36, 36, 'Now an omer is the tenth part of an ephah.'),
  ('0783ec44-d10c-55e7-a0f5-ab16b7a2b13b', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 1, 1, 'All the congregation of the children of Israel traveled from the wilderness of Sin, by their journeys, according to Yahweh''s commandment, and encamped in Rephidim; but there was no water for the people to drink.'),
  ('c1b90cd9-73ab-5681-a595-474b130c8934', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 2, 2, 'Therefore the people quarreled with Moses, and said, "Give us water to drink." Moses said to them, "Why do you quarrel with me? Why do you test Yahweh?"'),
  ('3076d46f-55e8-5079-afef-c22a5b973fd4', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 3, 3, 'The people were thirsty for water there; and the people murmured against Moses, and said, "Why have you brought us up out of Egypt, to kill us, our children, and our livestock with thirst?"'),
  ('913a3dc7-ff20-5b76-abd1-49fee3084c19', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 4, 4, 'Moses cried to Yahweh, saying, "What shall I do with these people? They are almost ready to stone me."'),
  ('d74b9b9a-5df9-551c-aaa1-cd577cd55044', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 5, 5, 'Yahweh said to Moses, "Walk on before the people, and take the elders of Israel with you, and take the rod in your hand with which you struck the Nile, and go.'),
  ('71212478-3fd2-5ec3-ae8f-acd0041c7c6b', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 6, 6, 'Behold, I will stand before you there on the rock in Horeb. You shall strike the rock, and water will come out of it, that the people may drink." Moses did so in the sight of the elders of Israel.'),
  ('c3107127-79c3-5c0f-a88c-67c2b68a9ed3', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 7, 7, 'He called the name of the place Massah, and Meribah, because the children of Israel quarreled, and because they tested Yahweh, saying, "Is Yahweh among us, or not?"'),
  ('d02f4c2b-3e4d-51d8-a3d6-94e21bd0b00e', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 8, 8, 'Then Amalek came and fought with Israel in Rephidim.'),
  ('b46ca265-8d67-55c0-a594-34345844e80c', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 9, 9, 'Moses said to Joshua, "Choose men for us, and go out, fight with Amalek. Tomorrow I will stand on the top of the hill with God''s rod in my hand."'),
  ('b6f19666-9e9b-59b7-a869-b979c1c1f232', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 10, 10, 'So Joshua did as Moses had told him, and fought with Amalek; and Moses, Aaron, and Hur went up to the top of the hill.'),
  ('f1088619-a147-53be-ae4e-9d94b1e457c0', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 11, 11, 'It happened, when Moses held up his hand, that Israel prevailed; and when he let down his hand, Amalek prevailed.'),
  ('90a86b68-2bbb-5ab3-a7aa-876a1eddeafd', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 12, 12, 'But Moses'' hands were heavy; and they took a stone, and put it under him, and he sat on it. Aaron and Hur held up his hands, the one on the one side, and the other on the other side. His hands were steady until sunset.'),
  ('30174c5d-9075-544b-aa7c-6b05995132b5', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 13, 13, 'Joshua defeated Amalek and his people with the edge of the sword.'),
  ('a289a925-771c-53fb-a326-fcdb35bdc7bd', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 14, 14, 'Yahweh said to Moses, "Write this for a memorial in a book, and rehearse it in the ears of Joshua: that I will utterly blot out the memory of Amalek from under the sky."'),
  ('51c3db43-aedf-5bba-a653-69d3bc09350f', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 15, 15, 'Moses built an altar, and called its name Yahweh our Banner.'),
  ('bff80e68-7f1c-5025-a572-7ececdb774c5', '3686b578-70bb-5c47-a139-0a3f0747ed60', NULL, 16, 16, 'He said, "Yah has sworn: ''Yahweh will have war with Amalek from generation to generation.''"'),
  ('77488ce9-6a19-5688-a50b-b08fba469df5', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 1, 1, 'Now Jethro, the priest of Midian, Moses'' father-in-law, heard of all that God had done for Moses, and for Israel his people, how that Yahweh had brought Israel out of Egypt.'),
  ('84e6f503-709c-503e-acb1-3406a721fd64', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 2, 2, 'Jethro, Moses'' father-in-law, received Zipporah, Moses'' wife, after he had sent her away,'),
  ('f6c6aef5-342a-5bc7-aff1-a3190b72d04d', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 3, 3, 'and her two sons. The name of one son was Gershom, for Moses said, "I have lived as a foreigner in a foreign land".'),
  ('28d0c8fe-b66b-5077-a883-3422e2a2c9dd', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 4, 4, 'The name of the other was Eliezer, for he said, "My father''s God was my help and delivered me from Pharaoh''s sword."'),
  ('3c94e7c6-a4c5-5490-a471-602a5b5d2a70', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 5, 5, 'Jethro, Moses'' father-in-law, came with his sons and his wife to Moses into the wilderness where he was encamped, at the Mountain of God.'),
  ('489bfa57-fda9-5b77-aedd-1cbd78658f1c', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 6, 6, 'He said to Moses, "I, your father-in-law Jethro, have come to you with your wife, and her two sons with her."'),
  ('07f92a54-81b7-5769-a9dd-a81e161c77ae', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 7, 7, 'Moses went out to meet his father-in-law, and bowed and kissed him. They asked each other of their welfare, and they came into the tent.'),
  ('d1fb2c33-7396-56ff-add7-8e6517930b2b', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 8, 8, 'Moses told his father-in-law all that Yahweh had done to Pharaoh and to the Egyptians for Israel''s sake, all the hardships that had come on them on the way, and how Yahweh delivered them.'),
  ('7beee2d4-ab2d-59b1-ae00-5e652b22ccbd', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 9, 9, 'Jethro rejoiced for all the goodness which Yahweh had done to Israel, in that he had delivered them out of the hand of the Egyptians.'),
  ('4c6c1a07-cbca-5ea1-ad49-f42e08d59df5', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 10, 10, 'Jethro said, "Blessed be Yahweh, who has delivered you out of the hand of the Egyptians, and out of the hand of Pharaoh; who has delivered the people from under the hand of the Egyptians.'),
  ('f95ce3d8-3a1c-5f61-af83-ee6c84b7f994', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 11, 11, 'Now I know that Yahweh is greater than all gods because of the thing in which they dealt arrogantly against them."'),
  ('e355b736-edb8-54a3-abc3-ecf0ff5fc527', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 12, 12, 'Jethro, Moses'' father-in-law, took a burnt offering and sacrifices for God. Aaron came with all of the elders of Israel, to eat bread with Moses'' father-in-law before God.'),
  ('f09e16f4-8af5-5d26-a1fd-351deb98531e', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 13, 13, 'It happened on the next day, that Moses sat to judge the people, and the people stood around Moses from the morning to the evening.'),
  ('79149aa4-1d75-575c-af8c-fa06368da353', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 14, 14, 'When Moses'' father-in-law saw all that he did to the people, he said, "What is this thing that you do for the people? Why do you sit alone, and all the people stand around you from morning to evening?"'),
  ('94ea59d5-1fb1-5099-a534-2ad80d747cd7', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 15, 15, 'Moses said to his father-in-law, "Because the people come to me to inquire of God.'),
  ('86bc5df1-205e-576e-ab00-5282bfc8989f', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 16, 16, 'When they have a matter, they come to me, and I judge between a man and his neighbor, and I make them know the statutes of God, and his laws."'),
  ('1586e06b-fe9c-5e97-ae5f-3fe493c8b784', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 17, 17, 'Moses'' father-in-law said to him, "The thing that you do is not good.'),
  ('720112ee-0f6f-5042-a2c6-e651176e3d94', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 18, 18, 'You will surely wear away, both you, and this people that is with you; for the thing is too heavy for you. You are not able to perform it yourself alone.'),
  ('6b0a9227-1f5f-53f9-ab59-ddce53926cc8', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 19, 19, 'Listen now to my voice. I will give you counsel, and God be with you. You represent the people before God, and bring the causes to God.'),
  ('8c38f68e-29d1-5eb0-a1bf-d2d8e0ddc683', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 20, 20, 'You shall teach them the statutes and the laws, and shall show them the way in which they must walk, and the work that they must do.'),
  ('66172df3-75fa-5cf0-ae7a-580e1ae57650', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 21, 21, 'Moreover you shall provide out of all the people able men, such as fear God: men of truth, hating unjust gain; and place such over them, to be rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.'),
  ('2e9a26d3-49fe-532e-ac59-3a81afdce477', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 22, 22, 'Let them judge the people at all times. It shall be that every great matter they shall bring to you, but every small matter they shall judge themselves. So shall it be easier for you, and they shall share the load with you.'),
  ('4fbbac1f-2e25-5a8c-a616-ebe64ac75cea', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 23, 23, 'If you will do this thing, and God commands you so, then you will be able to endure, and all of these people also will go to their place in peace."'),
  ('725c76a1-cd6f-5a6a-ac28-b9e2f22c90f7', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 24, 24, 'So Moses listened to the voice of his father-in-law, and did all that he had said.'),
  ('74fafe2e-366f-5121-a333-de7b42426bf7', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 25, 25, 'Moses chose able men out of all Israel, and made them heads over the people, rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.'),
  ('b12ad5ab-b07c-5792-a75c-4dc4736cde23', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 26, 26, 'They judged the people at all times. They brought the hard causes to Moses, but every small matter they judged themselves.'),
  ('63f3b064-9cee-53de-abe0-c381d8719228', '379b4bbd-d4bc-567b-a4ea-6dbb9998f7f3', NULL, 27, 27, 'Moses let his father-in-law depart, and he went his way into his own land.'),
  ('821c27f7-3cc5-5fa2-a442-56c9713aa9a5', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 1, 1, 'In the third month after the children of Israel had gone forth out of the land of Egypt, on that same day they came into the wilderness of Sinai.'),
  ('2063c7d5-a78b-5796-aef3-2f54b86856dd', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 2, 2, 'When they had departed from Rephidim, and had come to the wilderness of Sinai, they encamped in the wilderness; and there Israel encamped before the mountain.'),
  ('70e8f82f-6afd-59ca-a930-07df0b0330b0', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 3, 3, 'Moses went up to God, and Yahweh called to him out of the mountain, saying, "This is what you shall tell the house of Jacob, and tell the children of Israel:'),
  ('5cb48a8d-ae62-53f0-a7eb-cb8429f0eef1', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 4, 4, '''You have seen what I did to the Egyptians, and how I bore you on eagles'' wings, and brought you to myself.'),
  ('207acb1b-1972-52a9-aa04-4a71d3e4e5c9', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 5, 5, 'Now therefore, if you will indeed obey my voice, and keep my covenant, then you shall be my own possession from among all peoples; for all the earth is mine;'),
  ('664a9bad-5c78-5f1a-a0b2-741428cb0e3b', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 6, 6, 'and you shall be to me a kingdom of priests, and a holy nation.'' These are the words which you shall speak to the children of Israel."'),
  ('c907d3a2-18b0-580d-aaa4-72f94ef4ed3e', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 7, 7, 'Moses came and called for the elders of the people, and set before them all these words which Yahweh commanded him.'),
  ('bc871d58-fc12-5099-a06f-4bd546f8d722', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 8, 8, 'All the people answered together, and said, "All that Yahweh has spoken we will do." Moses reported the words of the people to Yahweh.'),
  ('e85963f3-9ca1-5824-affc-545d3f38010b', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 9, 9, 'Yahweh said to Moses, "Behold, I come to you in a thick cloud, that the people may hear when I speak with you, and may also believe you forever." Moses told the words of the people to Yahweh.'),
  ('531944ff-99e9-5e18-aae1-a46edae210eb', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 10, 10, 'Yahweh said to Moses, "Go to the people, and sanctify them today and tomorrow, and let them wash their garments,'),
  ('78394e15-6842-5668-a482-2c35d61fe454', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 11, 11, 'and be ready against the third day; for on the third day Yahweh will come down in the sight of all the people on Mount Sinai.'),
  ('b6d9a70d-33bc-554f-a492-9a32a3cce216', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 12, 12, 'You shall set bounds to the people all around, saying, ''Be careful that you don''t go up onto the mountain, or touch its border. Whoever touches the mountain shall be surely put to death.'),
  ('67856bb2-5514-5e37-ab68-5181f58f26af', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 13, 13, 'No hand shall touch him, but he shall surely be stoned or shot through; whether it is animal or man, he shall not live.'' When the trumpet sounds long, they shall come up to the mountain."'),
  ('936b83d7-884f-58c5-a28b-e6dac994af26', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 14, 14, 'Moses went down from the mountain to the people, and sanctified the people; and they washed their clothes.'),
  ('fc61abbc-d35d-596e-a87e-eaa19f3a1475', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 15, 15, 'He said to the people, "Be ready by the third day. Don''t have sexual relations with a woman."'),
  ('064fb9f0-fa34-5414-a942-900c6e8567b9', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 16, 16, 'It happened on the third day, when it was morning, that there were thunders and lightnings, and a thick cloud on the mountain, and the sound of an exceedingly loud trumpet; and all the people who were in the camp trembled.'),
  ('5aeb402e-f021-53d6-a46f-34eed24fda42', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 17, 17, 'Moses led the people out of the camp to meet God; and they stood at the lower part of the mountain.'),
  ('7f69c538-922f-5e89-a4fa-7c813d516f05', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 18, 18, 'Mount Sinai, all it, smoked, because Yahweh descended on it in fire; and its smoke ascended like the smoke of a furnace, and the whole mountain quaked greatly.'),
  ('e2c9803e-0242-5ccc-a9a7-4ab1d50614b4', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 19, 19, 'When the sound of the trumpet grew louder and louder, Moses spoke, and God answered him by a voice.'),
  ('fe4ba45d-131c-5148-a959-861357415fa3', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 20, 20, 'Yahweh came down on Mount Sinai, to the top of the mountain. Yahweh called Moses to the top of the mountain, and Moses went up.'),
  ('7b8a2605-bbde-514f-ae6b-3aaf8a86fb79', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 21, 21, 'Yahweh said to Moses, "Go down, warn the people, lest they break through to Yahweh to gaze, and many of them perish.'),
  ('bfd0ca18-f1a9-55c4-acd0-6c7b972f5276', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 22, 22, 'Let the priests also, who come near to Yahweh, sanctify themselves, lest Yahweh break forth on them."'),
  ('4dd1ac35-504e-5aaf-ac6c-458e127f211e', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 23, 23, 'Moses said to Yahweh, "The people can''t come up to Mount Sinai, for you warned us, saying, ''Set bounds around the mountain, and sanctify it.''"'),
  ('c0437b4a-0b1e-5beb-aff4-f7aab4d4ab7c', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 24, 24, 'Yahweh said to him, "Go down and you shall bring Aaron up with you, but don''t let the priests and the people break through to come up to Yahweh, lest he break forth on them."'),
  ('ab444d7e-0467-5e6d-ad3b-0d319957e7a0', '6dfd4137-d7a5-5f5f-a9db-da939558b2de', NULL, 25, 25, 'So Moses went down to the people, and told them.'),
  ('d375c91a-7e71-5889-ad57-f33f6dfed864', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 1, 1, 'God spoke all these words, saying,'),
  ('b872d926-3c74-5435-a836-b1cb9ed97696', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 2, 2, '"I am Yahweh your God, who brought you out of the land of Egypt, out of the house of bondage.'),
  ('df1e4d0b-db63-52aa-afb6-2eb59bb74d28', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 3, 3, '"You shall have no other gods before me.'),
  ('0e8f0bac-532f-5465-a90d-779eee889d4b', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 4, 4, '"You shall not make for yourselves an idol, nor any image of anything that is in the heavens above, or that is in the earth beneath, or that is in the water under the earth:'),
  ('a8de78e6-0d92-5eb1-a962-d282cefd3597', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 5, 5, 'you shall not bow yourself down to them, nor serve them, for I, Yahweh your God, am a jealous God, visiting the iniquity of the fathers on the children, on the third and on the fourth generation of those who hate me,'),
  ('5862c4da-3829-551f-a380-94f4e6c268f1', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 6, 6, 'and showing loving kindness to thousands of those who love me and keep my commandments.'),
  ('16d87cae-5e6e-53c1-aaad-87fe9bbd8a6c', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 7, 7, '"You shall not take the name of Yahweh your God in vain, for Yahweh will not hold him guiltless who takes his name in vain.'),
  ('7dcb1aba-2cf2-5045-a055-4be16b4089b3', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 8, 8, '"Remember the Sabbath day, to keep it holy.'),
  ('19452761-2275-541f-af27-9ff21e8fdebe', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 9, 9, 'You shall labor six days, and do all your work,'),
  ('fcc00e01-5b37-5cfd-aeeb-08307d3fd85e', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 10, 10, 'but the seventh day is a Sabbath to Yahweh your God. You shall not do any work in it, you, nor your son, nor your daughter, your male servant, nor your female servant, nor your livestock, nor your stranger who is within your gates;'),
  ('114ad374-fadd-5e82-a235-7be7e78bea4a', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 11, 11, 'for in six days Yahweh made heaven and earth, the sea, and all that is in them, and rested the seventh day; therefore Yahweh blessed the Sabbath day, and made it holy.'),
  ('a8adca54-5ad2-5377-a750-93e113ab40b3', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 12, 12, '"Honor your father and your mother, that your days may be long in the land which Yahweh your God gives you.'),
  ('81328be9-089c-52cf-ae34-d48021c5e62c', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 13, 13, '"You shall not murder.'),
  ('0041a668-8911-5288-a5af-6f8defc72c68', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 14, 14, '"You shall not commit adultery.'),
  ('404ba11f-9c4f-54f4-a9c4-d3e2b9f02057', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 15, 15, '"You shall not steal.'),
  ('7ea978d0-2929-51b2-ad70-7d4e379e1216', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 16, 16, '"You shall not give false testimony against your neighbor.'),
  ('73e7e59a-2493-53cf-aa16-e527e5bf4744', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 17, 17, '"You shall not covet your neighbor''s house. You shall not covet your neighbor''s wife, nor his male servant, nor his female servant, nor his ox, nor his donkey, nor anything that is your neighbor''s."'),
  ('333b9e0e-7af2-51c5-a300-e20a58340e82', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 18, 18, 'All the people perceived the thunderings, the lightnings, the sound of the trumpet, and the mountain smoking. When the people saw it, they trembled, and stayed at a distance.'),
  ('48747d3f-7925-561d-a1d5-73f40ad2ef52', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 19, 19, 'They said to Moses, "Speak with us yourself, and we will listen; but don''t let God speak with us, lest we die."'),
  ('370e14bb-fe55-558e-ad65-60febaaf4de6', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 20, 20, 'Moses said to the people, "Don''t be afraid, for God has come to test you, and that his fear may be before you, that you won''t sin."'),
  ('edeb92ae-250b-593f-a289-6e317079e87a', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 21, 21, 'The people stayed at a distance, and Moses drew near to the thick darkness where God was.'),
  ('486d7f69-4671-5c61-a827-3d7324190241', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 22, 22, 'Yahweh said to Moses, "This is what you shall tell the children of Israel: ''You yourselves have seen that I have talked with you from heaven.'),
  ('c1c0fb45-1ccd-5ba6-a35c-3f2a5da48aa4', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 23, 23, 'You shall most certainly not make alongside of me gods of silver, or gods of gold for yourselves.'),
  ('7d816433-0c10-59ee-a210-ce36461c78b7', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 24, 24, 'You shall make an altar of earth for me, and shall sacrifice on it your burnt offerings and your peace offerings, your sheep and your cattle. In every place where I record my name I will come to you and I will bless you.'),
  ('efedb410-3995-5cf0-a5a9-997df54b1dc6', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 25, 25, 'If you make me an altar of stone, you shall not build it of cut stones; for if you lift up your tool on it, you have polluted it.'),
  ('baebfe73-e447-503e-a179-24cafa9152fc', '9275dc53-237e-5b5d-a5f7-08b93271ad0c', NULL, 26, 26, 'Neither shall you go up by steps to my altar, that your nakedness may not be exposed to it.'''),
  ('941bde8a-af95-5b5c-a64c-cbe9bf3fbb36', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 1, 1, '"Now these are the ordinances which you shall set before them.'),
  ('50e200ed-58e6-5884-abc9-04e169925d15', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 2, 2, '"If you buy a Hebrew servant, he shall serve six years and in the seventh he shall go out free without paying anything.'),
  ('9099e940-1298-5fa7-a398-58ca3b61e12b', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 3, 3, 'If he comes in by himself, he shall go out by himself. If he is married, then his wife shall go out with him.'),
  ('46ccc2f5-39a3-5947-abba-979b105ac785', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 4, 4, 'If his master gives him a wife and she bears him sons or daughters, the wife and her children shall be her master''s, and he shall go out by himself.'),
  ('4198ff18-c20a-523c-a75b-8c090be96198', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 5, 5, 'But if the servant shall plainly say, ''I love my master, my wife, and my children. I will not go out free;'''),
  ('1684f9d3-819e-57fc-a617-357da7e594e7', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 6, 6, 'then his master shall bring him to God, and shall bring him to the door or to the doorpost, and his master shall bore his ear through with an awl, and he shall serve him for ever.'),
  ('414c82b2-d934-5283-abff-9183d93396e1', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 7, 7, '"If a man sells his daughter to be a female servant, she shall not go out as the male servants do.'),
  ('04ee3935-0d3c-54e9-afa7-5c07f2f1b424', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 8, 8, 'If she doesn''t please her master, who has married her to himself, then he shall let her be redeemed. He shall have no right to sell her to a foreign people, since he has dealt deceitfully with her.'),
  ('b92d3b8f-564a-55ad-a9ac-b094709c4cdb', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 9, 9, 'If he marries her to his son, he shall deal with her as a daughter.'),
  ('26b99ca8-985d-5617-a9ad-5768fbb7a70a', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 10, 10, 'If he takes another wife to himself, he shall not diminish her food, her clothing, and her marital rights.'),
  ('1c52675f-5e1d-532f-a0cc-f7ef6f24440c', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 11, 11, 'If he doesn''t do these three things for her, she may go free without paying any money.'),
  ('8c2a1a05-55c5-54d7-a0ee-e8a1a28dca8c', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 12, 12, '"One who strikes a man so that he dies shall surely be put to death,'),
  ('a199e4bc-b09f-528e-a8e4-7706b159b1c9', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 13, 13, 'but not if it is unintentional, but God allows it to happen: then I will appoint you a place where he shall flee.'),
  ('073bc78e-0efa-599d-a2f2-fae8fda7d61b', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 14, 14, 'If a man schemes and comes presumptuously on his neighbor to kill him, you shall take him from my altar, that he may die.'),
  ('c2a45ca1-97e2-5918-a624-9037549c3235', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 15, 15, '"Anyone who attacks his father or his mother shall be surely put to death.'),
  ('f504f45c-9185-5a92-ac7a-2dc38419e623', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 16, 16, '"Anyone who kidnaps someone and sells him, or if he is found in his hand, he shall surely be put to death.'),
  ('47c513f8-dea3-574c-aa6f-b57cc84d1c34', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 17, 17, '"Anyone who curses his father or his mother shall surely be put to death.'),
  ('39d2e89a-b1c6-5ba1-a172-96af0fe52f00', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 18, 18, '"If men quarrel and one strikes the other with a stone, or with his fist, and he doesn''t die, but is confined to bed;'),
  ('46f8e7a0-ddb6-5d48-a269-cf4e1c984a6a', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 19, 19, 'if he rises again and walks around with his staff, then he who struck him shall be cleared: only he shall pay for the loss of his time, and shall provide for his healing until he is thoroughly healed.'),
  ('8e035601-88d3-5ec6-a75f-b3e2cadc7b34', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 20, 20, '"If a man strikes his servant or his maid with a rod, and he dies under his hand, he shall surely be punished.'),
  ('959e0c6f-a6a3-5c1d-ae81-d5bcb161ceb0', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 21, 21, 'Notwithstanding, if he gets up after a day or two, he shall not be punished, for he is his property.'),
  ('530b2fa0-0660-5c7a-a906-d9d0b88130ed', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 22, 22, '"If men fight and hurt a pregnant woman so that she gives birth prematurely, and yet no harm follows, he shall be surely fined as much as the woman''s husband demands and the judges allow.'),
  ('f4424a4e-1f0b-5778-a47b-bc2907355a93', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 23, 23, 'But if any harm follows, then you must take life for life,'),
  ('a49116df-4c86-57ff-ab99-a8395bab7866', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 24, 24, 'eye for eye, tooth for tooth, hand for hand, foot for foot,'),
  ('586c1be2-4b19-5048-a362-d51b593fcb9d', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 25, 25, 'burning for burning, wound for wound, and bruise for bruise.'),
  ('b2f947d2-949f-56e1-a0a3-fc43f9fa8dee', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 26, 26, '"If a man strikes his servant''s eye, or his maid''s eye, and destroys it, he shall let him go free for his eye''s sake.'),
  ('475f0e66-6de8-52b4-a8d2-f35a2bbdb3cf', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 27, 27, 'If he strikes out his male servant''s tooth, or his female servant''s tooth, he shall let him go free for his tooth''s sake.'),
  ('2161a075-1915-581e-ac3b-8bb63c900b4c', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 28, 28, '"If a bull gores a man or a woman to death, the bull shall surely be stoned, and its flesh shall not be eaten; but the owner of the bull shall not be held responsible.'),
  ('36ab6638-890c-5fac-a5d7-7e8469215250', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 29, 29, 'But if the bull had a habit of goring in the past, and it has been testified to its owner, and he has not kept it in, but it has killed a man or a woman, the bull shall be stoned, and its owner shall also be put to death.'),
  ('78b19730-932c-5c86-a3f0-ac548dfe63c5', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 30, 30, 'If a ransom is laid on him, then he shall give for the redemption of his life whatever is laid on him.'),
  ('f566eb23-460d-51c6-ae13-2e8e56c1d383', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 31, 31, 'Whether it has gored a son or has gored a daughter, according to this judgment it shall be done to him.'),
  ('07447cd6-0210-59ed-ac84-3548af623655', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 32, 32, 'If the bull gores a male servant or a female servant, thirty shekels of silver shall be given to their master, and the ox shall be stoned.'),
  ('8f28dd8d-8356-5026-a9d5-25035a3285bb', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 33, 33, '"If a man opens a pit, or if a man digs a pit and doesn''t cover it, and a bull or a donkey falls into it,')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('bcc11fad-54bb-5ab0-a429-7a9ca9b02789', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 34, 34, 'the owner of the pit shall make it good. He shall give money to its owner, and the dead animal shall be his.'),
  ('47a6c072-b4a4-5405-afa2-ddd2b0da2bda', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 35, 35, '"If one man''s bull injures another''s, so that it dies, then they shall sell the live bull, and divide its price; and they shall also divide the dead animal.'),
  ('b0282a10-da7a-551d-a13f-5983e00018aa', '6cf54283-37ba-5573-a686-bcef8bb1cf49', NULL, 36, 36, 'Or if it is known that the bull was in the habit of goring in the past, and its owner has not kept it in, he shall surely pay bull for bull, and the dead animal shall be his own.'),
  ('07c60739-e638-50e6-a48e-9c32917ed9eb', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 1, 1, '"If a man steals an ox or a sheep, and kills it, or sells it; he shall pay five oxen for an ox, and four sheep for a sheep.'),
  ('fdc9a4e7-668a-5693-a195-bd803a4e6a75', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 2, 2, 'If the thief is found breaking in, and is struck so that he dies, there shall be no guilt of bloodshed for him.'),
  ('967a519c-b353-512d-ab4d-eb4182617b23', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 3, 3, 'If the sun has risen on him, guilt of bloodshed shall be for him; he shall make restitution. If he has nothing, then he shall be sold for his theft.'),
  ('2d6e2c7b-1355-5c05-a099-d0f58866be9d', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 4, 4, 'If the stolen property is found in his hand alive, whether it is ox, donkey, or sheep, he shall pay double.'),
  ('94fffff1-8b6b-5198-a2ee-13bbf977dc82', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 5, 5, '"If a man causes a field or vineyard to be eaten, and lets his animal loose, and it grazes in another man''s field, he shall make restitution from the best of his own field, and from the best of his own vineyard.'),
  ('271fddee-a4d2-5862-aa4f-5914b2dbe127', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 6, 6, '"If fire breaks out, and catches in thorns so that the shocks of grain, or the standing grain, or the field are consumed; he who kindled the fire shall surely make restitution.'),
  ('b1c21b69-dacf-5566-aa62-b7552f956ab0', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 7, 7, '"If a man delivers to his neighbor money or stuff to keep, and it is stolen out of the man''s house; if the thief is found, he shall pay double.'),
  ('0a5e9650-915c-5180-a9fc-3338bb946c24', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 8, 8, 'If the thief isn''t found, then the master of the house shall come near to God, to find out if he hasn''t put his hand to his neighbor''s goods.'),
  ('e389d96a-1cdb-508f-a31b-54486695d25f', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 9, 9, 'For every matter of trespass, whether it be for ox, for donkey, for sheep, for clothing, or for any kind of lost thing, about which one says, ''This is mine,'' the cause of both parties shall come before God. He whom God condemns shall pay double to his neighbor.'),
  ('b400bbbd-ffd7-5cc7-a170-81f220d98393', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 10, 10, '"If a man delivers to his neighbor a donkey, an ox, a sheep, or any animal to keep, and it dies or is injured, or driven away, no man seeing it;'),
  ('dc0aafba-594e-5f49-a754-74e9f459e84d', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 11, 11, 'the oath of Yahweh shall be between them both, whether he hasn''t put his hand to his neighbor''s goods; and its owner shall accept it, and he shall not make restitution.'),
  ('5e9070c9-8039-5750-a7d0-94a276075c30', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 12, 12, 'But if it is stolen from him, he shall make restitution to its owner.'),
  ('1903c9f8-bf8e-59bd-ad36-2f25e4de0c2e', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 13, 13, 'If it is torn in pieces, let him bring it for evidence. He shall not make good that which was torn.'),
  ('1a156a9d-7a78-5962-aad2-a5f806573c58', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 14, 14, '"If a man borrows anything of his neighbor''s, and it is injured, or dies, its owner not being with it, he shall surely make restitution.'),
  ('cc0e031a-dbdf-5ecd-a38f-4aab8937f7d6', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 15, 15, 'If its owner is with it, he shall not make it good. If it is a leased thing, it came for its lease.'),
  ('057b96d6-9fdb-56d5-a475-eec4ffa55f38', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 16, 16, '"If a man entices a virgin who isn''t pledged to be married, and lies with her, he shall surely pay a dowry for her to be his wife.'),
  ('5a75f407-cc8b-50b6-a163-f12411239e1c', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 17, 17, 'If her father utterly refuses to give her to him, he shall pay money according to the dowry of virgins.'),
  ('bb8f6ab2-7ecf-5f5e-a22a-dd4452bdb462', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 18, 18, '"You shall not allow a sorceress to live.'),
  ('d9cdfd5b-b4bd-58b7-ad5f-5daf5637d041', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 19, 19, '"Whoever has sex with an animal shall surely be put to death.'),
  ('23063d07-8538-583c-ac76-fb959cae7ff2', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 20, 20, '"He who sacrifices to any god, except to Yahweh only, shall be utterly destroyed.'),
  ('0c71357c-62e8-5edf-a212-4516fa9465a4', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 21, 21, '"You shall not wrong an alien, neither shall you oppress him, for you were aliens in the land of Egypt.'),
  ('8a1b802a-4d38-5bc3-a0c5-2b708926c0b3', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 22, 22, '"You shall not take advantage of any widow or fatherless child.'),
  ('d99ceafd-316e-59ef-ab4d-327a4a88917b', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 23, 23, 'If you take advantage of them at all, and they cry at all to me, I will surely hear their cry;'),
  ('17c37974-4363-5094-a2d9-c3765fe5e526', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 24, 24, 'and my wrath will grow hot, and I will kill you with the sword; and your wives shall be widows, and your children fatherless.'),
  ('71119d00-9376-5ef3-aa6c-5bbd88df35a7', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 25, 25, '"If you lend money to any of my people with you who is poor, you shall not be to him as a creditor; neither shall you charge him interest.'),
  ('814ce8b3-b61e-5a5e-a80c-1175b97a9d89', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 26, 26, 'If you take your neighbor''s garment as collateral, you shall restore it to him before the sun goes down,'),
  ('0c11f15b-5680-5578-ac43-5639ad5f026c', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 27, 27, 'for that is his only covering, it is his garment for his skin. What would he sleep in? It will happen, when he cries to me, that I will hear, for I am gracious.'),
  ('da68518e-bb1a-51bf-a490-2315e6805823', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 28, 28, '"You shall not blaspheme God, nor curse a ruler of your people.'),
  ('65c39fcc-5b84-57d3-ae5d-ed62590b4c37', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 29, 29, '"You shall not delay to offer from your harvest and from the outflow of your presses. "You shall give the firstborn of your sons to me.'),
  ('d7177096-2685-5b72-ab1b-90a27f751b5c', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 30, 30, 'You shall do likewise with your cattle and with your sheep. Seven days it shall be with its mother, then on the eighth day you shall give it to me.'),
  ('7aa96630-31ec-5b0c-ad77-d75d1d8ff445', 'dabd475e-ddb1-5422-a89a-b7f196c69800', NULL, 31, 31, '"You shall be holy men to me, therefore you shall not eat any flesh that is torn by animals in the field. You shall cast it to the dogs.'),
  ('a23198da-4029-520c-a0c0-dcec6f61f9e4', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 1, 1, '"You shall not spread a false report. Don''t join your hand with the wicked to be a malicious witness.'),
  ('3f290904-59fd-55cc-ae57-73272d7fc0e6', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 2, 2, '"You shall not follow a crowd to do evil; neither shall you testify in court to side with a multitude to pervert justice;'),
  ('1360f691-b30e-58eb-a960-9445655048ed', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 3, 3, 'neither shall you favor a poor man in his cause.'),
  ('da3f6765-3e91-5164-a750-9f1831f84a1c', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 4, 4, '"If you meet your enemy''s ox or his donkey going astray, you shall surely bring it back to him again.'),
  ('b1ce6c9e-670b-5d61-abab-188a58e7f666', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 5, 5, 'If you see the donkey of him who hates you fallen down under his burden, don''t leave him, you shall surely help him with it.'),
  ('dd88e017-fdba-5693-a0df-3ccc54be2524', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 6, 6, '"You shall not deny justice to your poor people in their lawsuits.'),
  ('f43c9786-a7ad-5bd9-ad7e-840c5b50115f', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 7, 7, '"Keep far from a false charge, and don''t kill the innocent and righteous: for I will not justify the wicked.'),
  ('efedd37d-97ff-53b1-ab3b-794bd333b699', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 8, 8, '"You shall take no bribe, for a bribe blinds those who have sight and perverts the words of the righteous.'),
  ('2f9455ea-ae2a-5f33-a6f1-3dbf04d6031b', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 9, 9, '"You shall not oppress an alien, for you know the heart of an alien, since you were aliens in the land of Egypt.'),
  ('99c9b090-595f-5f78-a5da-0795aaf753d9', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 10, 10, '"For six years you shall sow your land, and shall gather in its increase,'),
  ('5317c643-0bdd-5ae3-a8a9-f70cb409e58b', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 11, 11, 'but the seventh year you shall let it rest and lie fallow, that the poor of your people may eat; and what they leave the animal of the field shall eat. In the same way, you shall deal with your vineyard and with your olive grove.'),
  ('2f5655fe-54ab-5244-a647-d38bd979ac4c', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 12, 12, '"Six days you shall do your work, and on the seventh day you shall rest, that your ox and your donkey may have rest, and the son of your handmaid, and the alien may be refreshed.'),
  ('341247a8-1198-5a85-ad1b-c8f32b0fdc01', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 13, 13, '"Be careful to do all things that I have said to you; and don''t invoke the name of other gods, neither let them be heard out of your mouth.'),
  ('fe085873-5e25-517f-a1a7-190ee81a683e', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 14, 14, '"You shall observe a feast to me three times a year.'),
  ('d5c5524a-9451-5d84-a396-38b464fdf583', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 15, 15, 'You shall observe the feast of unleavened bread. Seven days you shall eat unleavened bread, as I commanded you, at the time appointed in the month Abib (for in it you came out from Egypt), and no one shall appear before me empty.'),
  ('87dd1b31-3a35-5533-aacc-65a86d77a4db', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 16, 16, 'And the feast of harvest, the first fruits of your labors, which you sow in the field: and the feast of harvest, at the end of the year, when you gather in your labors out of the field.'),
  ('f2794d13-7428-5be3-aedd-50a216d58f55', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 17, 17, 'Three times in the year all your males shall appear before the Lord Yahweh.'),
  ('8948dbe8-c813-53c8-aff1-b587d688fafa', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 18, 18, '"You shall not offer the blood of my sacrifice with leavened bread, neither shall the fat of my feast remain all night until the morning.'),
  ('d638cf4d-3464-542b-a432-de1ace93dac6', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 19, 19, 'The first of the first fruits of your ground you shall bring into the house of Yahweh your God. "You shall not boil a young goat in its mother''s milk.'),
  ('23a27b4e-b457-5fba-a8b0-aabe7c63769f', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 20, 20, '"Behold, I send an angel before you, to keep you by the way, and to bring you into the place which I have prepared.'),
  ('f1db447b-38df-5545-a282-76b36cfa5f1f', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 21, 21, 'Pay attention to him, and listen to his voice. Don''t provoke him, for he will not pardon your disobedience, for my name is in him.'),
  ('ba291a17-a442-5b6f-a360-d4b3bdea70da', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 22, 22, 'But if you indeed listen to his voice, and do all that I speak, then I will be an enemy to your enemies, and an adversary to your adversaries.'),
  ('4307dcfe-c416-5f89-a6a8-e718ef7259f9', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 23, 23, 'For my angel shall go before you, and bring you in to the Amorite, the Hittite, the Perizzite, the Canaanite, the Hivite, and the Jebusite; and I will cut them off.'),
  ('11accf7c-f331-54cb-afa0-d3ed5d74a3ac', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 24, 24, 'You shall not bow down to their gods, nor serve them, nor follow their practices, but you shall utterly overthrow them and demolish their pillars.'),
  ('2787c0b0-9a7d-5d7f-a379-63ca5323012b', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 25, 25, 'You shall serve Yahweh your God, and he will bless your bread and your water, and I will take sickness away from your midst.'),
  ('9d734f58-50e9-593e-a0af-de9c3431c1a7', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 26, 26, 'No one will miscarry or be barren in your land. I will fulfill the number of your days.'),
  ('3833f635-3ec9-583c-a91d-3e041fd15e73', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 27, 27, 'I will send my terror before you, and will confuse all the people to whom you come, and I will make all your enemies turn their backs to you.'),
  ('4f5492f6-3223-57df-a085-a87459383e93', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 28, 28, 'I will send the hornet before you, which will drive out the Hivite, the Canaanite, and the Hittite, from before you.'),
  ('5a6b6eb4-06a9-5f1b-a032-c30618ded9fb', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 29, 29, 'I will not drive them out from before you in one year, lest the land become desolate, and the animals of the field multiply against you.'),
  ('019614a9-a037-5a34-a3a5-71a2564f0abd', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 30, 30, 'Little by little I will drive them out from before you, until you have increased and inherit the land.'),
  ('78f63871-bc80-562e-af16-f958c59c5de3', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 31, 31, 'I will set your border from the Red Sea even to the sea of the Philistines, and from the wilderness to the River; for I will deliver the inhabitants of the land into your hand, and you shall drive them out before you.'),
  ('4208acf8-4948-56df-a2db-27356cab5a06', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 32, 32, 'You shall make no covenant with them, nor with their gods.'),
  ('0b63bb39-4b53-5f5a-a7e2-e7483cc9851b', 'd309eabe-fdf3-5355-abdb-e630286f2dca', NULL, 33, 33, 'They shall not dwell in your land, lest they make you sin against me, for if you serve their gods, it will surely be a snare to you."'),
  ('d8ba0d0b-e3ee-533a-adbf-94a86e9c9cdf', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 1, 1, 'He said to Moses, "Come up to Yahweh, you, and Aaron, Nadab, and Abihu, and seventy of the elders of Israel; and worship from a distance.'),
  ('4793e1aa-61ae-5dbd-acaf-9f1b84b5c8cc', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 2, 2, 'Moses alone shall come near to Yahweh, but they shall not come near, neither shall the people go up with him."'),
  ('a43c4041-bfaf-5da3-add4-7ad803560ac4', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 3, 3, 'Moses came and told the people all the words of Yahweh, and all the ordinances; and all the people answered with one voice, and said, "All the words which Yahweh has spoken will we do."'),
  ('91165746-b90e-5e93-a053-f3118684f2ff', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 4, 4, 'Moses wrote all the words of Yahweh, and rose up early in the morning, and built an altar under the mountain, and twelve pillars for the twelve tribes of Israel.'),
  ('327253fd-b649-592e-a7ab-f64e74d4c12a', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 5, 5, 'He sent young men of the children of Israel, who offered burnt offerings and sacrificed peace offerings of cattle to Yahweh.'),
  ('d2cd395a-566e-57ac-afb4-0bef34203f91', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 6, 6, 'Moses took half of the blood and put it in basins, and half of the blood he sprinkled on the altar.'),
  ('208f7df2-ca29-5d44-a808-b6871ed64ba6', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 7, 7, 'He took the book of the covenant and read it in the hearing of the people, and they said, "All that Yahweh has spoken will we do, and be obedient."'),
  ('989425f2-5f3d-5e02-ad84-baf4e517ccad', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 8, 8, 'Moses took the blood, and sprinkled it on the people, and said, "Look, this is the blood of the covenant, which Yahweh has made with you concerning all these words."'),
  ('6080cd4e-fcac-5a20-a0f5-db04fcd232e1', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 9, 9, 'Then Moses, Aaron, Nadab, Abihu, and seventy of the elders of Israel went up.'),
  ('dc6df8f6-54a5-5ea6-ac6d-d9aee4462396', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 10, 10, 'They saw the God of Israel. Under his feet was like a paved work of sapphire stone, like the skies for clearness.'),
  ('b2726464-7ef0-5312-a290-819a5c035ddd', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 11, 11, 'He didn''t lay his hand on the nobles of the children of Israel. They saw God, and ate and drank.'),
  ('b5eaba2f-433d-5845-acf8-dad449070292', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 12, 12, 'Yahweh said to Moses, "Come up to me on the mountain, and stay here, and I will give you the tables of stone with the law and the commands that I have written, that you may teach them."'),
  ('dcb905c2-6984-58d4-a543-e6a42345da13', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 13, 13, 'Moses rose up with Joshua, his servant, and Moses went up onto God''s Mountain.'),
  ('b37e3404-c293-52d8-a2fa-2df3f170f877', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 14, 14, 'He said to the elders, "Wait here for us, until we come again to you. Behold, Aaron and Hur are with you. Whoever is involved in a dispute can go to them."'),
  ('c1ecaf12-6b49-5de2-adae-2b7e1ed171bb', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 15, 15, 'Moses went up on the mountain, and the cloud covered the mountain.'),
  ('09a1cc63-eeb6-57ef-a8cd-a6ab57ae7f21', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 16, 16, 'The glory of Yahweh settled on Mount Sinai, and the cloud covered it six days. The seventh day he called to Moses out of the midst of the cloud.'),
  ('47d40014-8e12-55b8-a465-616ed8904e3d', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 17, 17, 'The appearance of the glory of Yahweh was like devouring fire on the top of the mountain in the eyes of the children of Israel.'),
  ('00d1060e-ff7f-5cd0-a70a-8a95236ff388', '62a4ef98-f876-559b-aec9-acfd42b5fee9', NULL, 18, 18, 'Moses entered into the midst of the cloud, and went up on the mountain; and Moses was on the mountain forty days and forty nights.'),
  ('685e55b6-95db-587f-aad2-dc467b648a47', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('832838d9-ea69-5ea5-a588-39decca0c4a5', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 2, 2, '"Speak to the children of Israel, that they take an offering for me. From everyone whose heart makes him willing you shall take my offering.'),
  ('e1303b2f-ba29-56e7-ab45-db5bfdedf182', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 3, 3, 'This is the offering which you shall take from them: gold, silver, brass,'),
  ('c2cfaf44-1d81-5be9-acbc-0445f2e055d2', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 4, 4, 'blue, purple, scarlet, fine linen, goats'' hair,'),
  ('ea2b9d3c-3ee4-5836-a4ac-c2f5d7af032c', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 5, 5, 'rams'' skins dyed red, sea cow hides, acacia wood,'),
  ('425fe6af-ae7f-5043-a515-66c7d7da7f79', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 6, 6, 'oil for the light, spices for the anointing oil and for the sweet incense,'),
  ('d86803ff-40bb-5372-af49-68e2e9d78451', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 7, 7, 'onyx stones, and stones to be set for the ephod and for the breastplate.'),
  ('fe774c20-2d85-5b6d-a4d1-f938f167d7f6', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 8, 8, 'Let them make me a sanctuary, that I may dwell among them.'),
  ('b68b974d-9841-5af6-a3e6-db7105083e81', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 9, 9, 'According to all that I show you, the pattern of the tabernacle, and the pattern of all of its furniture, even so you shall make it.'),
  ('9bee946e-59fe-560f-afe0-2a0ae227e147', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 10, 10, '"They shall make an ark of acacia wood. Its length shall be two and a half cubits, its breadth a cubit and a half, and a cubit and a half its height.'),
  ('f0a34b61-9053-5511-a7d7-3a0bd129f5f8', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 11, 11, 'You shall overlay it with pure gold. You shall overlay it inside and outside, and you shall make a gold molding around it.'),
  ('80e1ff8b-b614-55d1-a2ea-6c86b45fea5f', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 12, 12, 'You shall cast four rings of gold for it, and put them in its four feet. Two rings shall be on the one side of it, and two rings on the other side of it.'),
  ('2b236447-fbbe-5a81-aec5-156f08723691', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 13, 13, 'You shall make poles of acacia wood, and overlay them with gold.'),
  ('63f26682-ad7f-5a53-a27e-1221300e3152', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 14, 14, 'You shall put the poles into the rings on the sides of the ark to carry the ark.'),
  ('7096bb7e-bd45-5e0f-a845-e28c548c3243', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 15, 15, 'The poles shall be in the rings of the ark. They shall not be taken from it.'),
  ('a25363c8-9ad8-586f-a375-e7bb67ef0358', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 16, 16, 'You shall put the testimony which I shall give you into the ark.'),
  ('43e066a8-6253-5e99-adfb-3320db1850a9', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 17, 17, 'You shall make a mercy seat of pure gold. Two and a half cubits shall be its length, and a cubit and a half its breadth.'),
  ('20e00aa3-87f0-5243-acde-70746cdb1792', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 18, 18, 'You shall make two cherubim of hammered gold. You shall make them at the two ends of the mercy seat.'),
  ('0897fe82-8dcc-5f01-a2eb-5eb3d09c6382', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 19, 19, 'Make one cherub at the one end, and one cherub at the other end. You shall make the cherubim on its two ends of one piece with the mercy seat.'),
  ('c4b839c5-d6cd-55ef-a798-b187fee3a32a', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 20, 20, 'The cherubim shall spread out their wings upward, covering the mercy seat with their wings, with their faces toward one another. The faces of the cherubim shall be toward the mercy seat.'),
  ('3ceb893a-a4e8-5536-ab12-2faaaa4b1aa3', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 21, 21, 'You shall put the mercy seat on top of the ark, and in the ark you shall put the testimony that I will give you.'),
  ('841330bb-ecce-565b-ad85-5b58a995aa8b', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 22, 22, 'There I will meet with you, and I will tell you from above the mercy seat, from between the two cherubim which are on the ark of the testimony, all that I command you for the children of Israel.'),
  ('1212d8c0-3bf0-5375-a76b-55c15676010e', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 23, 23, '"You shall make a table of acacia wood. Two cubits shall be its length, and a cubit its breadth, and one and a half cubits its height.'),
  ('037a745c-9b29-564b-a17d-fccc1d5b86eb', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 24, 24, 'You shall overlay it with pure gold, and make a gold molding around it.'),
  ('04221174-6d17-545e-a68f-eb6a5388d8c0', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 25, 25, 'You shall make a rim of a handbreadth around it. You shall make a golden molding on its rim around it.'),
  ('d0124f22-1cc5-5f45-aafc-9b1993726b3f', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 26, 26, 'You shall make four rings of gold for it, and put the rings in the four corners that are on its four feet.'),
  ('8cef2dae-50ff-567b-aad3-5b46c5c8a00f', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 27, 27, 'the rings shall be close to the rim, for places for the poles to carry the table.'),
  ('ac48147f-d5c9-5b47-a199-c5fda06bcfb2', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 28, 28, 'You shall make the poles of acacia wood, and overlay them with gold, that the table may be carried with them.'),
  ('d2d759c0-0122-5655-a96b-efae23bbe1d1', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 29, 29, 'You shall make its dishes, its spoons, its ladles, and its bowls to pour out offerings with. You shall make them of pure gold.'),
  ('76167705-57a4-5c38-a6e8-9a2c62017e73', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 30, 30, 'You shall set bread of the presence on the table before me always.'),
  ('98541a22-3adf-5b48-a1e6-a74b3f4ce040', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 31, 31, '"You shall make a lampstand of pure gold. Of hammered work shall the lampstand be made, even its base, its shaft, its cups, its buds, and its flowers, shall be of one piece with it.'),
  ('59749d25-eccf-5a3e-a4d6-7c582173a54e', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 32, 32, 'There shall be six branches going out of its sides: three branches of the lampstand out of its one side, and three branches of the lampstand out of its other side;'),
  ('64ff4e46-8605-56bb-a402-62e5cbe9d4a8', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 33, 33, 'three cups made like almond blossoms in one branch, a bud and a flower; and three cups made like almond blossoms in the other branch, a bud and a flower, so for the six branches going out of the lampstand;'),
  ('9e169d57-79bc-5f19-a494-429b0424705a', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 34, 34, 'and in the lampstand four cups made like almond blossoms, its buds and its flowers;'),
  ('bdefd033-8437-5925-a0bd-6daf1a83a3f8', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 35, 35, 'and a bud under two branches of one piece with it, and a bud under two branches of one piece with it, and a bud under two branches of one piece with it, for the six branches going out of the lampstand.'),
  ('5f6776a9-4a0a-55f1-a94c-7263fa3b9a26', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 36, 36, 'Their buds and their branches shall be of one piece with it, all of it one beaten work of pure gold.'),
  ('b2af2e4d-764b-5c06-a56d-be2908f0b804', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 37, 37, 'You shall make its lamps seven, and they shall light its lamps to give light to the space in front of it.'),
  ('f6b1cf40-0c03-5101-afd4-b56a3cd5bc6a', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 38, 38, 'Its snuffers and its snuff dishes shall be of pure gold.'),
  ('c23651c3-3601-522d-a05e-6e94781541c5', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 39, 39, 'It shall be made of a talent of pure gold, with all these accessories.'),
  ('3e181647-2703-52eb-a1c5-672ef26a695c', '1e8423f4-bb45-55a3-a1b2-c34d4e2b3ebe', NULL, 40, 40, 'See that you make them after their pattern, which has been shown to you on the mountain.'),
  ('9cd60d7e-f73c-55c2-a348-32b6f3345980', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 1, 1, '"Moreover you shall make the tabernacle with ten curtains; of fine twined linen, and blue, and purple, and scarlet, with cherubim. The work of the skillful workman you shall make them.'),
  ('a39a9d37-e157-563a-a239-e86e876e645b', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 2, 2, 'The length of each curtain shall be twenty-eight cubits, and the breadth of each curtain four cubits: all the curtains shall have one measure.'),
  ('16963755-875a-5a4c-a906-c8d469bfc5cf', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 3, 3, 'Five curtains shall be coupled together one to another; and the other five curtains shall be coupled one to another.'),
  ('99021105-d79f-5875-a029-989669dd5ce5', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 4, 4, 'You shall make loops of blue on the edge of the one curtain from the edge in the coupling; and likewise you shall make in the edge of the curtain that is outmost in the second coupling.'),
  ('2cc23859-ee54-5daf-a3a0-0b87cc9d6b5b', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 5, 5, 'You shall make fifty loops in the one curtain, and you shall make fifty loops in the edge of the curtain that is in the second coupling. The loops shall be opposite one to another.'),
  ('9e8ef873-3558-5a55-ac48-eed541084bc1', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 6, 6, 'You shall make fifty clasps of gold, and couple the curtains one to another with the clasps: and the tabernacle shall be a unit.'),
  ('6dea3f5f-3305-560b-a127-ff41025a53b7', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 7, 7, '"You shall make curtains of goats'' hair for a covering over the tabernacle. You shall make them eleven curtains.'),
  ('4dad6649-4f9b-5ec2-a7ac-d616f8311314', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 8, 8, 'The length of each curtain shall be thirty cubits, and the breadth of each curtain four cubits: the eleven curtains shall have one measure.'),
  ('8af7e703-5424-53ba-a9ad-b98ffd272a6b', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 9, 9, 'You shall couple five curtains by themselves, and six curtains by themselves, and shall double over the sixth curtain in the forefront of the tent.'),
  ('f2426179-edc8-5ae4-a9dc-f44f325df117', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 10, 10, 'You shall make fifty loops on the edge of the one curtain that is outmost in the coupling, and fifty loops on the edge of the curtain which is outmost in the second coupling.'),
  ('64c482cb-ae77-57e0-af23-9f6be37d973b', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 11, 11, 'You shall make fifty clasps of brass, and put the clasps into the loops, and couple the tent together, that it may be one.'),
  ('4640b645-43e9-57cb-a463-6ba28a10692b', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 12, 12, 'The overhanging part that remains of the curtains of the tent, the half curtain that remains, shall hang over the back of the tabernacle.'),
  ('18ff6e48-0ffc-59e5-a01a-85faaed7500d', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 13, 13, 'The cubit on the one side, and the cubit on the other side, of that which remains in the length of the curtains of the tent, shall hang over the sides of the tabernacle on this side and on that side, to cover it.'),
  ('b73485a6-0f31-5eac-acb8-4532f39f3d9e', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 14, 14, 'You shall make a covering for the tent of rams'' skins dyed red, and a covering of sea cow hides above.'),
  ('95a31a65-150a-5663-ab54-c029c0be55ea', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 15, 15, '"You shall make the boards for the tabernacle of acacia wood, standing up.'),
  ('d2f90255-e894-5c75-aa98-5a3273ad8736', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 16, 16, 'Ten cubits shall be the length of a board, and one and a half cubits the breadth of each board.'),
  ('b2313596-36c0-5c4f-a3cf-40f295c29164', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 17, 17, 'There shall be two tenons in each board, joined to one another: thus you shall make for all the boards of the tabernacle.'),
  ('605f4bd1-924a-5891-aed5-89f99928897f', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 18, 18, 'You shall make the boards for the tabernacle, twenty boards for the south side southward.'),
  ('ad3177e7-9dc2-5853-a1d7-689d01eda940', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 19, 19, 'You shall make forty sockets of silver under the twenty boards; two sockets under one board for its two tenons, and two sockets under another board for its two tenons.'),
  ('00ef0c31-28cb-51d8-a0c1-35f4558cfb77', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 20, 20, 'For the second side of the tabernacle, on the north side, twenty boards,'),
  ('4dc82db3-0cdd-5c43-a754-a91def5382dc', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 21, 21, 'and their forty sockets of silver; two sockets under one board, and two sockets under another board.'),
  ('8f72ca48-48c6-5cb9-a3b0-20c491db9e14', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 22, 22, 'For the far part of the tabernacle westward you shall make six boards.'),
  ('f2ebb587-229d-5c5d-a2ac-976b31a3ac03', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 23, 23, 'You shall make two boards for the corners of the tabernacle in the far part.'),
  ('5943d7a5-32a1-59bf-a8f3-5c7fda2fe914', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 24, 24, 'They shall be double beneath, and in the same way they shall be whole to its top to one ring: thus shall it be for them both; they shall be for the two corners.'),
  ('5cfe3fdf-339f-52af-a02c-2701ab0b4cb0', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 25, 25, 'There shall be eight boards, and their sockets of silver, sixteen sockets; two sockets under one board, and two sockets under another board.'),
  ('d1033a0e-861a-5d85-a6de-f310992df002', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 26, 26, '"You shall make bars of acacia wood: five for the boards of the one side of the tabernacle,'),
  ('102b214f-ef16-5405-a9ce-05dddb8ea847', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 27, 27, 'and five bars for the boards of the other side of the tabernacle, and five bars for the boards of the side of the tabernacle, for the far part westward.'),
  ('bc044e7d-c8db-5c19-ab4d-9d2a380e76b4', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 28, 28, 'The middle bar in the midst of the boards shall pass through from end to end.'),
  ('ae2b9f5c-a623-5702-a25b-1ac341716381', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 29, 29, 'You shall overlay the boards with gold, and make their rings of gold for places for the bars: and you shall overlay the bars with gold.'),
  ('94bd0de4-a563-5c8d-a02d-59faaa4b51f3', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 30, 30, 'You shall set up the tabernacle according to the way that it was shown to you on the mountain.'),
  ('ba36052e-44c7-5049-af18-89a543d66cf5', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 31, 31, '"You shall make a veil of blue, and purple, and scarlet, and fine twined linen, with cherubim. The work of the skillful workman shall it be made.'),
  ('befa073b-5d6e-5271-a406-ce50e5937488', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 32, 32, 'You shall hang it on four pillars of acacia overlaid with gold; their hooks shall be of gold, on four sockets of silver.'),
  ('7c04b225-e44b-52d6-a8fa-025eeceeb0c8', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 33, 33, 'You shall hang up the veil under the clasps, and shall bring the ark of the testimony in there within the veil: and the veil shall separate the holy place from the most holy for you.'),
  ('d6d28e40-85a0-5b4f-a9ce-f773964753b0', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 34, 34, 'You shall put the mercy seat on the ark of the testimony in the most holy place.'),
  ('5d52fc76-77b8-5eb4-affa-333ec8684e7f', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 35, 35, 'You shall set the table outside the veil, and the lampstand over against the table on the side of the tabernacle toward the south: and you shall put the table on the north side.'),
  ('77b70da4-6fb0-58ec-aa24-54d8e9fa480e', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 36, 36, '"You shall make a screen for the door of the Tent, of blue, and purple, and scarlet, and fine twined linen, the work of the embroiderer.'),
  ('0f86aba3-7293-5c6f-a9b6-e418acaf967f', '7a91c72e-e9ee-5956-a492-1759d6705bee', NULL, 37, 37, 'You shall make for the screen five pillars of acacia, and overlay them with gold: their hooks shall be of gold: and you shall cast five sockets of brass for them.'),
  ('92437673-c3e7-5080-a104-4a86a5256275', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 1, 1, '"You shall make the altar of acacia wood, five cubits long, and five cubits broad; the altar shall be foursquare: and its height shall be three cubits.'),
  ('ef6574d2-03b7-52de-a7f7-22ce74d48e0b', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 2, 2, 'You shall make its horns on its four corners; its horns shall be of one piece with it; and you shall overlay it with brass.'),
  ('34cc1dac-43f1-5fd5-a2c1-583eaf41b7c1', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 3, 3, 'You shall make its pots to take away its ashes, its shovels, its basins, its flesh hooks, and its fire pans: all its vessels you shall make of brass.'),
  ('f9fc21a5-eef1-5987-aec9-bea641c0bdc2', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 4, 4, 'You shall make a grating for it of network of brass: and on the net you shall make four bronze rings in its four corners.'),
  ('56dc0d55-f0c2-5f64-a24a-6b5630929181', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 5, 5, 'You shall put it under the ledge around the altar beneath, that the net may reach halfway up the altar.'),
  ('40decd04-328f-5968-a61d-65c53a1cf8fe', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 6, 6, 'You shall make poles for the altar, poles of acacia wood, and overlay them with brass.'),
  ('b168f5ec-9027-52e7-a311-d05520c752f1', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 7, 7, 'Its poles shall be put into the rings, and the poles shall be on the two sides of the altar, when carrying it.'),
  ('a4b6eb3c-3c62-524c-a52a-2cc61af9f657', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 8, 8, 'You shall make it with hollow planks. They shall make it as it has been shown you on the mountain.'),
  ('48d60e48-b4f7-5611-a4c3-218a2e095e59', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 9, 9, '"You shall make the court of the tabernacle: for the south side southward there shall be hangings for the court of fine twined linen one hundred cubits long for one side:'),
  ('a68a0c39-ba87-5656-a281-dd338a1c0e4d', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 10, 10, 'and its pillars shall be twenty, and their sockets twenty, of brass; the hooks of the pillars and their fillets shall be of silver.'),
  ('8ec5ff62-3f00-53e6-a3f9-4baab53987a4', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 11, 11, 'Likewise for the north side in length there shall be hangings one hundred cubits long, and its pillars twenty, and their sockets twenty, of brass; the hooks of the pillars, and their fillets, of silver.'),
  ('cad15495-4573-5b4c-ad7f-ac7302e53287', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 12, 12, 'For the breadth of the court on the west side shall be hangings of fifty cubits; their pillars ten, and their sockets ten.'),
  ('9edaad0a-f4ed-5718-afb4-09248fa44d60', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 13, 13, 'The breadth of the court on the east side eastward shall be fifty cubits.'),
  ('0fbc3d05-59eb-5062-a831-52a9528b0514', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 14, 14, 'The hangings for the one side of the gate shall be fifteen cubits; their pillars three, and their sockets three.'),
  ('c5c26ca1-22b9-57bb-a224-37d8bc0424f0', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 15, 15, 'For the other side shall be hangings of fifteen cubits; their pillars three, and their sockets three.'),
  ('092c7233-26b1-54d9-a005-74726e9c0d22', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 16, 16, 'For the gate of the court shall be a screen of twenty cubits, of blue, and purple, and scarlet, and fine twined linen, the work of the embroiderer; their pillars four, and their sockets four.'),
  ('12e85a77-8648-5e56-a9b1-65544b8efa20', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 17, 17, 'All the pillars of the court around shall be filleted with silver; their hooks of silver, and their sockets of brass.'),
  ('07328358-4a7a-5100-af2d-7156b6a7e90f', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 18, 18, 'The length of the court shall be one hundred cubits, and the breadth fifty every where, and the height five cubits, of fine twined linen, and their sockets of brass.'),
  ('b734e32b-8c7a-5dce-a88e-b3503733d28c', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 19, 19, 'All the instruments of the tabernacle in all its service, and all its pins, and all the pins of the court, shall be of brass.'),
  ('29ca5447-ec90-5277-a125-f3650252de55', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 20, 20, '"You shall command the children of Israel, that they bring to you pure olive oil beaten for the light, to cause a lamp to burn continually.'),
  ('9d7fc2b5-ec5b-58d4-a377-30997d89ccd8', '8c354559-ceee-5d3d-ace0-5044a81c72fd', NULL, 21, 21, 'In the Tent of Meeting, outside the veil which is before the testimony, Aaron and his sons shall keep it in order from evening to morning before Yahweh: it shall be a statute forever throughout their generations on the behalf of the children of Israel.'),
  ('10b3903c-715d-5ad2-a756-92433ee9f1d7', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 1, 1, '"Bring Aaron your brother, and his sons with him, near to you from among the children of Israel, that he may minister to me in the priest''s office, even Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron''s sons.'),
  ('12a1a4da-00c0-5426-ad86-c025a59079db', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 2, 2, 'You shall make holy garments for Aaron your brother, for glory and for beauty.'),
  ('51dbb11a-3ba0-5e8c-aa88-5c208eb961d2', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 3, 3, 'You shall speak to all who are wise-hearted, whom I have filled with the spirit of wisdom, that they make Aaron''s garments to sanctify him, that he may minister to me in the priest''s office.'),
  ('52481d24-6221-599f-a25c-164cdd477190', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 4, 4, 'These are the garments which they shall make: a breastplate, and an ephod, and a robe, and a coat of checker work, a turban, and a sash: and they shall make holy garments for Aaron your brother, and his sons, that he may minister to me in the priest''s office.'),
  ('b11ec53a-5d11-5d66-a8dc-2882a38826d8', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 5, 5, 'They shall take the gold, and the blue, and the purple, and the scarlet, and the fine linen.'),
  ('2686bb65-3f09-5aa3-a2f5-8108c5e5564c', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 6, 6, '"They shall make the ephod of gold, of blue, and purple, scarlet, and fine twined linen, the work of the skillful workman.'),
  ('dda5eecb-6a95-5bdf-adca-d4bea0b7aef4', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 7, 7, 'It shall have two shoulder straps joined to the two ends of it, that it may be joined together.'),
  ('8f7d10d4-c6ef-5a2f-aa0d-7f7606b52a65', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 8, 8, 'The skillfully woven band, which is on it, that is on him, shall be like its work and of the same piece; of gold, of blue, and purple, and scarlet, and fine twined linen.'),
  ('c2f94d66-af6b-5d19-af2e-6338e8fe08f1', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 9, 9, 'You shall take two onyx stones, and engrave on them the names of the children of Israel:'),
  ('265e8da5-0e61-5eae-aa2b-469f65b7456f', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 10, 10, 'six of their names on the one stone, and the names of the six that remain on the other stone, in the order of their birth.'),
  ('58511ba5-035c-55c9-a7b3-4d9e374f26f9', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 11, 11, 'With the work of an engraver in stone, like the engravings of a signet, you shall engrave the two stones, according to the names of the children of Israel: you shall make them to be enclosed in settings of gold.'),
  ('f0d9d783-4483-5d3a-a02b-c3372b0c0614', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 12, 12, 'You shall put the two stones on the shoulder straps of the ephod, to be stones of memorial for the children of Israel: and Aaron shall bear their names before Yahweh on his two shoulders for a memorial.'),
  ('eff5894a-a01d-55a1-ac26-e08d17f4a817', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 13, 13, 'You shall make settings of gold,'),
  ('d9f29140-164b-53db-adda-0fd57fb5f736', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 14, 14, 'and two chains of pure gold; you shall make them like cords of braided work: and you shall put the braided chains on the settings.'),
  ('3c2d95d3-54f3-5b99-af4f-c59a0a6ca0d6', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 15, 15, '"You shall make a breastplate of judgment, the work of the skillful workman; like the work of the ephod you shall make it; of gold, of blue, and purple, and scarlet, and fine twined linen, you shall make it.'),
  ('2ac3ca2f-97ce-58fb-a7ea-c806bdd72565', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 16, 16, 'It shall be square and folded double; a span shall be its length of it, and a span its breadth.'),
  ('cc4785d9-29de-5d07-a93c-ebf2a47aeb8b', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 17, 17, 'You shall set in it settings of stones, four rows of stones: a row of ruby, topaz, and beryl shall be the first row;'),
  ('d411fc1e-0b83-59a6-aac3-bd4a071bbbe4', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 18, 18, 'and the second row a turquoise, a sapphire, and an emerald;'),
  ('42fdcc8b-ff71-5d2b-aa26-4d48866ba0bd', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 19, 19, 'and the third row a jacinth, an agate, and an amethyst;'),
  ('daf0818b-61e0-5544-a1fa-d101f003bba7', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 20, 20, 'and the fourth row a chrysolite, an onyx, and a jasper: they shall be enclosed in gold in their settings.'),
  ('c567381a-6c57-5ee0-aee6-0d78c5a8ee11', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 21, 21, 'The stones shall be according to the names of the children of Israel, twelve, according to their names; like the engravings of a signet, everyone according to his name, they shall be for the twelve tribes.'),
  ('759f9f14-cc40-5082-afa2-78743902388d', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 22, 22, 'You shall make on the breastplate chains like cords, of braided work of pure gold.'),
  ('274c94b4-00d3-5f15-a233-4559999dd4a0', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 23, 23, 'You shall make on the breastplate two rings of gold, and shall put the two rings on the two ends of the breastplate.'),
  ('3273258b-384f-50b7-ada9-9944436282ba', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 24, 24, 'You shall put the two braided chains of gold in the two rings at the ends of the breastplate.'),
  ('9bf5ca7a-7e12-5cf8-a1ab-5ab76c506ce1', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 25, 25, 'The other two ends of the two braided chains you shall put on the two settings, and put them on the shoulder straps of the ephod in its forepart.'),
  ('ed798027-3df3-5d2c-ad4e-def2f514484e', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 26, 26, 'You shall make two rings of gold, and you shall put them on the two ends of the breastplate, on its edge, which is toward the side of the ephod inward.'),
  ('e70d94f4-474c-5a0e-a869-69291e0ba56e', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 27, 27, 'You shall make two rings of gold, and shall put them on the two shoulder straps of the ephod underneath, in its forepart, close by its coupling, above the skillfully woven band of the ephod.'),
  ('fe2ea1d8-2781-5ff9-a2a6-f5957c712a09', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 28, 28, 'They shall bind the breastplate by its rings to the rings of the ephod with a lace of blue, that it may be on the skillfully woven band of the ephod, and that the breastplate may not swing out from the ephod.'),
  ('4aad0b72-0181-559a-a0d5-502248e688b5', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 29, 29, 'Aaron shall bear the names of the children of Israel in the breastplate of judgment on his heart, when he goes in to the holy place, for a memorial before Yahweh continually.'),
  ('968d1cd1-ce3c-50eb-aacd-68269983c9f6', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 30, 30, 'You shall put in the breastplate of judgment the Urim and the Thummim; and they shall be on Aaron''s heart, when he goes in before Yahweh: and Aaron shall bear the judgment of the children of Israel on his heart before Yahweh continually.'),
  ('df9ad926-220f-5b16-a20b-75a74206479d', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 31, 31, '"You shall make the robe of the ephod all of blue.'),
  ('4df50272-724f-5210-acd8-bc41285f7778', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 32, 32, 'It shall have a hole for the head in its midst: it shall have a binding of woven work around its hole, as it were the hole of a coat of mail, that it not be torn.'),
  ('c8e45440-6abe-5b03-a100-69ef13d41c43', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 33, 33, 'On its hem you shall make pomegranates of blue, and of purple, and of scarlet, around its hem; and bells of gold between and around them:'),
  ('fdb3d2cb-8235-5183-adb6-619098fbe90d', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 34, 34, 'a golden bell and a pomegranate, a golden bell and a pomegranate, around the hem of the robe.'),
  ('4fef1f8c-0b61-5444-ab0e-4c37606d1a59', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 35, 35, 'It shall be on Aaron to minister: and its sound shall be heard when he goes in to the holy place before Yahweh, and when he comes out, that he not die.'),
  ('4d48e2e1-6af9-50b8-a522-f544e19e71e7', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 36, 36, '"You shall make a plate of pure gold, and engrave on it, like the engravings of a signet, ''HOLY TO YAHWEH.'''),
  ('4baccf0e-0ac9-56d6-ae56-185822f4ebbf', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 37, 37, 'You shall put it on a lace of blue, and it shall be on the sash; on the front of the sash it shall be.'),
  ('9d932284-34b6-5886-ab3d-e187e6c43742', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 38, 38, 'It shall be on Aaron''s forehead, and Aaron shall bear the iniquity of the holy things, which the children of Israel shall make holy in all their holy gifts; and it shall be always on his forehead, that they may be accepted before Yahweh.'),
  ('d331a5ea-9e93-5bb2-ab87-a6fc7a85064c', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 39, 39, 'You shall weave the coat in checker work of fine linen, and you shall make a turban of fine linen, and you shall make a sash, the work of the embroiderer.'),
  ('4615302d-c41c-52d4-a12e-69ab714c79bc', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 40, 40, '"You shall make coats for Aaron''s sons, and you shall make sashes for them and you shall make headbands for them, for glory and for beauty.'),
  ('072bed8e-dbf8-54fb-a4e7-b514f34bc060', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 41, 41, 'You shall put them on Aaron your brother, and on his sons with him, and shall anoint them, and consecrate them, and sanctify them, that they may minister to me in the priest''s office.'),
  ('afd76c7a-d16a-5516-a559-ac2318b77a3a', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 42, 42, 'You shall make them linen breeches to cover the flesh of their nakedness; from the waist even to the thighs they shall reach:'),
  ('ebc6f30b-25a0-51b7-ab8a-80a28bd0ab64', '3256bb26-d3bd-5c47-ad8d-9570248f389b', NULL, 43, 43, 'They shall be on Aaron, and on his sons, when they go in to the Tent of Meeting, or when they come near to the altar to minister in the holy place; that they don''t bear iniquity, and die: it shall be a statute forever to him and to his descendants after him.'),
  ('00607231-0817-583a-a3e4-6dc0fd07af82', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 1, 1, '"This is the thing that you shall do to them to make them holy, to minister to me in the priest''s office: take one young bull and two rams without blemish,'),
  ('97eeccd5-5101-5379-a388-136d5bf363fe', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 2, 2, 'unleavened bread, unleavened cakes mixed with oil, and unleavened wafers anointed with oil: you shall make them of fine wheat flour.'),
  ('9c43aff7-bfe9-51bf-adbb-882aa678f47a', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 3, 3, 'You shall put them into one basket, and bring them in the basket, with the bull and the two rams.'),
  ('d03825d1-8fce-55b1-a4aa-f13ecf4df614', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 4, 4, 'You shall bring Aaron and his sons to the door of the Tent of Meeting, and shall wash them with water.'),
  ('e9e84d3a-51e0-5169-ae2b-2a7d1111821c', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 5, 5, 'You shall take the garments, and put on Aaron the coat, the robe of the ephod, the ephod, and the breastplate, and clothe him with the skillfully woven band of the ephod;'),
  ('82fed33e-7178-505a-a34b-ae1f328f025a', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 6, 6, 'and you shall set the turban on his head, and put the holy crown on the turban.'),
  ('1f291939-6bba-55d6-acd9-4a4136e8ec8a', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 7, 7, 'Then you shall take the anointing oil, and pour it on his head, and anoint him.'),
  ('b499c8a7-9a03-5864-a4b0-c8ecaa1343ca', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 8, 8, 'You shall bring his sons, and put coats on them.'),
  ('0b8196b7-9b2b-543d-a077-1ad961b53cfb', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 9, 9, 'You shall clothe them with belts, Aaron and his sons, and bind headbands on them: and they shall have the priesthood by a perpetual statute: and you shall consecrate Aaron and his sons.'),
  ('b824e2ac-373b-5602-a3e6-2921eb0ff38f', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 10, 10, '"You shall bring the bull before the Tent of Meeting: and Aaron and his sons shall lay their hands on the head of the bull.'),
  ('cead2a44-582d-5e32-ab02-c2a5eb13bb15', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 11, 11, 'You shall kill the bull before Yahweh, at the door of the Tent of Meeting.'),
  ('360d4ba0-4bf2-5dc4-a436-51651c7f9724', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 12, 12, 'You shall take of the blood of the bull, and put it on the horns of the altar with your finger; and you shall pour out all the blood at the base of the altar.'),
  ('d3216f46-81cf-516e-a615-281f78a7ad08', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 13, 13, 'You shall take all the fat that covers the innards, the cover of the liver, the two kidneys, and the fat that is on them, and burn them on the altar.'),
  ('3fd63fb6-6f7b-581c-a1a3-3aa546cd05d1', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 14, 14, 'But the flesh of the bull, and its skin, and its dung, you shall burn with fire outside of the camp: it is a sin offering.'),
  ('8b40fb29-b1d1-5c17-a4e9-1afe574e47f7', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 15, 15, '"You shall also take the one ram; and Aaron and his sons shall lay their hands on the head of the ram.'),
  ('a2f60f49-3cc8-5561-a9de-9d36ba4c6c18', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 16, 16, 'You shall kill the ram, and you shall take its blood, and sprinkle it around on the altar.'),
  ('b95496e9-11fd-5f72-ad42-20aa8656f9dd', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 17, 17, 'You shall cut the ram into its pieces, and wash its innards, and its legs, and put them with its pieces, and with its head.'),
  ('213302c2-7ba3-591e-ad41-f4d899784eda', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 18, 18, 'You shall burn the whole ram on the altar: it is a burnt offering to Yahweh; it is a pleasant aroma, an offering made by fire to Yahweh.'),
  ('99c8b38f-3bd6-5f10-ac47-72ec65ff686a', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 19, 19, '"You shall take the other ram; and Aaron and his sons shall lay their hands on the head of the ram.'),
  ('b45f7ddf-bc4c-5d85-af8d-a64637301c62', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 20, 20, 'Then you shall kill the ram, and take some of its blood, and put it on the tip of the right ear of Aaron, and on the tip of the right ear of his sons, and on the thumb of their right hand, and on the big toe of their right foot, and sprinkle the blood around on the altar.'),
  ('fb860673-a46f-5dd6-a604-fe8f68b3d09e', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 21, 21, 'You shall take of the blood that is on the altar, and of the anointing oil, and sprinkle it on Aaron, and on his garments, and on his sons, and on the garments of his sons with him: and he shall be made holy, and his garments, and his sons, and his sons'' garments with him.'),
  ('19a76219-d89f-5e80-aaa4-9d1654a9a801', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 22, 22, 'Also you shall take some of the ram''s fat, the fat tail, the fat that covers the innards, the cover of the liver, the two kidneys, the fat that is on them, and the right thigh (for it is a ram of consecration),'),
  ('63742043-4eae-57b8-a627-c7dcf7efd3bf', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 23, 23, 'and one loaf of bread, one cake of oiled bread, and one wafer out of the basket of unleavened bread that is before Yahweh.'),
  ('3709a402-a186-5fe9-a22d-cbec084a3e94', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 24, 24, 'You shall put all of this in Aaron''s hands, and in his sons'' hands, and shall wave them for a wave offering before Yahweh.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('eaa9d8c8-8b45-50c2-aa3b-127fa51d15e1', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 25, 25, 'You shall take them from their hands, and burn them on the altar on the burnt offering, for a pleasant aroma before Yahweh: it is an offering made by fire to Yahweh.'),
  ('f8c8a0ab-1936-5f94-a910-1849e63d8d3d', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 26, 26, '"You shall take the breast of Aaron''s ram of consecration, and wave it for a wave offering before Yahweh: and it shall be your portion.'),
  ('04681068-06f8-5652-a23f-8b41cd738ad0', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 27, 27, 'You shall sanctify the breast of the wave offering, and the thigh of the wave offering, which is waved, and which is heaved up, of the ram of consecration, even of that which is for Aaron, and of that which is for his sons:'),
  ('2f579815-27ca-5034-a38e-a5fb8bc5d985', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 28, 28, 'and it shall be for Aaron and his sons as their portion forever from the children of Israel; for it is a wave offering: and it shall be a wave offering from the children of Israel of the sacrifices of their peace offerings, even their wave offering to Yahweh.'),
  ('994c9726-2729-5863-a64a-35613234e351', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 29, 29, '"The holy garments of Aaron shall be for his sons after him, to be anointed in them, and to be consecrated in them.'),
  ('1d23162f-7418-5b00-ade1-8083c7a603f4', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 30, 30, 'Seven days shall the son who is priest in his place put them on, when he comes into the Tent of Meeting to minister in the holy place.'),
  ('c5f71bff-f99a-576b-a970-6c23b21a2872', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 31, 31, '"You shall take the ram of consecration, and boil its flesh in a holy place.'),
  ('cc6f6c0d-887f-505c-a966-7b77745b90ff', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 32, 32, 'Aaron and his sons shall eat the flesh of the ram, and the bread that is in the basket, at the door of the Tent of Meeting.'),
  ('def324dc-2081-5e40-a1c1-4ede982a7b53', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 33, 33, 'They shall eat those things with which atonement was made, to consecrate and sanctify them: but a stranger shall not eat of it, because they are holy.'),
  ('593fc2c6-5a7f-5aee-aa01-89ee3553bfdf', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 34, 34, 'If anything of the flesh of the consecration, or of the bread, remains to the morning, then you shall burn the remainder with fire: it shall not be eaten, because it is holy.'),
  ('d4764a6a-238e-5226-ae05-49db8de384ab', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 35, 35, '"You shall do so to Aaron, and to his sons, according to all that I have commanded you. You shall consecrate them seven days.'),
  ('aad43980-8954-53f9-afa4-4929051c8a40', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 36, 36, 'Every day you shall offer the bull of sin offering for atonement: and you shall cleanse the altar, when you make atonement for it; and you shall anoint it, to sanctify it.'),
  ('745a2149-ff0d-5514-ab34-4a2365633f49', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 37, 37, 'Seven days you shall make atonement for the altar, and sanctify it: and the altar shall be most holy; whatever touches the altar shall be holy.'),
  ('c154b904-4209-5773-ac52-75443212c027', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 38, 38, '"Now this is that which you shall offer on the altar: two lambs a year old day by day continually.'),
  ('fdd0d30f-d1cd-5418-a206-cfe6569eb7f2', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 39, 39, 'The one lamb you shall offer in the morning; and the other lamb you shall offer at evening:'),
  ('ba6a5723-b27e-5145-a76a-3ba4b3a34e49', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 40, 40, 'and with the one lamb a tenth part of an ephah of fine flour mixed with the fourth part of a hin of beaten oil, and the fourth part of a hin of wine for a drink offering.'),
  ('53cc9b29-bacd-5198-ae86-16aa96216ffb', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 41, 41, 'The other lamb you shall offer at evening, and shall do to it according to the meal offering of the morning, and according to its drink offering, for a pleasant aroma, an offering made by fire to Yahweh.'),
  ('5816cf20-64e1-5ecf-aa6c-77b5031d7b2d', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 42, 42, 'It shall be a continual burnt offering throughout your generations at the door of the Tent of Meeting before Yahweh, where I will meet with you, to speak there to you.'),
  ('b8b47d24-b6c2-542c-aa91-1f050f298900', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 43, 43, 'There I will meet with the children of Israel; and the place shall be sanctified by my glory.'),
  ('1288101d-d184-592d-a6cb-c24faba0e144', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 44, 44, 'I will sanctify the Tent of Meeting and the altar: Aaron also and his sons I will sanctify, to minister to me in the priest''s office.'),
  ('ef83bd28-342f-5816-ab16-9c35f0340b0b', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 45, 45, 'I will dwell among the children of Israel, and will be their God.'),
  ('8c9ad947-717a-5259-a8ab-6ae085013973', '4859c7e9-2c2f-5c1c-a2a6-e67f0efd17c3', NULL, 46, 46, 'They shall know that I am Yahweh their God, who brought them forth out of the land of Egypt, that I might dwell among them: I am Yahweh their God.'),
  ('cb91a044-fec4-5dab-ae67-ff78430120e9', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 1, 1, '"You shall make an altar to burn incense on. You shall make it of acacia wood.'),
  ('08c1dbea-c039-523b-a338-c295209f841e', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 2, 2, 'Its length shall be a cubit, and its breadth a cubit. It shall be square, and its height shall be two cubits. Its horns shall be of one piece with it.'),
  ('3c0e203c-2c0b-57f2-a892-fa694ad8b5f0', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 3, 3, 'You shall overlay it with pure gold, its top, its sides around it, and its horns; and you shall make a gold molding around it.'),
  ('6b36f671-b985-54ab-acbe-d858f4c6a501', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 4, 4, 'You shall make two golden rings for it under its molding; on its two ribs, on its two sides you shall make them; and they shall be for places for poles with which to bear it.'),
  ('99e6b454-ab8a-5d2e-a963-beeef087f45e', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 5, 5, 'You shall make the poles of acacia wood, and overlay them with gold.'),
  ('e655f204-b912-5a61-a777-96998be74919', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 6, 6, 'You shall put it before the veil that is by the ark of the testimony, before the mercy seat that is over the testimony, where I will meet with you.'),
  ('fc8f9775-b5b5-59de-acb3-84ba664f1980', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 7, 7, 'Aaron shall burn incense of sweet spices on it every morning. When he tends the lamps, he shall burn it.'),
  ('8c85a8e2-8800-52a5-aa1c-8388ed5c3ca9', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 8, 8, 'When Aaron lights the lamps at evening, he shall burn it, a perpetual incense before Yahweh throughout your generations.'),
  ('87bbc35f-5e77-5b85-a6b9-c63298b4a0b8', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 9, 9, 'You shall offer no strange incense on it, nor burnt offering, nor meal offering; and you shall pour no drink offering on it.'),
  ('43735c7f-9b85-5a81-a296-8cceb4bcc718', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 10, 10, 'Aaron shall make atonement on its horns once in the year; with the blood of the sin offering of atonement once in the year he shall make atonement for it throughout your generations. It is most holy to Yahweh."'),
  ('6bf3240c-c9d6-5107-a576-75f1d150582c', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 11, 11, 'Yahweh spoke to Moses, saying,'),
  ('91a281b9-e951-575e-af91-3170d32b9752', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 12, 12, '"When you take a census of the children of Israel, according to those who are numbered among them, then each man shall give a ransom for his soul to Yahweh, when you number them; that there be no plague among them when you number them.'),
  ('b1038ca7-a50a-5958-ac93-1669de166de4', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 13, 13, 'They shall give this, everyone who passes over to those who are numbered, half a shekel after the shekel of the sanctuary; (the shekel is twenty gerahs;) half a shekel for an offering to Yahweh.'),
  ('6bf3f2e7-4a70-5942-a03e-6b67aa74288f', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 14, 14, 'Everyone who passes over to those who are numbered, from twenty years old and upward, shall give the offering to Yahweh.'),
  ('d02b0240-eeb6-5d38-a104-0c49a150726c', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 15, 15, 'The rich shall not give more, and the poor shall not give less, than the half shekel, when they give the offering of Yahweh, to make atonement for your souls.'),
  ('b7569910-f58a-5905-a9f7-0ee62f789e24', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 16, 16, 'You shall take the atonement money from the children of Israel, and shall appoint it for the service of the Tent of Meeting; that it may be a memorial for the children of Israel before Yahweh, to make atonement for your souls."'),
  ('cf2f9c04-c471-5154-a3df-f230d6c41f5d', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 17, 17, 'Yahweh spoke to Moses, saying,'),
  ('a6613b08-00f0-5a9d-af7d-0a0068c13344', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 18, 18, '"You shall also make a basin of brass, and its base of brass, in which to wash. You shall put it between the Tent of Meeting and the altar, and you shall put water in it.'),
  ('70c25544-a690-5419-a458-7be252d74d72', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 19, 19, 'Aaron and his sons shall wash their hands and their feet in it.'),
  ('f5d1f8a6-f7e0-58d0-a967-68240a3b7569', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 20, 20, 'When they go into the Tent of Meeting, they shall wash with water, that they not die; or when they come near to the altar to minister, to burn an offering made by fire to Yahweh.'),
  ('0c876b20-2b59-59d2-afc6-3615c7bbe6aa', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 21, 21, 'So they shall wash their hands and their feet, that they not die: and it shall be a statute forever to them, even to him and to his descendants throughout their generations."'),
  ('7650fb70-2719-569d-aa8c-02511ed5ef67', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 22, 22, 'Moreover Yahweh spoke to Moses, saying,'),
  ('0e92a83f-7d08-50c4-a68b-f1bf577c5cf7', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 23, 23, '"Also take fine spices: of liquid myrrh, five hundred shekels; and of fragrant cinnamon half as much, even two hundred and fifty; and of fragrant cane, two hundred and fifty;'),
  ('b2f3216e-67df-542c-a8cb-517be0df01ea', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 24, 24, 'and of cassia five hundred, after the shekel of the sanctuary; and a hin of olive oil.'),
  ('f488d845-9246-592b-a696-217fd04340af', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 25, 25, 'You shall make it a holy anointing oil, a perfume compounded after the art of the perfumer: it shall be a holy anointing oil.'),
  ('bdcefad5-01e4-52a7-af1e-2f91c2e078af', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 26, 26, 'You shall use it to anoint the Tent of Meeting, the ark of the testimony,'),
  ('6a77ccc7-2788-52a4-a9f6-724aac51ecaf', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 27, 27, 'the table and all its articles, the lampstand and its accessories, the altar of incense,'),
  ('89342945-ac32-50a3-a411-e5d5f8f7384f', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 28, 28, 'the altar of burnt offering with all its utensils, and the basin with its base.'),
  ('ec605593-b35d-5e55-a25f-469763cec451', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 29, 29, 'You shall sanctify them, that they may be most holy. Whatever touches them shall be holy.'),
  ('629c0687-5984-5f9b-a1a4-795fa889ee29', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 30, 30, 'You shall anoint Aaron and his sons, and sanctify them, that they may minister to me in the priest''s office.'),
  ('75f84376-5aa9-5fa9-a07d-89f171c383ec', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 31, 31, 'You shall speak to the children of Israel, saying, ''This shall be a holy anointing oil to me throughout your generations.'),
  ('211e118e-284f-5af8-a7e3-5c5c30a435ce', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 32, 32, 'It shall not be poured on man''s flesh, neither shall you make any like it, according to its composition: it is holy. It shall be holy to you.'),
  ('01ee36ba-4bd1-516a-afe1-87c043ac83db', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 33, 33, 'Whoever compounds any like it, or whoever puts any of it on a stranger, he shall be cut off from his people.''"'),
  ('8a309c02-0ad2-5169-a796-e0e442109651', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 34, 34, 'Yahweh said to Moses, "Take to yourself sweet spices, gum resin, and onycha, and galbanum; sweet spices with pure frankincense: of each shall there be an equal weight;'),
  ('45fe625e-bf0e-55bd-af27-201924a92ec6', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 35, 35, 'and you shall make incense of it, a perfume after the art of the perfumer, seasoned with salt, pure and holy:'),
  ('89770d1e-5b3c-51ed-a68b-1f1fffb598f4', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 36, 36, 'and you shall beat some of it very small, and put some of it before the testimony in the Tent of Meeting, where I will meet with you. It shall be to you most holy.'),
  ('82e90af6-3cfc-5a96-ae80-df0a4c411841', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 37, 37, 'The incense which you shall make, according to its composition you shall not make for yourselves: it shall be to you holy for Yahweh.'),
  ('6e3b72d1-ddc3-5f23-ae4a-197fcec41374', 'a1cafd31-c819-5fde-adf7-fea9f1c1e90c', NULL, 38, 38, 'Whoever shall make any like that, to smell of it, he shall be cut off from his people."'),
  ('7b6cef01-47e6-5651-aac1-efb8a4e941d6', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('ae8eb4c0-4880-51dd-a6e8-1b679e7af846', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 2, 2, '"Behold, I have called by name Bezalel the son of Uri, the son of Hur, of the tribe of Judah:'),
  ('0a799c78-253f-51d2-a4ee-297062c85b62', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 3, 3, 'and I have filled him with the Spirit of God, in wisdom, and in understanding, and in knowledge, and in all kinds of workmanship,'),
  ('82ab0575-f854-5b1d-a9e1-9a03e1ab75ca', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 4, 4, 'to devise skillful works, to work in gold, and in silver, and in brass,'),
  ('8429fff2-25ae-5518-ae9a-1bada3e95a57', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 5, 5, 'and in cutting of stones for setting, and in carving of wood, to work in all kinds of workmanship.'),
  ('ebe12201-30e8-50e9-a3b0-de6e2468e92f', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 6, 6, 'I, behold, I have appointed with him Oholiab, the son of Ahisamach, of the tribe of Dan; and in the heart of all who are wise-hearted I have put wisdom, that they may make all that I have commanded you:'),
  ('33027072-4a2e-5d4a-ad86-ec4e833711eb', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 7, 7, 'the Tent of Meeting, the ark of the testimony, the mercy seat that is on it, all the furniture of the Tent,'),
  ('777cc360-1b57-5851-aee4-acf01be5480f', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 8, 8, 'the table and its vessels, the pure lampstand with all its vessels, the altar of incense,'),
  ('5b440b07-9575-5c3e-a82e-e348063b8b31', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 9, 9, 'the altar of burnt offering with all its vessels, the basin and its base,'),
  ('6e6bf2eb-9a7d-5e34-a330-4551e9656f41', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 10, 10, 'the finely worked garments--the holy garments for Aaron the priest--the garments of his sons to minister in the priest''s office,'),
  ('b3e6e2d0-d080-56d5-a3ea-2d27df8605f4', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 11, 11, 'the anointing oil, and the incense of sweet spices for the holy place: according to all that I have commanded you they shall do."'),
  ('67460bb2-ac7f-56cd-a0b3-c8736d6bf520', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 12, 12, 'Yahweh spoke to Moses, saying,'),
  ('45906d29-a9b2-5a33-ace0-50c04296f7bc', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 13, 13, '"Speak also to the children of Israel, saying, ''Most certainly you shall keep my Sabbaths: for it is a sign between me and you throughout your generations; that you may know that I am Yahweh who sanctifies you.'),
  ('57f52148-b5f9-5a51-a4ea-1576f6f29dab', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 14, 14, 'You shall keep the Sabbath therefore; for it is holy to you. Everyone who profanes it shall surely be put to death; for whoever does any work therein, that soul shall be cut off from among his people.'),
  ('14296ad7-2532-50e8-a420-3e5731900275', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 15, 15, 'Six days shall work be done, but on the seventh day is a Sabbath of solemn rest, holy to Yahweh. Whoever does any work on the Sabbath day shall surely be put to death.'),
  ('92663a18-3d74-5e16-a86f-58e406e0dfbd', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 16, 16, 'Therefore the children of Israel shall keep the Sabbath, to observe the Sabbath throughout their generations, for a perpetual covenant.'),
  ('4ddda563-af26-50a1-a574-a23a6d72e3d7', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 17, 17, 'It is a sign between me and the children of Israel forever; for in six days Yahweh made heaven and earth, and on the seventh day he rested, and was refreshed.''"'),
  ('8d5e9fde-3fa1-57a4-ad24-5c3dc09e4387', 'd235511a-19a5-519b-ac12-5bdfd7610e65', NULL, 18, 18, 'He gave to Moses, when he finished speaking with him on Mount Sinai, the two tablets of the testimony, stone tablets, written with God''s finger.'),
  ('58d33840-8836-5cba-a90f-be23ed4725ba', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 1, 1, 'When the people saw that Moses delayed to come down from the mountain, the people gathered themselves together to Aaron, and said to him, "Come, make us gods, which shall go before us; for as for this Moses, the man who brought us up out of the land of Egypt, we don''t know what has become of him."'),
  ('ff6a7583-d8fd-5fd4-a250-e63fe63bb9a7', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 2, 2, 'Aaron said to them, "Take off the golden rings, which are in the ears of your wives, of your sons, and of your daughters, and bring them to me."'),
  ('3d2f6a2a-dff2-58cc-ae81-eef83d4968b5', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 3, 3, 'All the people took off the golden rings which were in their ears, and brought them to Aaron.'),
  ('9e689518-86df-5559-a3c3-718f044a8815', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 4, 4, 'He received what they handed him, and fashioned it with an engraving tool, and made it a molten calf; and they said, "These are your gods, Israel, which brought you up out of the land of Egypt."'),
  ('6976a4ac-e363-5bf5-a5a1-2637f92473a3', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 5, 5, 'When Aaron saw this, he built an altar before it; and Aaron made a proclamation, and said, "Tomorrow shall be a feast to Yahweh."'),
  ('4aef1458-3a34-5910-a673-ee3052df5ff5', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 6, 6, 'They rose up early on the next day, and offered burnt offerings, and brought peace offerings; and the people sat down to eat and to drink, and rose up to play.'),
  ('3bfdb286-924c-5ee8-aadc-9f9971d6a8e7', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 7, 7, 'Yahweh spoke to Moses, "Go, get down; for your people, who you brought up out of the land of Egypt, have corrupted themselves!'),
  ('5cb4e85a-94bb-5399-afc9-7742813712ac', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 8, 8, 'They have turned aside quickly out of the way which I commanded them. They have made themselves a molten calf, and have worshiped it, and have sacrificed to it, and said, ''These are your gods, Israel, which brought you up out of the land of Egypt.''"'),
  ('fbb55fa0-fa72-59ac-ad1d-5f1d4124548d', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 9, 9, 'Yahweh said to Moses, "I have seen these people, and behold, they are a stiff-necked people.'),
  ('87baff2d-e8f4-5cd1-a219-9306a2c5560b', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 10, 10, 'Now therefore leave me alone, that my wrath may burn hot against them, and that I may consume them; and I will make of you a great nation."'),
  ('7dd3a40e-b9e9-58bf-ad02-42a8b29596b3', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 11, 11, 'Moses begged Yahweh his God, and said, "Yahweh, why does your wrath burn hot against your people, that you have brought forth out of the land of Egypt with great power and with a mighty hand?'),
  ('002c35ea-fe2b-56e0-a0d5-dd3ba1897086', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 12, 12, 'Why should the Egyptians speak, saying, ''He brought them forth for evil, to kill them in the mountains, and to consume them from the surface of the earth?'' Turn from your fierce wrath, and repent of this evil against your people.'),
  ('ecf4b728-40b4-5f70-ada5-90bc80e43128', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 13, 13, 'Remember Abraham, Isaac, and Israel, your servants, to whom you swore by your own self, and said to them, ''I will multiply your seed as the stars of the sky, and all this land that I have spoken of I will give to your seed, and they shall inherit it forever.''"'),
  ('ef7da274-adfe-50dc-a640-0841fb394458', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 14, 14, 'Yahweh repented of the evil which he said he would do to his people.'),
  ('e34250ea-68b0-51ce-a1de-973c6658a612', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 15, 15, 'Moses turned, and went down from the mountain, with the two tablets of the testimony in his hand; tablets that were written on both their sides; on the one side and on the other they were written.'),
  ('fa5885f6-3f76-57bb-ad56-c8143e71f01e', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 16, 16, 'The tablets were the work of God, and the writing was the writing of God, engraved on the tables.'),
  ('eea38533-af2e-5155-ae12-ab32ef3c34da', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 17, 17, 'When Joshua heard the noise of the people as they shouted, he said to Moses, "There is the noise of war in the camp."'),
  ('d5e3f23a-6f0d-5ffc-a783-c583b61334d6', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 18, 18, 'He said, "It isn''t the voice of those who shout for victory, neither is it the voice of those who cry for being overcome; but the noise of those who sing that I hear."'),
  ('72cd4e92-0863-5279-a838-cf51c0178ad0', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 19, 19, 'It happened, as soon as he came near to the camp, that he saw the calf and the dancing: and Moses'' anger grew hot, and he threw the tablets out of his hands, and broke them beneath the mountain.'),
  ('d27dc8a6-bd10-5afd-a9da-a15124cd21ec', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 20, 20, 'He took the calf which they had made, and burnt it with fire, ground it to powder, and scattered it on the water, and made the children of Israel drink of it.'),
  ('1696dfb4-4219-5964-a5a4-2f9ecea550b1', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 21, 21, 'Moses said to Aaron, "What did these people do to you, that you have brought a great sin on them?"'),
  ('9020f8d8-b132-5c56-ae88-8a3e4ef3695e', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 22, 22, 'Aaron said, "Don''t let the anger of my lord grow hot. You know the people, that they are set on evil.'),
  ('6c3d00c4-a4a4-5c3c-a6b5-e2e87bbd7fb0', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 23, 23, 'For they said to me, ''Make us gods, which shall go before us; for as for this Moses, the man who brought us up out of the land of Egypt, we don''t know what has become of him.'''),
  ('547502fd-9b79-5ea8-a18c-eab5cf7b485b', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 24, 24, 'I said to them, ''Whoever has any gold, let them take it off:'' so they gave it to me; and I threw it into the fire, and out came this calf."'),
  ('317e32d9-e85a-5850-af04-7886653f65d5', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 25, 25, 'When Moses saw that the people had broken loose, (for Aaron had let them loose for a derision among their enemies),'),
  ('ebbb4b82-5637-5ded-a33d-50fdaa483895', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 26, 26, 'then Moses stood in the gate of the camp, and said, "Whoever is on Yahweh''s side, come to me!" All the sons of Levi gathered themselves together to him.'),
  ('adb72fe3-be27-54b8-aa47-a1f385638508', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 27, 27, 'He said to them, "Thus says Yahweh, the God of Israel, ''Every man put his sword on his thigh, and go back and forth from gate to gate throughout the camp, and every man kill his brother, and every man his companion, and every man his neighbor.''"'),
  ('56b7477f-646a-51e9-a23f-e4cb1fcd9199', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 28, 28, 'The sons of Levi did according to the word of Moses: and there fell of the people that day about three thousand men.'),
  ('0f396bd4-518d-56ac-a2b9-b5db277d1b85', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 29, 29, 'Moses said, "Consecrate yourselves today to Yahweh, yes, every man against his son, and against his brother; that he may bestow on you a blessing this day."'),
  ('286b7546-798e-54be-abdd-4b88fbdf578a', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 30, 30, 'It happened on the next day, that Moses said to the people, "You have sinned a great sin. Now I will go up to Yahweh. Perhaps I shall make atonement for your sin."'),
  ('23c0b347-4249-5fba-a8af-7db7397b26ae', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 31, 31, 'Moses returned to Yahweh, and said, "Oh, this people have sinned a great sin, and have made themselves gods of gold.'),
  ('b32e9b8f-e399-503b-a0e9-be4489c7ef81', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 32, 32, 'Yet now, if you will, forgive their sin--and if not, please blot me out of your book which you have written."'),
  ('2f08fd8e-098e-5833-a837-a233d79b44c4', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 33, 33, 'Yahweh said to Moses, "Whoever has sinned against me, him will I blot out of my book.'),
  ('08bcc520-fa2a-5de4-af8b-20d5b04e9fd2', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 34, 34, 'Now go, lead the people to the place of which I have spoken to you. Behold, my angel shall go before you. Nevertheless in the day when I punish, I will punish them for their sin."'),
  ('8a2167a1-6c44-51d5-a980-81189c2a0dad', 'ca1d06b8-799e-5509-ac51-fcbd3254416b', NULL, 35, 35, 'Yahweh struck the people, because they made the calf, which Aaron made.'),
  ('b8a00989-46fd-5406-a666-9bddac623d8b', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 1, 1, 'Yahweh spoke to Moses, "Depart, go up from here, you and the people that you have brought up out of the land of Egypt, to the land of which I swore to Abraham, to Isaac, and to Jacob, saying, ''I will give it to your seed.'''),
  ('bdd1db38-8418-502b-abd3-54e761423e19', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 2, 2, 'I will send an angel before you; and I will drive out the Canaanite, the Amorite, and the Hittite, and the Perizzite, the Hivite, and the Jebusite:'),
  ('f4c1d318-8d36-560e-a783-a52621ab6063', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 3, 3, 'to a land flowing with milk and honey: for I will not go up in the midst of you, for you are a stiff-necked people, lest I consume you in the way."'),
  ('50726b49-75de-5982-a72c-6fce18721abf', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 4, 4, 'When the people heard this evil news, they mourned: and no one put on his jewelry.'),
  ('c79146db-a8b8-5e11-a272-3d1be0ed6add', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 5, 5, 'Yahweh said to Moses, "Tell the children of Israel, ''You are a stiff-necked people. If I were to go up into your midst for one moment, I would consume you. Therefore now take off your jewelry from you, that I may know what to do to you.''"'),
  ('c64276b6-4717-5279-a62b-0c40b06d2ea1', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 6, 6, 'The children of Israel stripped themselves of their jewelry from Mount Horeb onward.'),
  ('d0887bdc-81e0-5197-a199-17aee4a0a75d', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 7, 7, 'Now Moses used to take the tent and to pitch it outside the camp, far away from the camp, and he called it "The Tent of Meeting." It happened that everyone who sought Yahweh went out to the Tent of Meeting, which was outside the camp.'),
  ('43051d6b-68a4-56c5-ae71-0c211f1db510', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 8, 8, 'It happened that when Moses went out to the Tent, that all the people rose up, and stood, everyone at their tent door, and watched Moses, until he had gone into the Tent.'),
  ('ffa75fc8-b0cf-554f-aa73-947c3adbbabc', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 9, 9, 'It happened, when Moses entered into the Tent, that the pillar of cloud descended, stood at the door of the Tent, and spoke with Moses.'),
  ('3803dfe7-9c6c-5ed2-a966-7fe941ed19d7', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 10, 10, 'All the people saw the pillar of cloud stand at the door of the Tent, and all the people rose up and worshiped, everyone at their tent door.'),
  ('ec580cf1-903c-5771-a7b2-85d14b55eae9', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 11, 11, 'Yahweh spoke to Moses face to face, as a man speaks to his friend. He turned again into the camp, but his servant Joshua, the son of Nun, a young man, didn''t depart out of the Tent.'),
  ('642d855e-143f-51b0-aa31-864936438432', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 12, 12, 'Moses said to Yahweh, "Behold, you tell me, ''Bring up this people:'' and you haven''t let me know whom you will send with me. Yet you have said, ''I know you by name, and you have also found favor in my sight.'''),
  ('c6a643ab-d4e3-572e-a447-63bb23913f1c', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 13, 13, 'Now therefore, if I have found favor in your sight, please show me now your ways, that I may know you, so that I may find favor in your sight: and consider that this nation is your people."'),
  ('1be4b388-8490-5d03-aeab-e5d78e4479f4', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 14, 14, 'He said, "My presence will go with you, and I will give you rest."'),
  ('f7254962-d2bf-5687-a729-d4d85e9c15b2', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 15, 15, 'He said to him, "If your presence doesn''t go with me, don''t carry us up from here.'),
  ('79adba03-3f0c-5992-a9f7-88c2fba6311c', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 16, 16, 'For how would people know that I have found favor in your sight, I and your people? Isn''t it in that you go with us, so that we are separated, I and your people, from all the people who are on the surface of the earth?"'),
  ('6dcedf46-37eb-5e11-a89f-eecac66947b0', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 17, 17, 'Yahweh said to Moses, "I will do this thing also that you have spoken; for you have found favor in my sight, and I know you by name."'),
  ('c861d993-6653-5131-a34b-a9951ea136b3', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 18, 18, 'He said, "Please show me your glory."'),
  ('df8acd68-3a08-5597-aefc-fbe5ef1feaa6', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 19, 19, 'He said, "I will make all my goodness pass before you, and will proclaim the name of Yahweh before you. I will be gracious to whom I will be gracious, and will show mercy on whom I will show mercy."'),
  ('4be23cef-f6e3-50db-a6ae-41752d4502d5', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 20, 20, 'He said, "You cannot see my face, for man may not see me and live."'),
  ('3225af7f-df36-51a1-aaa3-3c1c8994a4a1', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 21, 21, 'Yahweh also said, "Behold, there is a place by me, and you shall stand on the rock.'),
  ('b6abac56-b802-576c-a570-3930aff75f98', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 22, 22, 'It will happen, while my glory passes by, that I will put you in a cleft of the rock, and will cover you with my hand until I have passed by;'),
  ('212d8fcf-72b3-5993-a921-802639abf1cc', '40f29f69-19f9-5c63-aae3-50e3267b5370', NULL, 23, 23, 'then I will take away my hand, and you will see my back; but my face shall not be seen."'),
  ('a92210ac-5cb0-57b2-a37e-989bcf777c6c', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 1, 1, 'Yahweh said to Moses, "Chisel two stone tablets like the first: and I will write on the tablets the words that were on the first tablets, which you broke.'),
  ('46de21e2-fbb6-5246-adbd-4c0307e422ff', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 2, 2, 'Be ready by the morning, and come up in the morning to Mount Sinai, and present yourself there to me on the top of the mountain.'),
  ('b9f4b244-d6c6-5d99-a987-6274e55bd6a0', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 3, 3, 'No one shall come up with you; neither let anyone be seen throughout all the mountain; neither let the flocks nor herds feed before that mountain."'),
  ('d17b2981-7b96-59ef-ae5a-f78f7ef5af2b', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 4, 4, 'He chiseled two tablets of stone like the first; and Moses rose up early in the morning, and went up to Mount Sinai, as Yahweh had commanded him, and took in his hand two stone tablets.'),
  ('41f890e3-920e-5f62-a88b-4eba78217d06', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 5, 5, 'Yahweh descended in the cloud, and stood with him there, and proclaimed the name of Yahweh.'),
  ('e4119adc-fb88-55a4-a3aa-6142cdf8365f', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 6, 6, 'Yahweh passed by before him, and proclaimed, "Yahweh! Yahweh, a merciful and gracious God, slow to anger, and abundant in loving kindness and truth,'),
  ('0619f466-45b4-585d-a0eb-c72804766ad3', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 7, 7, 'keeping loving kindness for thousands, forgiving iniquity and disobedience and sin; and that will by no means clear the guilty, visiting the iniquity of the fathers on the children, and on the children''s children, on the third and on the fourth generation."'),
  ('dfd3b71a-2d5c-537f-aaa5-faac447a9552', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 8, 8, 'Moses hurried and bowed his head toward the earth, and worshiped.'),
  ('14fccbb1-11a0-5976-a68d-d03d8bfafcab', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 9, 9, 'He said, "If now I have found favor in your sight, Lord, please let the Lord go in the midst of us; although this is a stiff-necked people; pardon our iniquity and our sin, and take us for your inheritance."'),
  ('af1992ed-ec90-578a-aac8-36ef10853294', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 10, 10, 'He said, "Behold, I make a covenant: before all your people I will do marvels, such as have not been worked in all the earth, nor in any nation; and all the people among which you are shall see the work of Yahweh; for it is an awesome thing that I do with you.'),
  ('8dc821cd-e7f7-5d01-a5c0-2f842a99ad36', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 11, 11, 'Observe that which I command you this day. Behold, I drive out before you the Amorite, the Canaanite, the Hittite, the Perizzite, the Hivite, and the Jebusite.'),
  ('5151ab5a-0dcc-5f3a-aa59-2653c385de4e', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 12, 12, 'Be careful, lest you make a covenant with the inhabitants of the land where you are going, lest it be for a snare in the midst of you:'),
  ('f4296d04-9865-5592-af0d-8bc28b48e0ec', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 13, 13, 'but you shall break down their altars, and dash in pieces their pillars, and you shall cut down their Asherim;'),
  ('888de6ff-f6a2-5bcc-acdf-66f6a2110fb4', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 14, 14, 'for you shall worship no other god: for Yahweh, whose name is Jealous, is a jealous God.'),
  ('9e77e845-6a0d-577c-a2a4-ea95bf5dde8b', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 15, 15, '"Don''t make a covenant with the inhabitants of the land, lest they play the prostitute after their gods, and sacrifice to their gods, and one call you and you eat of his sacrifice;'),
  ('0c3421e2-7f37-5e5c-a603-a002f84e7d87', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 16, 16, 'and you take of their daughters to your sons, and their daughters play the prostitute after their gods, and make your sons play the prostitute after their gods.'),
  ('d65102e2-e8f9-54ee-aa1c-3f097a7331a9', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 17, 17, '"You shall make no cast idols for yourselves.'),
  ('2db3fd82-0d09-5771-a1e7-d4aabdd0516b', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 18, 18, '"You shall keep the feast of unleavened bread. Seven days you shall eat unleavened bread, as I commanded you, at the time appointed in the month Abib; for in the month Abib you came out from Egypt.'),
  ('3552c8b2-2fb7-53c2-a9b8-4bf88590a38b', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 19, 19, '"All that opens the womb is mine; and all your livestock that is male, the firstborn of cow and sheep.'),
  ('4634e2bc-7c98-561d-a08a-6adfa4d3e1d8', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 20, 20, 'The firstborn of a donkey you shall redeem with a lamb: and if you will not redeem it, then you shall break its neck. All the firstborn of your sons you shall redeem. No one shall appear before me empty.'),
  ('b931ceaa-bab8-5ab7-a477-9ae27cffb296', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 21, 21, '"Six days you shall work, but on the seventh day you shall rest: in plowing time and in harvest you shall rest.'),
  ('fe8c5ba7-698a-5317-a53a-65bd3473ea55', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 22, 22, '"You shall observe the feast of weeks with the first fruits of wheat harvest, and the feast of harvest at the year''s end.'),
  ('25ef0f25-58ba-5bd5-adca-233aa76f2aba', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 23, 23, 'Three times in the year all your males shall appear before the Lord Yahweh, the God of Israel.'),
  ('5ae1394d-2c32-5f21-a969-d439f65a806d', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 24, 24, 'For I will drive out nations before you and enlarge your borders; neither shall any man desire your land when you go up to appear before Yahweh, your God, three times in the year.'),
  ('ca239c28-e394-5652-acf6-052757a25000', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 25, 25, '"You shall not offer the blood of my sacrifice with leavened bread; neither shall the sacrifice of the feast of the Passover be left to the morning.'),
  ('c3c52572-e567-5c6b-a6cd-23fcef2002ad', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 26, 26, '"You shall bring the first of the first fruits of your ground to the house of Yahweh your God. "You shall not boil a young goat in its mother''s milk."'),
  ('337af85c-1c79-5b65-adc2-88033c9b63b6', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 27, 27, 'Yahweh said to Moses, "Write you these words: for in accordance with these words I have made a covenant with you and with Israel."'),
  ('61858b15-b7c1-51af-a696-e3013a0edb80', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 28, 28, 'He was there with Yahweh forty days and forty nights; he neither ate bread, nor drank water. He wrote on the tablets the words of the covenant, the ten commandments.'),
  ('b2971965-463b-576b-adab-c9455e61cfe0', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 29, 29, 'It happened, when Moses came down from Mount Sinai with the two tablets of the testimony in Moses'' hand, when he came down from the mountain, that Moses didn''t know that the skin of his face shone by reason of his speaking with him.'),
  ('ee231972-13e9-552e-ad12-2acca28de692', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 30, 30, 'When Aaron and all the children of Israel saw Moses, behold, the skin of his face shone; and they were afraid to come near him.'),
  ('b95da500-0bf2-5f4b-ae2a-f32c2a516265', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 31, 31, 'Moses called to them, and Aaron and all the rulers of the congregation returned to him; and Moses spoke to them.'),
  ('42fa29ac-2e19-5ce9-ab61-b58279845329', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 32, 32, 'Afterward all the children of Israel came near, and he gave them all of the commandments that Yahweh had spoken with him on Mount Sinai.'),
  ('4f9c34c9-a60d-508f-a1ee-3a14f6bc2a56', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 33, 33, 'When Moses was done speaking with them, he put a veil on his face.'),
  ('ad9ebde7-cdc0-503f-a6f5-f0f7f5bac713', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 34, 34, 'But when Moses went in before Yahweh to speak with him, he took the veil off, until he came out; and he came out, and spoke to the children of Israel that which he was commanded.'),
  ('5ad89301-f754-50f5-aaa7-866bc2cb6fa3', 'b2a0c9e6-37fa-5c1d-afa6-46031006e992', NULL, 35, 35, 'The children of Israel saw Moses'' face, that the skin of Moses'' face shone: and Moses put the veil on his face again, until he went in to speak with him.'),
  ('37c8c596-85b6-5b30-a3fc-63bd4cea8410', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 1, 1, 'Moses assembled all the congregation of the children of Israel, and said to them, "These are the words which Yahweh has commanded, that you should do them.'),
  ('c35d7411-2b37-57bb-a219-399352bdf347', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 2, 2, '''Six days shall work be done, but on the seventh day there shall be a holy day for you, a Sabbath of solemn rest to Yahweh: whoever does any work in it shall be put to death.'),
  ('d1526dc2-d538-514e-ab5f-b569ee6f9b37', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 3, 3, 'You shall kindle no fire throughout your habitations on the Sabbath day.''"'),
  ('c3fd24dd-e2f9-51a6-a8c5-bbc6fc9ca633', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 4, 4, 'Moses spoke to all the congregation of the children of Israel, saying, "This is the thing which Yahweh commanded, saying,'),
  ('db3d6fc6-c48a-5182-a5d5-2083de146bb7', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 5, 5, '''Take from among you an offering to Yahweh. Whoever is of a willing heart, let him bring it, Yahweh''s offering: gold, silver, brass,'),
  ('7f3fdc28-68ce-5d4d-a85d-aeca920df1bc', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 6, 6, 'blue, purple, scarlet, fine linen, goats'' hair,'),
  ('b0ad5cfa-0112-52df-af7c-a0caab7a9344', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 7, 7, 'rams'' skins dyed red, sea cow hides, acacia wood,'),
  ('cf099e9d-3a19-5ef0-aa5d-5620189c498b', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 8, 8, 'oil for the light, spices for the anointing oil and for the sweet incense,'),
  ('f77ad891-a1d0-512d-abbc-b0ee869ab5dc', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 9, 9, 'onyx stones, and stones to be set for the ephod and for the breastplate.'),
  ('bcdd5da5-42f9-5ae3-a80d-f40d7932f1fb', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 10, 10, '"''Let every wise-hearted man among you come, and make all that Yahweh has commanded:'),
  ('14c2b9ff-f7ef-5ecf-adf1-068b5de71bc5', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 11, 11, 'the tabernacle, its outer covering, its roof, its clasps, its boards, its bars, its pillars, and its sockets;'),
  ('8ab8773c-ea94-50c4-a0e7-706f75d777a3', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 12, 12, 'the ark, and its poles, the mercy seat, the veil of the screen;'),
  ('4ddafd97-164b-5bbe-a420-38c832428376', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 13, 13, 'the table with its poles and all its vessels, and the show bread;'),
  ('a8235dcd-1cf3-5bab-aeb9-672fb26baeae', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 14, 14, 'the lampstand also for the light, with its vessels, its lamps, and the oil for the light;'),
  ('a319a36d-d2b6-55cf-a281-6712055432b2', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 15, 15, 'and the altar of incense with its poles, the anointing oil, the sweet incense, the screen for the door, at the door of the tabernacle;'),
  ('b7a36187-c4d5-57a3-a085-2de66567e16a', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 16, 16, 'the altar of burnt offering, with its grating of brass, it poles, and all its vessels, the basin and its base;'),
  ('af11e6c2-bbb7-5394-a87e-f9d38df1965a', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 17, 17, 'the hangings of the court, its pillars, their sockets, and the screen for the gate of the court;'),
  ('0f9d54d3-8e7d-5908-a704-1e84025230f3', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 18, 18, 'the pins of the tabernacle, the pins of the court, and their cords;'),
  ('af66e7ab-6b41-549f-ab84-171b253d72ce', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 19, 19, 'the finely worked garments, for ministering in the holy place, the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest''s office.''"'),
  ('e55919b8-6425-5028-a421-330101b03a3b', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 20, 20, 'All the congregation of the children of Israel departed from the presence of Moses.'),
  ('922ae99c-5a73-50f7-acc5-716ee52c6057', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 21, 21, 'They came, everyone whose heart stirred him up, and everyone whom his spirit made willing, and brought Yahweh''s offering, for the work of the Tent of Meeting, and for all of its service, and for the holy garments.'),
  ('016e9805-b990-5665-a635-2400264b2f4e', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 22, 22, 'They came, both men and women, as many as were willing-hearted, and brought brooches, earrings, signet rings, and armlets, all jewels of gold; even every man who offered an offering of gold to Yahweh.'),
  ('5a5bbd74-5118-5f42-a6a3-4c386a8cb349', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 23, 23, 'Everyone, with whom was found blue, purple, scarlet, fine linen, goats'' hair, rams'' skins dyed red, and sea cow hides, brought them.'),
  ('0b006a72-14f5-5a45-a9f7-011e334ae0ce', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 24, 24, 'Everyone who did offer an offering of silver and brass brought Yahweh''s offering; and everyone, with whom was found acacia wood for any work of the service, brought it.'),
  ('8168aae2-c04b-50ac-aea3-a9d9e5304e15', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 25, 25, 'All the women who were wise-hearted spun with their hands, and brought that which they had spun, the blue, the purple, the scarlet, and the fine linen.'),
  ('7c6127ae-bffa-572f-a3da-f784d47e9a0a', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 26, 26, 'All the women whose heart stirred them up in wisdom spun the goats'' hair.'),
  ('0921f777-e0ca-593b-abac-55cb67e14929', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 27, 27, 'The rulers brought the onyx stones, and the stones to be set, for the ephod and for the breastplate;'),
  ('28bc80e4-c2f2-5fbc-a406-fbfefc9126b3', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 28, 28, 'and the spice, and the oil for the light, for the anointing oil, and for the sweet incense.'),
  ('fcbaec2d-c070-5ac2-abfb-ee9ad1d4560d', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 29, 29, 'The children of Israel brought a freewill offering to Yahweh; every man and woman, whose heart made them willing to bring for all the work, which Yahweh had commanded to be made by Moses.'),
  ('eff1008d-c5c4-56e7-aff5-d2753418f02f', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 30, 30, 'Moses said to the children of Israel, "Behold, Yahweh has called by name Bezalel the son of Uri, the son of Hur, of the tribe of Judah.'),
  ('f484f4c7-e368-595b-ae88-ed6f7367291c', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 31, 31, 'He has filled him with the Spirit of God, in wisdom, in understanding, in knowledge, and in all kinds of workmanship;'),
  ('d73a6e66-91a9-56ec-a9ed-2774ae58af77', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 32, 32, 'and to make skillful works, to work in gold, in silver, in brass,'),
  ('b7de635f-1bfd-5f95-ab9c-6a11f1f1fb7b', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 33, 33, 'in cutting of stones for setting, and in carving of wood, to work in all kinds of skillful workmanship.'),
  ('92045538-a19d-5e0d-ac8f-c3967a1f4764', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 34, 34, 'He has put in his heart that he may teach, both he, and Oholiab, the son of Ahisamach, of the tribe of Dan.'),
  ('d533139c-2ac3-55b0-aaef-3e812ccfc314', '83aef8fc-7f66-528f-a4bd-dd2117007356', NULL, 35, 35, 'He has filled them with wisdom of heart, to work all kinds of workmanship, of the engraver, of the skillful workman, and of the embroiderer, in blue, in purple, in scarlet, and in fine linen, and of the weaver, even of those who do any workmanship, and of those who make skillful works.'),
  ('6dfd46db-e2d6-51f3-ada9-5bd4d1b10ee4', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 1, 1, '"Bezalel and Oholiab shall work with every wise-hearted man, in whom Yahweh has put wisdom and understanding to know how to work all the work for the service of the sanctuary, according to all that Yahweh has commanded."'),
  ('0fa9af24-7606-57d1-a28a-aab63660c535', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 2, 2, 'Moses called Bezalel and Oholiab, and every wise-hearted man, in whose heart Yahweh had put wisdom, even everyone whose heart stirred him up to come to the work to do it:'),
  ('6d8f9a0a-b02d-5358-ab53-361fca954367', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 3, 3, 'and they received from Moses all the offering which the children of Israel had brought for the work of the service of the sanctuary, with which to make it. They brought yet to him freewill offerings every morning.'),
  ('80d14aed-7d73-51e8-a920-ff08cd285f7c', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 4, 4, 'All the wise men, who performed all the work of the sanctuary, each came from his work which they did.'),
  ('53805237-c249-5359-a0e3-f1c2664d51ef', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 5, 5, 'They spoke to Moses, saying, "The people bring much more than enough for the service of the work which Yahweh commanded to make."'),
  ('85ea759b-ec89-5222-ace3-7a313d474f9f', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 6, 6, 'Moses gave commandment, and they caused it to be proclaimed throughout the camp, saying, "Let neither man nor woman make anything else for the offering for the sanctuary." So the people were restrained from bringing.'),
  ('91a7f1b3-a49c-526b-aaf3-70952c7719c8', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 7, 7, 'For the stuff they had was sufficient for all the work to make it, and too much.'),
  ('7cd9d7c3-79cb-5b48-ab00-2cab549824d1', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 8, 8, 'All the wise-hearted men among those who did the work made the tabernacle with ten curtains; of fine twined linen, blue, purple, and scarlet, with cherubim, the work of the skillful workman, they made them.'),
  ('9773adc3-8e3e-5395-a439-b323038125d7', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 9, 9, 'The length of each curtain was twenty-eight cubits, and the breadth of each curtain four cubits. All the curtains had one measure.'),
  ('baad5a51-32f7-5f93-a9ef-7a8d41be1dda', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 10, 10, 'He coupled five curtains to one another, and the other five curtains he coupled one to another.'),
  ('8b3cfc30-2606-515d-a945-dfa27784f0e6', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 11, 11, 'He made loops of blue on the edge of the one curtain from the edge in the coupling. Likewise he made in the edge of the curtain that was outmost in the second coupling.'),
  ('f0eb1d16-7b17-5a60-a468-128456dded65', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 12, 12, 'He made fifty loops in the one curtain, and he made fifty loops in the edge of the curtain that was in the second coupling. The loops were opposite one to another.'),
  ('4da80eaa-f870-5ee2-af39-cd419b3c9a04', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 13, 13, 'He made fifty clasps of gold, and coupled the curtains one to another with the clasps: so the tabernacle was a unit.'),
  ('732242d5-164e-552c-a424-5d369fa091fe', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 14, 14, 'He made curtains of goats'' hair for a covering over the tabernacle. He made them eleven curtains.'),
  ('c2ba0d54-cef3-55c3-a297-e72abac19271', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 15, 15, 'The length of each curtain was thirty cubits, and four cubits the breadth of each curtain. The eleven curtains had one measure.'),
  ('8ad3bcb4-2f4a-5b6a-a9ea-6bf68d6ecc2f', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 16, 16, 'He coupled five curtains by themselves, and six curtains by themselves.'),
  ('c7521563-6dec-5145-ac47-98e2cf560057', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 17, 17, 'He made fifty loops on the edge of the curtain that was outmost in the coupling, and he made fifty loops on the edge of the curtain which was outmost in the second coupling.'),
  ('d28a6d48-a38f-5f37-acce-f72588299be9', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 18, 18, 'He made fifty clasps of brass to couple the tent together, that it might be a unit.'),
  ('af84cb6c-3378-51a2-a2e4-a46830f7eb00', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 19, 19, 'He made a covering for the tent of rams'' skins dyed red, and a covering of sea cow hides above.'),
  ('7911c6de-a132-5e9c-a961-836d02e0c2ba', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 20, 20, 'He made the boards for the tabernacle of acacia wood, standing up.'),
  ('94901e99-4c77-52eb-a21e-7c4e218cb9a1', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 21, 21, 'Ten cubits was the length of a board, and a cubit and a half the breadth of each board.'),
  ('13cf0d05-2196-58b1-a025-d12afe2c8cdc', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 22, 22, 'Each board had two tenons, joined one to another. He made all the boards of the tabernacle this way.'),
  ('8d2215e7-f4d4-5ce5-a4e9-0b94c96f9db0', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 23, 23, 'He made the boards for the tabernacle: twenty boards for the south side southward.'),
  ('23793cfb-bc01-5e00-a269-323d2ba420d7', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 24, 24, 'He made forty sockets of silver under the twenty boards; two sockets under one board for its two tenons, and two sockets under another board for its two tenons.'),
  ('83046d23-1e0f-58fc-a6ec-85305059c909', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 25, 25, 'For the second side of the tabernacle, on the north side, he made twenty boards,'),
  ('227e3596-1199-5abb-a390-2df1de835376', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 26, 26, 'and their forty sockets of silver; two sockets under one board, and two sockets under another board.'),
  ('e3ba53d5-92ba-57ff-a07e-f4b7abfb67dd', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 27, 27, 'For the far part of the tabernacle westward he made six boards.'),
  ('b6162386-7dac-55f4-a0f7-d65627b369fc', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 28, 28, 'He made two boards for the corners of the tabernacle in the far part.'),
  ('31d66267-3b1b-5dc3-a927-1cfcd52f23a0', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 29, 29, 'They were double beneath, and in the same way they were all the way to its top to one ring. He did thus to both of them in the two corners.'),
  ('37b12d9d-372a-5161-ac39-c7e25a2e4493', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 30, 30, 'There were eight boards, and their sockets of silver, sixteen sockets; under every board two sockets.'),
  ('ae21f507-e4d1-5f32-aa55-e4c252aba214', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 31, 31, 'He made bars of acacia wood; five for the boards of the one side of the tabernacle,'),
  ('d8085631-a61d-56de-a8db-be0d470e40dd', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 32, 32, 'and five bars for the boards of the other side of the tabernacle, and five bars for the boards of the tabernacle for the hinder part westward.'),
  ('4bedf2e6-a6b0-5290-aab7-7fcd5d70f7c3', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 33, 33, 'He made the middle bar to pass through in the midst of the boards from the one end to the other.'),
  ('be7972be-9236-5fc2-a3a8-5abc90f288f1', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 34, 34, 'He overlaid the boards with gold, and made their rings of gold for places for the bars, and overlaid the bars with gold.'),
  ('dcec7fc4-0c2b-5075-a0db-939da66cd59c', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 35, 35, 'He made the veil of blue, purple, scarlet, and fine twined linen: with cherubim. He made it the work of a skillful workman.'),
  ('e63f6b86-7fb5-5046-aa69-fe5de6dbe8e4', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 36, 36, 'He made four pillars of acacia for it, and overlaid them with gold. Their hooks were of gold. He cast four sockets of silver for them.'),
  ('ab0160f4-f5e6-5993-ad27-6b06fc5d08c1', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 37, 37, 'He made a screen for the door of the tent, of blue, purple, scarlet, and fine twined linen, the work of an embroiderer;'),
  ('79ead7c8-306a-5f33-ab96-06db658662b0', 'beb078f0-9df0-50a2-a080-3c0bca959a1c', NULL, 38, 38, 'and the five pillars of it with their hooks. He overlaid their capitals and their fillets with gold, and their five sockets were of brass.'),
  ('833f0647-4af5-52bf-aded-6894730af704', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 1, 1, 'Bezalel made the ark of acacia wood. Its length was two and a half cubits, and its breadth a cubit and a half, and a cubit and a half its height.'),
  ('58d8e515-067c-5a58-a302-07edba790243', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 2, 2, 'He overlaid it with pure gold inside and outside, and made a molding of gold for it around it.'),
  ('8d84d5f5-1882-5f34-a6d0-8afd2f91d46e', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 3, 3, 'He cast four rings of gold for it, in its four feet; even two rings on its one side, and two rings on its other side.'),
  ('fb4caf43-bd6f-5f9e-ab66-d24aa19e4d19', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 4, 4, 'He made poles of acacia wood, and overlaid them with gold.'),
  ('99cb0c13-80bb-5ebb-a0ce-477060be3eea', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 5, 5, 'He put the poles into the rings on the sides of the ark, to bear the ark.'),
  ('d6054a65-8cd5-518e-afa7-0dba97dd34a9', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 6, 6, 'He made a mercy seat of pure gold. Its length was two and a half cubits, and a cubit and a half its breadth.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('acbdc37d-d00b-5f72-aca2-cf748714c32e', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 7, 7, 'He made two cherubim of gold. He made them of beaten work, at the two ends of the mercy seat;'),
  ('11f373f6-9bf8-535f-a697-2d12f2a9baf1', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 8, 8, 'one cherub at the one end, and one cherub at the other end. He made the cherubim of one piece with the mercy seat at its two ends.'),
  ('14854d41-428e-5d89-a79e-b69c1fcde073', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 9, 9, 'The cherubim spread out their wings on high, covering the mercy seat with their wings, with their faces toward one another. The faces of the cherubim were toward the mercy seat.'),
  ('c612b893-6b1a-5958-a19a-ac58dbdfec43', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 10, 10, 'He made the table of acacia wood. Its length was two cubits, and its breadth was a cubit, and its height was a cubit and a half.'),
  ('97b9767c-e6e5-5045-a67c-5c218741a1fe', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 11, 11, 'He overlaid it with pure gold, and made a gold molding around it.'),
  ('3528ef77-412c-5b4b-a623-849761467777', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 12, 12, 'He made a border of a handbreadth around it, and made a golden molding on its border around it.'),
  ('fc5ab6bf-8734-5e4d-a91e-2bbff6eb4ed7', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 13, 13, 'He cast four rings of gold for it, and put the rings in the four corners that were on its four feet.'),
  ('5113ec73-20a7-54c3-afba-fc1311f0a220', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 14, 14, 'The rings were close by the border, the places for the poles to carry the table.'),
  ('15d164dd-bd92-5270-a270-0dd3adeb204a', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 15, 15, 'He made the poles of acacia wood, and overlaid them with gold, to carry the table.'),
  ('a3d8859f-0c7c-5391-a236-3db47f84ff86', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 16, 16, 'He made the vessels which were on the table, its dishes, its spoons, its bowls, and its pitchers with which to pour out, of pure gold.'),
  ('050eaf55-3f8c-55cf-a134-a3f00265705f', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 17, 17, 'He made the lampstand of pure gold. He made the lampstand of beaten work. Its base, its shaft, its cups, its buds, and its flowers were of one piece with it.'),
  ('14487e3c-642d-5746-aa18-2691cbcdaff3', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 18, 18, 'There were six branches going out of its sides: three branches of the lampstand out of its one side, and three branches of the lampstand out of its other side:'),
  ('8014b0de-9d97-51a8-a01c-56f2ca3ee886', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 19, 19, 'three cups made like almond blossoms in one branch, a bud and a flower, and three cups made like almond blossoms in the other branch, a bud and a flower: so for the six branches going out of the lampstand.'),
  ('edca05ef-ad6b-5664-a66f-39c668951c81', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 20, 20, 'In the lampstand were four cups made like almond blossoms, its buds and its flowers;'),
  ('0983507a-9ca2-5c64-af1c-6bbc60da9ea7', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 21, 21, 'and a bud under two branches of one piece with it, and a bud under two branches of one piece with it, and a bud under two branches of one piece with it, for the six branches going out of it.'),
  ('2b58c983-c123-521c-a6e1-992c2aaa48b8', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 22, 22, 'Their buds and their branches were of one piece with it. The whole thing was one beaten work of pure gold.'),
  ('36363992-af4c-5e6f-a4a8-9cb85df79709', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 23, 23, 'He made its seven lamps, and its snuffers, and its snuff dishes, of pure gold.'),
  ('89f86962-2240-5db9-a019-98d7034ea9ff', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 24, 24, 'He made it of a talent of pure gold, with all its vessels.'),
  ('039e21c4-3771-5f5a-a71f-ba8043407332', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 25, 25, 'He made the altar of incense of acacia wood. It was square: its length was a cubit, and its breadth a cubit. Its height was two cubits. Its horns were of one piece with it.'),
  ('23ca8859-d20d-5af5-a1a0-bd7e68fe7ead', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 26, 26, 'He overlaid it with pure gold, its top, its sides around it, and its horns. He made a gold molding around it.'),
  ('0f4cca56-10a1-57ea-a397-bfe608b986bd', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 27, 27, 'He made two golden rings for it under its molding crown, on its two ribs, on its two sides, for places for poles with which to carry it.'),
  ('cb9f12b9-a48c-524a-a69b-55935cc01d85', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 28, 28, 'He made the poles of acacia wood, and overlaid them with gold.'),
  ('f0512fb7-9903-563a-aed9-b83c01041a82', '340210cf-35d0-5bb5-a8f7-23a8ba2cb30c', NULL, 29, 29, 'He made the holy anointing oil and the pure incense of sweet spices, after the art of the perfumer.'),
  ('4a00c6f8-e39f-54c6-a74e-9c984b26b79f', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 1, 1, 'He made the altar of burnt offering of acacia wood. It was square. Its length was five cubits, its breadth was five cubits, and its height was three cubits.'),
  ('a175d72c-ce52-5af3-a974-a5b8654d8465', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 2, 2, 'He made its horns on its four corners. Its horns were of one piece with it, and he overlaid it with brass.'),
  ('86555f47-6abb-57f3-afb5-481ae64ca5af', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 3, 3, 'He made all the vessels of the altar, the pots, the shovels, the basins, the forks, and the fire pans. He made all its vessels of brass.'),
  ('f3b20169-271c-5ed1-ae88-171e779a2017', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 4, 4, 'He made for the altar a grating of a network of brass, under the ledge around it beneath, reaching halfway up.'),
  ('cc50bb60-168e-5525-ac39-5c438f62622a', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 5, 5, 'He cast four rings for the four ends of brass grating, to be places for the poles.'),
  ('e25c1d34-b5c2-567f-aedf-4a62e3e75b7d', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 6, 6, 'He made the poles of acacia wood, and overlaid them with brass.'),
  ('3442373c-0a72-5155-a749-54562945d2c4', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 7, 7, 'He put the poles into the rings on the sides of the altar, with which to carry it. He made it hollow with planks.'),
  ('aec7b0ba-5f11-508a-a658-41fc5cdc17f8', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 8, 8, 'He made the basin of brass, and its base of brass, out of the mirrors of the ministering women who ministered at the door of the Tent of Meeting.'),
  ('cc00bc7a-ab52-5630-afd5-1d2b7c9caba5', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 9, 9, 'He made the court: for the south side southward the hangings of the court were of fine twined linen, one hundred cubits;'),
  ('4c84a755-1b60-500b-a847-249a81f1fa94', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 10, 10, 'their pillars were twenty, and their sockets twenty, of brass; the hooks of the pillars and their fillets were of silver.'),
  ('e2bc37d1-c0ff-58aa-ac95-7e121e5e8160', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 11, 11, 'For the north side one hundred cubits, their pillars twenty, and their sockets twenty, of brass; the hooks of the pillars, and their fillets, of silver.'),
  ('773d3457-49c7-59b4-ab02-e9f75dca02c3', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 12, 12, 'For the west side were hangings of fifty cubits, their pillars ten, and their sockets ten; the hooks of the pillars, and their fillets, of silver.'),
  ('5b7976a9-93e8-5c1f-a52c-8e2f20381339', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 13, 13, 'For the east side eastward fifty cubits.'),
  ('3d28e6c9-1d9e-52f4-aa09-10c2b0161e10', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 14, 14, 'The hangings for the one side were fifteen cubits; their pillars three, and their sockets three;'),
  ('a2853586-67bf-537a-ad91-d4631268bcb6', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 15, 15, 'and so for the other side: on this hand and that hand by the gate of the court were hangings of fifteen cubits; their pillars three, and their sockets three.'),
  ('48b770d8-a33f-5e11-a682-e3d270f6f778', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 16, 16, 'All the hangings around the court were of fine twined linen.'),
  ('8c5a738e-3e43-56ce-a6cc-59d2e3118554', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 17, 17, 'The sockets for the pillars were of brass. The hooks of the pillars and their fillets were of silver; and the overlaying of their capitals, of silver; and all the pillars of the court were filleted with silver.'),
  ('2563937b-8750-50ad-ae31-6873bab24a3c', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 18, 18, 'The screen for the gate of the court was the work of the embroiderer, of blue, purple, scarlet, and fine twined linen. Twenty cubits was the length, and the height in the breadth was five cubits, like to the hangings of the court.'),
  ('204f3771-6689-5cbe-a4cb-0719feb32692', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 19, 19, 'Their pillars were four, and their sockets four, of brass; their hooks of silver, and the overlaying of their capitals, and their fillets, of silver.'),
  ('42655485-43c5-56d1-adc0-7a46548ca61e', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 20, 20, 'All the pins of the tabernacle, and around the court, were of brass.'),
  ('9893d54d-bc33-5e3b-a7f2-038b2d9df38a', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 21, 21, 'This is the amount of material used for the tabernacle, even the Tabernacle of the Testimony, as they were counted, according to the commandment of Moses, for the service of the Levites, by the hand of Ithamar, the son of Aaron the priest.'),
  ('2fe4ce0f-9240-56e5-a796-5aaa4d3acb2e', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 22, 22, 'Bezalel the son of Uri, the son of Hur, of the tribe of Judah, made all that Yahweh commanded Moses.'),
  ('052c4c45-6d1b-5ee5-ab08-18cdc55f3943', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 23, 23, 'With him was Oholiab, the son of Ahisamach, of the tribe of Dan, an engraver, and a skillful workman, and an embroiderer in blue, in purple, in scarlet, and in fine linen.'),
  ('cdc50666-dc17-51dd-a5f2-e12c0ea2817b', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 24, 24, 'All the gold that was used for the work in all the work of the sanctuary, even the gold of the offering, was twenty-nine talents, and seven hundred thirty shekels, after the shekel of the sanctuary.'),
  ('df498354-c992-5888-a564-4e50b97a456f', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 25, 25, 'The silver of those who were numbered of the congregation was one hundred talents, and one thousand seven hundred seventy-five shekels, after the shekel of the sanctuary:'),
  ('fd33918a-7111-5ccf-ad01-6af2ab1d368d', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 26, 26, 'a beka a head, that is, half a shekel, after the shekel of the sanctuary, for everyone who passed over to those who were numbered, from twenty years old and upward, for six hundred three thousand five hundred fifty men.'),
  ('5edd63a1-981a-567d-a976-7e1b995f1cdc', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 27, 27, 'The one hundred talents of silver were for casting the sockets of the sanctuary, and the sockets of the veil; one hundred sockets for the one hundred talents, a talent for a socket.'),
  ('78bf96c1-98b1-56a9-a3b5-78a1ff80ef56', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 28, 28, 'Of the one thousand seven hundred seventy-five shekels he made hooks for the pillars, overlaid their capitals, and made fillets for them.'),
  ('f6eaf840-9a3f-5076-ace7-40b1134930fe', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 29, 29, 'The brass of the offering was seventy talents, and two thousand four hundred shekels.'),
  ('aea0a8b0-fa08-55a9-ab89-f46011bc505d', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 30, 30, 'With this he made the sockets to the door of the Tent of Meeting, the bronze altar, the bronze grating for it, all the vessels of the altar,'),
  ('4c4d6648-9ece-5552-aa7d-dbf8e0cc90ca', '22ee8044-76bc-5157-aa83-764779f8379c', NULL, 31, 31, 'the sockets around the court, the sockets of the gate of the court, all the pins of the tabernacle, and all the pins around the court.'),
  ('ac67b1dd-37d9-5323-a617-9ad1ca062473', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 1, 1, 'Of the blue, purple, and scarlet, they made finely worked garments, for ministering in the holy place, and made the holy garments for Aaron; as Yahweh commanded Moses.'),
  ('a4ce0a84-a6f2-531f-ad36-5489801d816f', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 2, 2, 'He made the ephod of gold, blue, purple, scarlet, and fine twined linen.'),
  ('03183a16-d7d6-5c0b-a8b2-b434c3d577e2', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 3, 3, 'They beat the gold into thin plates, and cut it into wires, to work it in the blue, in the purple, in the scarlet, and in the fine linen, the work of the skillful workman.'),
  ('c688bed9-a7ba-55a7-ae87-b726c1d27d00', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 4, 4, 'They made shoulder straps for it, joined together. At the two ends it was joined together.'),
  ('761272c0-d77f-5fd2-a73b-ef414e828ff6', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 5, 5, 'The skillfully woven band that was on it, with which to fasten it on, was of the same piece, like its work; of gold, of blue, purple, scarlet, and fine twined linen; as Yahweh commanded Moses.'),
  ('911a4eba-d6fa-5cd6-a372-f7b5eb9c9843', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 6, 6, 'They worked the onyx stones, enclosed in settings of gold, engraved with the engravings of a signet, according to the names of the children of Israel.'),
  ('ed785d9e-a98b-5ea5-a677-62ebb808b3c3', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 7, 7, 'He put them on the shoulder straps of the ephod, to be stones of memorial for the children of Israel, as Yahweh commanded Moses.'),
  ('eb9c33b3-1617-5165-a708-54695397c9d5', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 8, 8, 'He made the breastplate, the work of a skillful workman, like the work of the ephod; of gold, of blue, purple, scarlet, and fine twined linen.'),
  ('1f1eea90-d334-5f6f-a0dc-d092e8e1a04d', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 9, 9, 'It was square. They made the breastplate double. Its length was a span, and its breadth a span, being double.'),
  ('6431d119-2f16-55fc-abaa-5315d52c677b', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 10, 10, 'They set in it four rows of stones. A row of ruby, topaz, and beryl was the first row;'),
  ('312064a3-308e-51fe-a9a1-1583908629d9', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 11, 11, 'and the second row, a turquoise, a sapphire, and an emerald;'),
  ('b55f0b8d-4a1d-5b9d-a0b7-1f4ed508dd69', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 12, 12, 'and the third row, a jacinth, an agate, and an amethyst;'),
  ('4ea4eb28-ea0b-585e-a63d-3d5ca79e1d65', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 13, 13, 'and the fourth row, a chrysolite, an onyx, and a jasper. They were enclosed in gold settings.'),
  ('4dde7dc2-e50e-5ed4-a572-c59f51df3756', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 14, 14, 'The stones were according to the names of the children of Israel, twelve, according to their names; like the engravings of a signet, everyone according to his name, for the twelve tribes.'),
  ('94a577be-c5fc-5071-acd8-18141ffa92a8', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 15, 15, 'They made on the breastplate chains like cords, of braided work of pure gold.'),
  ('dcb5b92d-cad7-52ba-a950-c1455f3609d7', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 16, 16, 'They made two settings of gold, and two gold rings, and put the two rings on the two ends of the breastplate.'),
  ('21bec92d-3035-593d-ab24-3dea42956b73', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 17, 17, 'They put the two braided chains of gold in the two rings at the ends of the breastplate.'),
  ('ffc3dc29-a71c-59ce-a23f-9e72de7bddca', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 18, 18, 'The other two ends of the two braided chains they put on the two settings, and put them on the shoulder straps of the ephod, in its front.'),
  ('ed79a508-54a1-5ca4-a362-cb984bea2af5', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 19, 19, 'They made two rings of gold, and put them on the two ends of the breastplate, on its edge, which was toward the side of the ephod inward.'),
  ('a174f9f5-5874-5513-a00c-2d8a7f471a3c', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 20, 20, 'They made two rings of gold, and put them on the two shoulder straps of the ephod underneath, in its front, close by its coupling, above the skillfully woven band of the ephod.'),
  ('bc20d544-e27c-5a40-a543-21a251d1c6ac', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 21, 21, 'They bound the breastplate by its rings to the rings of the ephod with a lace of blue, that it might be on the skillfully woven band of the ephod, and that the breastplate might not come loose from the ephod, as Yahweh commanded Moses.'),
  ('b1047c66-8cdf-5343-a19b-9472134a8c7f', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 22, 22, 'He made the robe of the ephod of woven work, all of blue.'),
  ('efea038d-5568-5d26-a60b-95bca22cdf72', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 23, 23, 'The opening of the robe in its midst was like the opening of a coat of mail, with a binding around its opening, that it should not be torn.'),
  ('22a1398c-2f8d-586e-a992-6949a7dc1928', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 24, 24, 'They made on the skirts of the robe pomegranates of blue, purple, scarlet, and twined linen.'),
  ('18b61df2-67e3-5968-a5fa-94d2d8cc1a3f', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 25, 25, 'They made bells of pure gold, and put the bells between the pomegranates around the skirts of the robe, between the pomegranates;'),
  ('694d5ebb-68ea-534d-a004-9c43d6128fae', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 26, 26, 'a bell and a pomegranate, a bell and a pomegranate, around the skirts of the robe, to minister in, as Yahweh commanded Moses.'),
  ('7a61412d-7f58-5b7b-ac75-701abff23fa4', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 27, 27, 'They made the coats of fine linen of woven work for Aaron, and for his sons,'),
  ('d2a719e4-1a7c-5044-a91d-99607fef3a70', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 28, 28, 'and the turban of fine linen, and the linen headbands of fine linen, and the linen breeches of fine twined linen,'),
  ('f75782e1-488f-529e-adc5-11c2012e18cd', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 29, 29, 'and the sash of fine twined linen, and blue, and purple, and scarlet, the work of the embroiderer, as Yahweh commanded Moses.'),
  ('52a3117d-6651-5585-a23a-1a4fdfa1df72', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 30, 30, 'They made the plate of the holy crown of pure gold, and wrote on it a writing, like the engravings of a signet: "HOLY TO YAHWEH."'),
  ('55cfd696-4b22-50e5-a6bb-c2bdd869d983', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 31, 31, 'They tied to it a lace of blue, to fasten it on the turban above, as Yahweh commanded Moses.'),
  ('a40960d3-052a-5994-ad81-4fcb0a09dbac', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 32, 32, 'Thus all the work of the tabernacle of the Tent of Meeting was finished. The children of Israel did according to all that Yahweh commanded Moses; so they did.'),
  ('4dd95afb-a739-5be7-a7f0-eb1ff6af3872', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 33, 33, 'They brought the tabernacle to Moses, the tent, with all its furniture, its clasps, its boards, its bars, its pillars, its sockets,'),
  ('e7e65da2-1c6e-5a00-a272-a402bf56976f', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 34, 34, 'the covering of rams'' skins dyed red, the covering of sea cow hides, the veil of the screen,'),
  ('c0237f6e-3ae3-5f17-aa0c-03c4a5437497', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 35, 35, 'the ark of the testimony with its poles, the mercy seat,'),
  ('8bcdb907-6be6-592d-a439-f3b40d10a357', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 36, 36, 'the table, all its vessels, the show bread,'),
  ('c7b75c54-6da6-5bf4-ac0a-56f4d766560b', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 37, 37, 'the pure lampstand, its lamps, even the lamps to be set in order, all its vessels, the oil for the light,'),
  ('ec9cbb5a-7f63-526a-a489-89905fb478c7', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 38, 38, 'the golden altar, the anointing oil, the sweet incense, the screen for the door of the Tent,'),
  ('139795d4-5e83-5753-ac5f-70d8445a0312', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 39, 39, 'the bronze altar, its grating of brass, its poles, all of its vessels, the basin and its base,'),
  ('74cd0a93-8d8e-5750-a95a-74a39cb97ca0', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 40, 40, 'the hangings of the court, its pillars, its sockets, the screen for the gate of the court, its cords, its pins, all the instruments of the service of the tabernacle, for the Tent of Meeting,'),
  ('5d437a3e-3272-5096-ad1a-71694ab55689', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 41, 41, 'the finely worked garments for ministering in the holy place, the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest''s office.'),
  ('c348b84b-7ac8-593e-ad06-c52e8220f263', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 42, 42, 'According to all that Yahweh commanded Moses, so the children of Israel did all the work.'),
  ('8d869b0c-04b6-5713-a9c6-8cab0762c8be', '97ab34f7-34f7-5549-a405-a80df5b61155', NULL, 43, 43, 'Moses saw all the work, and behold, they had done it as Yahweh had commanded, even so had they done it: and Moses blessed them.'),
  ('0676d3b0-8917-59a0-a3e7-12fb74d5d505', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('5f845944-de5d-583b-a3e9-e084344badd9', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 2, 2, '"On the first day of the first month you shall raise up the tabernacle of the Tent of Meeting.'),
  ('3e7d0f19-cf8a-54d0-ad65-ac9aaa034a0f', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 3, 3, 'You shall put the ark of the testimony in it, and you shall screen the ark with the veil.'),
  ('ea26cd5b-80cd-5917-ac5c-570c94f442f9', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 4, 4, 'You shall bring in the table, and set in order the things that are on it. You shall bring in the lampstand, and light its lamps.'),
  ('9611b76e-efd1-5077-aa26-5a71b2387a97', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 5, 5, 'You shall set the golden altar for incense before the ark of the testimony, and put the screen of the door to the tabernacle.'),
  ('f4ccf14c-c8ed-5202-aea3-b802a11113e4', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 6, 6, '"You shall set the altar of burnt offering before the door of the tabernacle of the Tent of Meeting.'),
  ('768c6f9b-cfe0-5797-aa83-40e4c431c799', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 7, 7, 'You shall set the basin between the Tent of Meeting and the altar, and shall put water therein.'),
  ('f03cd7d3-11a2-5764-a82b-d623109b3228', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 8, 8, 'You shall set up the court around it, and hang up the screen of the gate of the court.'),
  ('d4a77914-20ce-52aa-ac0a-cc22800d662b', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 9, 9, '"You shall take the anointing oil, and anoint the tabernacle, and all that is in it, and shall make it holy, and all its furniture: and it will be holy.'),
  ('2e897bb4-3bde-54fd-afbf-307a5aac7eaf', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 10, 10, 'You shall anoint the altar of burnt offering, with all its vessels, and sanctify the altar: and the altar will be most holy.'),
  ('0082f1bc-9ddd-57b7-af2c-9848926e557c', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 11, 11, 'You shall anoint the basin and its base, and sanctify it.'),
  ('d33fe195-ac7a-5f83-af4a-d58ff8b0a7b2', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 12, 12, '"You shall bring Aaron and his sons to the door of the Tent of Meeting, and shall wash them with water.'),
  ('513db1a0-46dd-5029-af45-c1f31639a7e2', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 13, 13, 'You shall put on Aaron the holy garments; and you shall anoint him, and sanctify him, that he may minister to me in the priest''s office.'),
  ('ad086dcd-08cf-50be-ac37-774d4a41a41b', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 14, 14, 'You shall bring his sons, and put coats on them.'),
  ('414ab1bc-6f46-59ae-a4fa-56deea925ed9', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 15, 15, 'You shall anoint them, as you anointed their father, that they may minister to me in the priest''s office. Their anointing shall be to them for an everlasting priesthood throughout their generations."'),
  ('1689b191-f373-5279-ad61-8726f6f95d6d', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 16, 16, 'Moses did so. According to all that Yahweh commanded him, so he did.'),
  ('04c93c8f-cff9-5c46-a94d-baa663815e7b', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 17, 17, 'It happened in the first month in the second year, on the first day of the month, that the tabernacle was raised up.'),
  ('60b1ddee-d75c-5e64-a391-0c4cfcf6a4c3', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 18, 18, 'Moses raised up the tabernacle, and laid its sockets, and set up its boards, and put in its bars, and raised up its pillars.'),
  ('35df5648-3734-5d11-af1e-b1dc703e3cc8', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 19, 19, 'He spread the covering over the tent, and put the roof of the tabernacle above on it, as Yahweh commanded Moses.'),
  ('4508284b-2c5a-5d1a-a695-7bdff4cd1513', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 20, 20, 'He took and put the testimony into the ark, and set the poles on the ark, and put the mercy seat above on the ark.'),
  ('8e75464f-465b-52ce-a91d-3666667ba057', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 21, 21, 'He brought the ark into the tabernacle, and set up the veil of the screen, and screened the ark of the testimony, as Yahweh commanded Moses.'),
  ('ec3bee3f-d327-52af-aae3-778473314699', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 22, 22, 'He put the table in the Tent of Meeting, on the side of the tabernacle northward, outside of the veil.'),
  ('faa0e95d-0936-5421-a777-5b97050a5751', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 23, 23, 'He set the bread in order on it before Yahweh, as Yahweh commanded Moses.'),
  ('b5ff3b95-e61c-5a9e-ab36-64b9dbedd1b6', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 24, 24, 'He put the lampstand in the Tent of Meeting, opposite the table, on the side of the tabernacle southward.'),
  ('c7560258-e85c-5985-aef7-77cbe461fd3b', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 25, 25, 'He lit the lamps before Yahweh, as Yahweh commanded Moses.'),
  ('c71cbeec-1bcd-5c90-a791-9f38759dc307', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 26, 26, 'He put the golden altar in the Tent of Meeting before the veil;'),
  ('45fdf55d-8073-54de-abe2-cadc17993586', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 27, 27, 'and he burnt incense of sweet spices on it, as Yahweh commanded Moses.'),
  ('d5932080-3c82-516a-a271-ddb395928d0e', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 28, 28, 'He put up the screen of the door to the tabernacle.'),
  ('a256278e-72b2-5187-a7bd-83ae25a0d4bb', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 29, 29, 'He set the altar of burnt offering at the door of the tabernacle of the Tent of Meeting, and offered on it the burnt offering and the meal offering, as Yahweh commanded Moses.'),
  ('6a87d5bd-0e79-53f9-a15f-a623d58915d5', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 30, 30, 'He set the basin between the Tent of Meeting and the altar, and put water therein, with which to wash.'),
  ('523648b6-9c82-5d12-a41b-1e8d0c7fe429', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 31, 31, 'Moses, Aaron, and his sons washed their hands and their feet there.'),
  ('6057e412-0556-5d11-ac2e-c0f1041d29f7', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 32, 32, 'When they went into the Tent of Meeting, and when they came near to the altar, they washed, as Yahweh commanded Moses.'),
  ('39c16a05-1f5d-569c-a719-95ff52b92603', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 33, 33, 'He raised up the court around the tabernacle and the altar, and set up the screen of the gate of the court. So Moses finished the work.'),
  ('7be47b24-00f3-554c-a988-c56033320a63', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 34, 34, 'Then the cloud covered the Tent of Meeting, and the glory of Yahweh filled the tabernacle.'),
  ('7fab8e46-6d82-548c-a488-70e6d3e21998', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 35, 35, 'Moses wasn''t able to enter into the Tent of Meeting, because the cloud stayed on it, and Yahweh''s glory filled the tabernacle.'),
  ('4b476048-b213-5d1e-a836-5bf52f556f37', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 36, 36, 'When the cloud was taken up from over the tabernacle, the children of Israel went onward, throughout all their journeys;'),
  ('3e2fb38d-8165-5af2-ab2f-2baee0dc6712', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 37, 37, 'but if the cloud wasn''t taken up, then they didn''t travel until the day that it was taken up.'),
  ('6b7a9bf5-bbad-50eb-a25f-8029b883bc40', 'b9f02ac7-ee07-5b09-a8cf-cc5e15643023', NULL, 38, 38, 'For the cloud of Yahweh was on the tabernacle by day, and there was fire in the cloud by night, in the sight of all the house of Israel, throughout all their journeys.'),
  ('5e9f3c8a-2175-57bd-a100-13b4d50986ba', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 1, 1, 'Yahweh called to Moses, and spoke to him out of the Tent of Meeting, saying,'),
  ('36eb8e0f-cd5b-5c2a-ad0a-bc173bc3c20a', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 2, 2, '"Speak to the children of Israel, and tell them, ''When anyone of you offers an offering to Yahweh, you shall offer your offering of the livestock, from the herd and from the flock.'),
  ('0e8000e2-15d7-5d97-a332-7dd6a05dd438', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 3, 3, '"''If his offering is a burnt offering from the herd, he shall offer a male without blemish. He shall offer it at the door of the Tent of Meeting, that he may be accepted before Yahweh.'),
  ('82e0b35b-5474-516c-a956-e108f28dd0d8', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 4, 4, 'He shall lay his hand on the head of the burnt offering, and it shall be accepted for him to make atonement for him.'),
  ('f1a38a99-61ba-54e0-a415-b0f9ca7a5209', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 5, 5, 'He shall kill the bull before Yahweh. Aaron''s sons, the priests, shall present the blood and sprinkle the blood around on the altar that is at the door of the Tent of Meeting.'),
  ('dccf3bb2-5baf-55bd-aeca-ca3fb652ade1', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 6, 6, 'He shall flay the burnt offering, and cut it into pieces.'),
  ('2fb9d2ba-1f33-5f86-a23a-9cfdb697b3d8', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 7, 7, 'The sons of Aaron the priest shall put fire on the altar, and lay wood in order on the fire;'),
  ('f204f588-a69e-5b45-a5a7-a6c1364398f9', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 8, 8, 'and Aaron''s sons, the priests, shall lay the pieces, the head, and the fat in order on the wood that is on the fire which is on the altar;'),
  ('1c1d5b1a-0b7e-5d69-a45a-e93497f0a5e4', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 9, 9, 'but its innards and its legs he shall wash with water. The priest shall burn the whole on the altar, for a burnt offering, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('406d9d1a-7017-5d2f-a38c-ed34db188ed1', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 10, 10, '"''If his offering is from the flock, from the sheep, or from the goats, for a burnt offering, he shall offer a male without blemish.'),
  ('ae8c9c02-be63-51ff-a3fb-6573b4c56797', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 11, 11, 'He shall kill it on the north side of the altar before Yahweh. Aaron''s sons, the priests, shall sprinkle its blood around on the altar.'),
  ('6deb6024-a203-5816-a57b-13d91b529893', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 12, 12, 'He shall cut it into its pieces, with its head and its fat. The priest shall lay them in order on the wood that is on the fire which is on the altar,'),
  ('e1a6827d-19bd-5732-aea2-927a62a3c03f', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 13, 13, 'but the innards and the legs he shall wash with water. The priest shall offer the whole, and burn it on the altar. It is a burnt offering, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('03de821b-ebef-5857-ac34-c751feccd7d7', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 14, 14, '"''If his offering to Yahweh is a burnt offering of birds, then he shall offer his offering of turtledoves, or of young pigeons.'),
  ('0bb6f8ae-5034-5414-a9fc-f6b9eb4309d5', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 15, 15, 'The priest shall bring it to the altar, and wring off its head, and burn it on the altar; and its blood shall be drained out on the side of the altar;'),
  ('8d3988d6-8c19-59af-afd1-fa4a3184c6c9', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 16, 16, 'and he shall take away its crop with its filth, and cast it beside the altar on the east part, in the place of the ashes.'),
  ('22e5ee38-6a5d-581c-a215-cdbd2b33a26e', 'f869195f-33bd-52b9-a459-c51f2ef11c23', NULL, 17, 17, 'He shall tear it by its wings, but shall not divide it apart. The priest shall burn it on the altar, on the wood that is on the fire. It is a burnt offering, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('cab11231-9496-58d7-a471-776991f71e10', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 1, 1, '"''When anyone offers an offering of a meal offering to Yahweh, his offering shall be of fine flour; and he shall pour oil on it, and put frankincense on it.'),
  ('c548c1a0-a938-5214-a6e2-1e91ba796c3f', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 2, 2, 'He shall bring it to Aaron''s sons, the priests; and he shall take his handful of its fine flour, and of its oil, with all its frankincense; and the priest shall burn its memorial on the altar, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('2dad026f-ae1e-51f8-a470-eb91f221c8fb', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 3, 3, 'That which is left of the meal offering shall be Aaron''s and his sons''. It is a most holy thing of the offerings of Yahweh made by fire.'),
  ('814ccd3b-a6a8-5a81-a901-6703a8401b9d', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 4, 4, '"''When you offer an offering of a meal offering baked in the oven, it shall be unleavened cakes of fine flour mixed with oil, or unleavened wafers anointed with oil.'),
  ('1322eac3-e8dd-5758-a761-44d0c0b47c1d', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 5, 5, 'If your offering is a meal offering of the griddle, it shall be of unleavened fine flour, mixed with oil.'),
  ('12730531-4fd1-5bf4-af67-cbbf7f623797', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 6, 6, 'You shall cut it in pieces, and pour oil on it. It is a meal offering.'),
  ('b7214b02-1943-5309-aea9-9c2b30d25934', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 7, 7, 'If your offering is a meal offering of the pan, it shall be made of fine flour with oil.'),
  ('f840702b-9c7f-5c57-a1f7-a1ac90c5ad8a', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 8, 8, 'You shall bring the meal offering that is made of these things to Yahweh: and it shall be presented to the priest, and he shall bring it to the altar.'),
  ('be21a584-12de-509f-a25c-df7c4091190d', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 9, 9, 'The priest shall take from the meal offering its memorial, and shall burn it on the altar, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('fc906b1d-31f7-5fc1-a5a0-aeb201165955', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 10, 10, 'That which is left of the meal offering shall be Aaron''s and his sons''. It is a thing most holy of the offerings of Yahweh made by fire.'),
  ('a2a6ce2c-828b-5ce1-ad81-ac52d76a56dd', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 11, 11, '"''No meal offering, which you shall offer to Yahweh, shall be made with yeast; for you shall burn no yeast, nor any honey, as an offering made by fire to Yahweh.'),
  ('0e923e7f-bfc8-5ef4-a63b-d9c011f5beca', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 12, 12, 'As an offering of firstfruits you shall offer them to Yahweh: but they shall not ascend for a pleasant aroma on the altar.'),
  ('3692d3fe-4bb8-5a01-a69c-c33b187525d8', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 13, 13, 'Every offering of your meal offering you shall season with salt; neither shall you allow the salt of the covenant of your God to be lacking from your meal offering. With all your offerings you shall offer salt.'),
  ('35e4244b-0fc9-5bd6-a693-a3ffad975038', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 14, 14, '"''If you offer a meal offering of first fruits to Yahweh, you shall offer for the meal offering of your first fruits grain in the ear parched with fire, bruised grain of the fresh ear.'),
  ('3aef10bb-aab2-5f21-a0f8-91b5561ea819', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 15, 15, 'You shall put oil on it, and lay frankincense on it: it is a meal offering.'),
  ('a42cd37d-53a6-566e-a698-a16cfa783e06', 'ac0973f8-e1b3-5f3c-ae46-9aea7e7dc119', NULL, 16, 16, 'The priest shall burn as its memorial, part of its bruised grain, and part of its oil, along with all its frankincense: it is an offering made by fire to Yahweh.'),
  ('ca21d67c-43c8-5e62-a36a-785720413d3a', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 1, 1, '"''If his offering is a sacrifice of peace offerings; if he offers it from the herd, whether male or female, he shall offer it without blemish before Yahweh.'),
  ('8a763ca5-9fe3-5551-abf1-2b8a39fb1b9b', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 2, 2, 'He shall lay his hand on the head of his offering, and kill it at the door of the Tent of Meeting: and Aaron''s sons, the priests shall sprinkle the blood around on the altar.'),
  ('cb2ed187-cffb-54f4-ad31-3796cf75acd1', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 3, 3, 'He shall offer of the sacrifice of peace offerings an offering made by fire to Yahweh; the fat that covers the innards, and all the fat that is on the innards,'),
  ('330b2bf1-66fc-55cf-a469-d5a0d66bf674', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 4, 4, 'and the two kidneys, and the fat that is on them, which is by the loins, and the cover on the liver, with the kidneys, he shall take away.'),
  ('4a0aca00-6d66-5537-af31-e705a5d64181', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 5, 5, 'Aaron''s sons shall burn it on the altar on the burnt offering, which is on the wood that is on the fire: it is an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('92238f65-a6c2-515a-a425-a596ac38a881', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 6, 6, '"''If his offering for a sacrifice of peace offerings to Yahweh is from the flock; male or female, he shall offer it without blemish.'),
  ('76e47c5a-6fe1-5160-a1ef-30332b0761d2', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 7, 7, 'If he offers a lamb for his offering, then he shall offer it before Yahweh;'),
  ('4a8c14b1-7bbc-5c41-a048-0f3c6c3b62ff', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 8, 8, 'and he shall lay his hand on the head of his offering, and kill it before the Tent of Meeting: and Aaron''s sons shall sprinkle its blood around on the altar.'),
  ('6b888059-630b-5cf6-addd-74cb8917e3e1', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 9, 9, 'He shall offer from the sacrifice of peace offerings an offering made by fire to Yahweh; its fat, the entire tail fat, he shall take away close to the backbone; and the fat that covers the inwards, and all the fat that is on the inwards,'),
  ('dedd65c2-3302-547d-ad25-682a1adceede', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 10, 10, 'and the two kidneys, and the fat that is on them, which is by the loins, and the cover on the liver, with the kidneys, he shall take away.'),
  ('f49036bc-4434-5eff-ac1c-45d5d7457d73', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 11, 11, 'The priest shall burn it on the altar: it is the food of the offering made by fire to Yahweh.'),
  ('c026c81c-8cc5-511b-aea6-57ee5e4f9df9', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 12, 12, '"''If his offering is a goat, then he shall offer it before Yahweh:'),
  ('4a0f7900-87fa-5f8d-a511-39cd5e342547', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 13, 13, 'and he shall lay his hand on its head, and kill it before the Tent of Meeting; and the sons of Aaron shall sprinkle its blood around on the altar.'),
  ('bd0a054b-5c05-5dfb-a1b7-2ce50ba56719', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 14, 14, 'He shall offer from it as his offering, an offering made by fire to Yahweh; the fat that covers the innards, and all the fat that is on the innards,'),
  ('d896a02e-e422-54e3-a298-97faf2bb8700', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 15, 15, 'and the two kidneys, and the fat that is on them, which is by the loins, and the cover on the liver, with the kidneys, he shall take away.'),
  ('cc13bf09-4102-550c-a755-9acdb297512d', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 16, 16, 'The priest shall burn them on the altar: it is the food of the offering made by fire, for a pleasant aroma; all the fat is Yahweh''s.'),
  ('7718d179-bf58-5229-a709-d67ed421f54c', 'd23920c4-149a-5a49-a32a-90eb48cd1acd', NULL, 17, 17, '"''It shall be a perpetual statute throughout your generations in all your dwellings, that you shall eat neither fat nor blood.''"'),
  ('7a140e62-4d07-5598-a05a-a0b8c4fa31ad', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('559bf700-e6d0-5a9b-a8e9-001039b647ef', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 2, 2, '"Speak to the children of Israel, saying, ''If anyone sins unintentionally, in any of the things which Yahweh has commanded not to be done, and does any one of them:'),
  ('177c6db2-7236-5a09-a5e2-b1ef99f86a67', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 3, 3, 'if the anointed priest sins so as to bring guilt on the people, then let him offer for his sin, which he has sinned, a young bull without blemish to Yahweh for a sin offering.'),
  ('f0e4915e-7a91-54c7-a44b-57d70b55261f', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 4, 4, 'He shall bring the bull to the door of the Tent of Meeting before Yahweh; and he shall lay his hand on the head of the bull, and kill the bull before Yahweh.'),
  ('14f22df4-5b43-5ab8-a799-959b999adeaf', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 5, 5, 'The anointed priest shall take some of the blood of the bull, and bring it to the Tent of Meeting.'),
  ('acb87205-903d-50cc-a1c6-2027f4d9d5e9', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 6, 6, 'The priest shall dip his finger in the blood, and sprinkle some of the blood seven times before Yahweh, before the veil of the sanctuary.'),
  ('ad7617ee-aed1-5953-ac7c-02b4521d9371', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 7, 7, 'The priest shall put some of the blood on the horns of the altar of sweet incense before Yahweh, which is in the Tent of Meeting; and he shall pour out all of rest of the blood of the bull at the base of the altar of burnt offering, which is at the door of the Tent of Meeting.'),
  ('d48fb86f-bab5-5679-aa27-37b8e93e09b0', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 8, 8, 'He shall take all the fat of the bull of the sin offering off of it; the fat that covers the innards, and all the fat that is on the innards,'),
  ('61e2d1d9-3fb7-5511-a893-bf2bdff98eea', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 9, 9, 'and the two kidneys, and the fat that is on them, which is by the loins, and the cover on the liver, with the kidneys, he shall take away,'),
  ('f6a47269-6a3b-5003-aa81-6cfc9521d7c0', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 10, 10, 'as it is taken off of the bull of the sacrifice of peace offerings. The priest shall burn them on the altar of burnt offering.'),
  ('703a3f14-209f-5766-a8f0-5bab2299686c', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 11, 11, 'The bull''s skin, all its flesh, with its head, and with its legs, its innards, and its dung,'),
  ('434f430c-da90-5118-aa7c-8a35b5414427', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 12, 12, 'even the whole bull shall he carry forth outside the camp to a clean place, where the ashes are poured out, and burn it on wood with fire. Where the ashes are poured out it shall be burned.'),
  ('16f556d5-2915-5543-af99-643d335ef444', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 13, 13, '"''If the whole congregation of Israel sins, and the thing is hidden from the eyes of the assembly, and they have done any of the things which Yahweh has commanded not to be done, and are guilty;'),
  ('6b700e99-dfea-58d4-a652-eb00eb4a027a', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 14, 14, 'when the sin in which they have sinned is known, then the assembly shall offer a young bull for a sin offering, and bring it before the Tent of Meeting.'),
  ('f22699ee-a78f-5d8e-a8d5-2ab44bbb9321', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 15, 15, 'The elders of the congregation shall lay their hands on the head of the bull before Yahweh; and the bull shall be killed before Yahweh.'),
  ('3b8b685a-6d6f-5906-a79a-74e40066610f', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 16, 16, 'The anointed priest shall bring of the blood of the bull to the Tent of Meeting:'),
  ('f6ac500a-927a-583d-adb6-f6dc6ba5d762', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 17, 17, 'and the priest shall dip his finger in the blood, and sprinkle it seven times before Yahweh, before the veil.'),
  ('5d74083a-2fb5-5f6d-ac72-85061531043f', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 18, 18, 'He shall put some of the blood on the horns of the altar which is before Yahweh, that is in the Tent of Meeting; and the rest of the blood he shall pour out at the base of the altar of burnt offering, which is at the door of the Tent of Meeting.'),
  ('09a079f5-8b55-5886-afe8-9859d25ffd0c', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 19, 19, 'All its fat he shall take from it, and burn it on the altar.'),
  ('35e4a7cc-adf2-595a-a376-3f350c025c4f', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 20, 20, 'Thus shall he do with the bull; as he did with the bull of the sin offering, so shall he do with this; and the priest shall make atonement for them, and they shall be forgiven.'),
  ('2bbfccc4-3a9c-5817-a4a1-b58afb6514d6', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 21, 21, 'He shall carry forth the bull outside the camp, and burn it as he burned the first bull. It is the sin offering for the assembly.'),
  ('74bc4062-4daa-5bcf-a355-d7298d1bcd9d', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 22, 22, '"''When a ruler sins, and unwittingly does any one of all the things which Yahweh his God has commanded not to be done, and is guilty;'),
  ('90e5b432-a046-57f4-a391-bdc363880071', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 23, 23, 'if his sin, in which he has sinned, is made known to him, he shall bring as his offering a goat, a male without blemish.'),
  ('6f8174dc-47eb-5c5b-a384-d5a92c7df4db', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 24, 24, 'He shall lay his hand on the head of the goat, and kill it in the place where they kill the burnt offering before Yahweh. It is a sin offering.'),
  ('9f866539-7451-524b-a499-7da12f5d122c', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 25, 25, 'The priest shall take some of the blood of the sin offering with his finger, and put it on the horns of the altar of burnt offering. He shall pour out the rest of its blood at the base of the altar of burnt offering.'),
  ('601586e1-1f6e-5fb9-a889-39970f5b15dd', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 26, 26, 'All its fat he shall burn on the altar, like the fat of the sacrifice of peace offerings; and the priest shall make atonement for him concerning his sin, and he will be forgiven.'),
  ('87cd1c80-00d9-5da2-abc7-7b1dd89062f7', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 27, 27, '"''If anyone of the common people sins unwittingly, in doing any of the things which Yahweh has commanded not to be done, and is guilty;'),
  ('9b7927cb-896a-5d73-a6f6-c58d2cdd07dc', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 28, 28, 'if his sin, which he has sinned, is made known to him, then he shall bring for his offering a goat, a female without blemish, for his sin which he has sinned.'),
  ('cc528bc7-ad9b-5827-a120-e736b1077125', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 29, 29, 'He shall lay his hand on the head of the sin offering, and kill the sin offering in the place of burnt offering.'),
  ('2d12b59d-b4e1-5717-a54a-154406569c1a', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 30, 30, 'The priest shall take some of its blood with his finger, and put it on the horns of the altar of burnt offering; and the rest of its blood he shall pour out at the base of the altar.'),
  ('79879949-9f88-558d-a960-9c84dd91dd46', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 31, 31, 'All its fat he shall take away, like the fat is taken away from off of the sacrifice of peace offerings; and the priest shall burn it on the altar for a pleasant aroma to Yahweh; and the priest shall make atonement for him, and he will be forgiven.'),
  ('459182f1-b62e-5656-a772-a1cb3e10210b', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 32, 32, '"''If he brings a lamb as his offering for a sin offering, he shall bring a female without blemish.'),
  ('4f6892a9-a3e5-52fc-a307-d8a958570f22', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 33, 33, 'He shall lay his hand on the head of the sin offering, and kill it for a sin offering in the place where they kill the burnt offering.'),
  ('83b6c91b-8ef2-503d-ab26-2fc46d6984e2', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 34, 34, 'The priest shall take some of the blood of the sin offering with his finger, and put it on the horns of the altar of burnt offering; and all the rest of its blood he shall pour out at the base of the altar.'),
  ('2fc20315-84f6-5a5e-a059-16d129acd39f', 'ee1f495a-d16f-5afa-a9e9-07d0580565a3', NULL, 35, 35, 'All its fat he shall take away, like the fat of the lamb is taken away from the sacrifice of peace offerings; and the priest shall burn them on the altar, on the offerings of Yahweh made by fire; and the priest shall make atonement for him concerning his sin that he has sinned, and he will be forgiven.'),
  ('fd98632e-844c-5670-a982-386df8b8b0d1', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 1, 1, '"''If anyone sins, in that he hears the voice of adjuration, he being a witness, whether he has seen or known, if he doesn''t report it, then he shall bear his iniquity.'),
  ('86c029cd-a8da-58d7-aed2-5a54338673ae', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 2, 2, '"''Or if anyone touches any unclean thing, whether it is the carcass of an unclean animal, or the carcass of unclean livestock, or the carcass of unclean creeping things, and it is hidden from him, and he is unclean, then he shall be guilty.'),
  ('bbc03bf2-a5d8-5a01-a228-9cfd1e2c4cf3', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 3, 3, '"''Or if he touches the uncleanness of man, whatever his uncleanness is with which he is unclean, and it is hidden from him; when he knows of it, then he shall be guilty.'),
  ('2fb29aec-9931-5943-ad61-a4cb738812b4', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 4, 4, '"''Or if anyone swears rashly with his lips to do evil, or to do good, whatever it is that a man might utter rashly with an oath, and it is hidden from him; when he knows of it, then he shall be guilty of one of these.'),
  ('cf2aa3fb-e784-5c44-a769-7b7329423699', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 5, 5, 'It shall be, when he is guilty of one of these, he shall confess that in which he has sinned:'),
  ('d8457915-7652-5a9b-a883-f8d4df7b2013', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 6, 6, 'and he shall bring his trespass offering to Yahweh for his sin which he has sinned, a female from the flock, a lamb or a goat, for a sin offering; and the priest shall make atonement for him concerning his sin.'),
  ('f90ae85a-281f-5b9a-ab45-ac227b770471', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 7, 7, '"''If he can''t afford a lamb, then he shall bring his trespass offering for that in which he has sinned, two turtledoves, or two young pigeons, to Yahweh; one for a sin offering, and the other for a burnt offering.'),
  ('7d817693-d0d3-5bc3-a760-b01b23dfbaea', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 8, 8, 'He shall bring them to the priest, who shall first offer the one which is for the sin offering, and wring off its head from its neck, but shall not sever it completely.'),
  ('1dffbb44-f95b-52fe-a79d-1b0e8a92a44a', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 9, 9, 'He shall sprinkle some of the blood of the sin offering on the side of the altar; and the rest of the blood shall be drained out at the base of the altar. It is a sin offering.'),
  ('d3b45ab2-20a1-5c99-a261-5cd75450f5ba', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 10, 10, 'He shall offer the second for a burnt offering, according to the ordinance; and the priest shall make atonement for him concerning his sin which he has sinned, and he shall be forgiven.'),
  ('a83b12f8-bf20-5516-a475-057eb065f65d', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 11, 11, '"''But if he can''t afford two turtledoves, or two young pigeons, then he shall bring his offering for that in which he has sinned, the tenth part of an ephah of fine flour for a sin offering. He shall put no oil on it, neither shall he put any frankincense on it, for it is a sin offering.'),
  ('720f5552-77b4-5a92-a643-37a03ac1880f', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 12, 12, 'He shall bring it to the priest, and the priest shall take his handful of it as the memorial portion, and burn it on the altar, on the offerings of Yahweh made by fire. It is a sin offering.'),
  ('dc8ea3f0-97d8-5851-a078-23c4d22649d4', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 13, 13, 'The priest shall make atonement for him concerning his sin that he has sinned in any of these things, and he will be forgiven; and the rest shall be the priest''s, as the meal offering.''"'),
  ('86d6ebd9-b205-5846-a942-863a7e81898b', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 14, 14, 'Yahweh spoke to Moses, saying,'),
  ('cb574784-9d3e-5676-add2-3bd18657234b', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 15, 15, '"If anyone commits a trespass, and sins unwittingly, in the holy things of Yahweh; then he shall bring his trespass offering to Yahweh, a ram without blemish from the flock, according to your estimation in silver by shekels, after the shekel of the sanctuary, for a trespass offering.'),
  ('3fdf0222-519d-5183-acdb-095fc94d9996', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 16, 16, 'He shall make restitution for that which he has done wrong in the holy thing, and shall add a fifth part to it, and give it to the priest; and the priest shall make atonement for him with the ram of the trespass offering, and he will be forgiven.'),
  ('5bb29c97-8557-5f55-a305-0c8f448d34aa', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 17, 17, '"If anyone sins, and does any of the things which Yahweh has commanded not to be done; though he didn''t know it, yet he is guilty, and shall bear his iniquity.'),
  ('a8431688-205f-55dd-a0b9-9489a31b4b73', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 18, 18, 'He shall bring a ram without blemish from of the flock, according to your estimation, for a trespass offering, to the priest; and the priest shall make atonement for him concerning the thing in which he sinned and didn''t know it, and he will be forgiven.'),
  ('c135b71a-2d67-5d6a-a539-fe33eff0c638', 'e6f27f05-97cb-51d5-a92e-9411a0e109b3', NULL, 19, 19, 'It is a trespass offering. He is certainly guilty before Yahweh."'),
  ('103fe564-49b6-523d-aebc-9764956bcbd4', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('c1bcaa51-f860-5917-af8c-dca9d78ae39d', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 2, 2, '"If anyone sins, and commits a trespass against Yahweh, and deals falsely with his neighbor in a matter of deposit, or of bargain, or of robbery, or has oppressed his neighbor,'),
  ('3ab137cc-d176-51e3-ac8a-a3005bc2fb1e', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 3, 3, 'or has found that which was lost, and dealt falsely therein, and swearing to a lie; in any of all these things that a man does, sinning therein;'),
  ('743b0153-621b-536a-a755-bfaa2b122eb2', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 4, 4, 'then it shall be, if he has sinned, and is guilty, he shall restore that which he took by robbery, or the thing which he has gotten by oppression, or the deposit which was committed to him, or the lost thing which he found,'),
  ('e31b41b5-95a8-56b2-a3f2-84cbee1a614d', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 5, 5, 'or any thing about which he has sworn falsely; he shall restore it even in full, and shall add a fifth part more to it. To him to whom it belongs he shall give it, in the day of his being found guilty.'),
  ('1143ae65-1986-53bf-abd6-2f2e311c9d1e', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 6, 6, 'He shall bring his trespass offering to Yahweh, a ram without blemish from the flock, according to your estimation, for a trespass offering, to the priest.'),
  ('ee81c8d7-93f2-56c5-a035-36de2edf026e', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 7, 7, 'The priest shall make atonement for him before Yahweh, and he will be forgiven concerning whatever he does to become guilty."'),
  ('224285db-e9eb-566a-a5b6-4ddb37d5f9a6', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 8, 8, 'Yahweh spoke to Moses, saying,'),
  ('a0de6cb1-8e36-5688-a38a-82dbca28299f', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 9, 9, '"Command Aaron and his sons, saying, ''This is the law of the burnt offering: the burnt offering shall be on the hearth on the altar all night until the morning; and the fire of the altar shall be kept burning on it.'),
  ('868e90a8-ba9e-56b1-a868-6e82bb43c052', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 10, 10, 'The priest shall put on his linen garment, and he shall put on his linen breeches upon his body; and he shall remove the ashes from where the fire has consumed the burnt offering on the altar, and he shall put them beside the altar.'),
  ('8a1d780f-986a-50b3-a7bb-4f7a72be8ae3', 'a5fadd46-8a69-52eb-a1de-41a233705d54', NULL, 11, 11, 'He shall take off his garments, and put on other garments, and carry the ashes outside the camp to a clean place.')
